      VALUES (1316, '{"characterId":1316,"captainAbility":"Boosts ATK of all characters by 2.5x after the 2nd PERFECT in a row and by 3.5x after the 5th PERFECT in a row.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 2.5x after the 2nd PERFECT in a row and by 3.5x after the 5th PERFECT in a row."}],"captainNotes":null,"specialName":"Echoing Cry of the Soul","specialText":"If HP is below 3,000, reduces No Healing debuff duration by 1 turn. Recovers 3x character''s RCV in HP. If HP is below 3,000, reduces No Healing debuff duration by 3 turns. Recovers 6x character''s RCV in HP. If HP is below 3,000, removes No Healing debuff duration completely. Recovers 13x character''s RCV in HP","specialNotes":"No Healing debuff completely stops healing abilities. This is the debuff used in Akainu raid. #{stages}","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["petty officer coby","coby"],"characterTags":[],"builderAbilities":[{"key":"remove_no_healing","label":"Remove No Healing","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_no_healing","label":"Remove No Healing","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_no_healing","label":"Remove No Healing","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_blindness","label":"Remove Blindness","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sail