      INSERT INTO character_details (character_id, detail_json)
      VALUES (1880, '{"characterId":1880,"captainAbility":"If your crew has 6 Powerhouse characters, Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, reduces crew''s current HP by 10% at the end of each turn, boosts ATK of Powerhouse characters by 3.25x. Boosts HP of Powerhouse characters by 1.1x-2x depending on how many Powerhouse characters are in your crew.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"If your crew has 6 Powerhouse characters, Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, reduces crew''s current HP by 10% at the end of each turn, boosts ATK of Powerhouse characters by 3.25x. Boosts HP of Powerhouse characters by 1.1x-2x depending on how many Powerhouse characters are in your crew."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"If your crew has 6 Powerhouse characters, Reduces Special Cooldown of Powerhouse characters by 3 turns at the start of the fight, reduces crew''s current HP by 10% at the end of each turn, boosts ATK of Powerhouse characters by 3.5x. Boosts HP of Powerhouse characters by ?x-2.5x depending on how many Powerhouse characters are in your crew."}],"captainNotes":"Hody''s HP boost is dependent on how many Powerhouse characters are in your crew. With 6 Powerhouse characters, the boost is 2x, with 5 the boost is 1.5x, with 4 the boost is 1.4x, with 3 the boost is 1.3x, with 2 the boost is 1.2x and with 1 the boost is 1.1x. [BASED ON 6*]","specialName":"Shark Pack","specialText":"Deals 10x character''s ATK in [INT] True damage to all enemies, reduces Special Cooldown of Powerhouse characters by 1 turn, reduces damage received by 60% for 1 turn. Deals 60x character''s ATK in [INT] True damage to all enemies, reduces Special Cooldown of Powerhouse characters by 2 turns, reduces damage received by 90% for 1 turn","specialNotes":"#{ignoreBarrier}. #{stages}. 1 time: lower multiplier boost, 2+ times: