      INSERT INTO character_details (character_id, detail_json)
      VALUES (2232, '{"characterId":2232,"captainAbility":"Reduces HP of all characters by 20%, reduces damage received by 13%, boosts chances of getting [RCV] orbs, makes [RCV] orbs beneficial for all characters, boosts ATK of all characters by 2x-3.75x depending on the amount healed in the last turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces HP of all characters by 20%, reduces damage received by 13%, boosts chances of getting [RCV] orbs, makes [RCV] orbs beneficial for all characters, boosts ATK of all characters by 2x-3.75x depending on the amount healed in the last turn."}],"captainNotes":"The range of ATK boost is from 2x to 3.75x. The exact boost is calculated as 2 + * 0.000175 and maxes at 10k HP healed. This ignores your max HP, so it doesn''t stop counting if you over-heal. #{beneficial}","specialName":"Kingdom Come","specialText":"Deals 25x Excess Healing done before the special is activated in Typeless damage to all enemies.","specialNotes":"The Excess Healing is counted from the last time the special is used and accumulates when you heal more than your maximum HP. For example, if you are at max HP and you heal 1,000 HP, you will add 25k damage to the special. The amount of damage possible caps at 5,000,000 damage (9,000,000 with LLB).","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kami eneru","eneru"],"characterTags":["Kami''s Army","Logia-type","Skypiea Arc"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMo