      INSERT INTO character_details (character_id, detail_json)
      VALUES (2233, '{"characterId":2233,"captainAbility":"Always Active: Boosts HP of [STR], [DEX] and [QCK] characters by 1.2x and changes [RCV] orbs into [SEMLA] orbs. Standard Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 3.5x. Powered Up Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 4x and reduces damage received by 15%. Rampage Captain: Boosts ATK of this character by 10x and own attacks will ignore damage reducing Barriers and Buffs, boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Always Active: Boosts HP of [STR], [DEX] and [QCK] characters by 1.2x and changes [RCV] orbs into [SEMLA] orbs. Standard Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 3.5x. Powered Up Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 4x and reduces damage received by 15%. Rampage Captain: Boosts ATK of this character by 10x and own attacks will ignore damage reducing Barriers and Buffs, boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x"}],"captainNotes":"[SEMLA] orbs replace [RCV] orbs, are beneficial for all characters and heal at the end of the enemy turn and can not be controlled by special abilities. In order to Power Up Big Mom, you must eat a [SEMLA] orb and will be powered up the following turn. While in Rampage, Big Mom will always attack a random enemy on her own, even while Binded or Paralyzed and hit a HUNGRY, which deals the same damage as a PERFECT. This attack occurs after your chain, so Big Mom''s attack will not be affected by Chain Limiters, Chain Boosters, or Chain Lockers. You can not activate Big Mom''s special while in Rampage. To exit Rampage, you must consume a [SEMLA] orb.","specialName":"Temper Tantrum","specialText":"Deals 250x character''s ATK in Typeless damage to one enemy and changes the orb of this character into a [STR] orb. If Big Mom is your Captain or Friend/Guest Captain, boosts ATK of top row characters by 2x for 3 turns and boosts Orb Effects of top row characters by 2x for 3 turns. If she is a Crewmate when the special is activated, boosts ATK of this character by 2x for 1 turn and boosts Orb Effects of this character by 2x for 1 turn instead","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["charlotte linlin","linlin"],"characterTags":[],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":2233,"basedOn":2234}}');


