      VALUES (2251, '{"characterId":2251,"captainAbility":"Boosts ATK of all characters by 2x at the start of the chain and their HP by 1.5x, boosts ATK of all characters by 4x following a chain of Good > Great > PERFECT hits, makes [PSY] and [RCV] orbs beneficial for all characters. Reduces ATK based on how many Striker, Shooter or Cerebral characters you have on your crew.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 2x at the start of the chain and their HP by 1.5x, boosts ATK of all characters by 4x following a chain of Good > Great > PERFECT hits, makes [PSY] and [RCV] orbs beneficial for all characters. Reduces ATK based on how many Striker, Shooter or Cerebral characters you have on your crew."}],"captainNotes":"ATK reduction is 0.2x for each Striker, Shooter or Cerebral class on your team. This stacks if you have each class on your team, so a team with a Striker, Shooter, and Cerebral character will get a 99.2% ATK reduction from Garp.","specialName":"Fist of Love","specialText":"Deals 10% of enemies'' current HP in True damage to one enemy, locks the chain multiplier at 3x for 1 turn and reduces Special Bind duration by 1 turn. Deals 30% of enemies'' current HP in True damage to one enemy, locks the chain multiplier at 3x for 1 turn and reduces Special Bind duration by 3 turns","specialNotes":"#{specialBind}","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["garp the fist","fist"],"characterTags":["Navy","Navy Vice Admiral"],"builderAbilities":[{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":nul