      INSERT INTO character_details (character_id, detail_json)
      VALUES (2300, '{"characterId":2300,"captainAbility":"If your crew has 6 characters with Fighter, Slasher, Shooter or Striker classes, boosts ATK of all characters by 3.25x and their HP by 1.3x and makes [RCV] and [TND] orbs beneficial for all characters. Action: Docking Franky brings the entire crew into General Franky for 1 turn and makes crew immune to Blow Away. During this turn, boosts ATK of all characters by 4.25x instead and reduces damage taken by 38%.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"If your crew has 6 characters with Fighter, Slasher, Shooter or Striker classes, boosts ATK of all characters by 3.25x and their HP by 1.3x and makes [RCV] and [TND] orbs beneficial for all characters. Action: Docking Franky brings the entire crew into General Franky for 1 turn and makes crew immune to Blow Away. During this turn, boosts ATK of all characters by 4.25x instead and reduces damage taken by 38%."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"If your crew has 6 characters with Fighter, Slasher, Shooter or Striker classes, boosts ATK of all characters by 3.5x and their HP by 1.3x and makes [RCV] and [TND] orbs beneficial for all characters. Action: Docking Franky brings the entire crew into General Franky for 1 turn and makes crew immune to Blow Away. During this turn, boosts ATK of all characters by 4.25x instead and reduces damage taken by 38%."}],"captainNotes":"All characters on your crew must have one of the 4 classes listed, but you do not need one of each. Franky Captain Action lasts one turn and can be reactivated after a 4 turns cooldown. Only 1 Franky Captain Action can be activated at once. During transformation:. If you attack with a Fighter character, deal 1.25x damage to targeted enemy. If you attack with a Slasher character, deal full damage to targeted enemy, but deal 0.1x damage to all enemies in the same row as the targeted enemy. If you attack with a Striker character, deal 0.5x damage to all enemies on the stage. If you attack with a Shooter character, deal 0.75x damage to targeted enemy but deal 0.3x damage to all other enemies on the stage","specialName":"Franky Radical Beam","specialText":"Deals 10% of enemies'' current HP in damage to all enemies and randomizes all non-Matching orbs, including [BLOCK] orbs. If there are 3 enemies or more on the stage when the special is activated, boosts ATK of Fighter, Slasher, Shooter and Striker characters by 2.25x for 1 turn, boosts ATK of Fighter, Slasher, Shooter and Striker characters by 2x otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["franky"],"characterTags":["Straw Hat Pirates","Dressrosa Arc"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_striker","label":"ATK Boost: Striker","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_striker","label":"RCV Boost: Striker","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_striker","label":"HP Boost: Striker","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_str_damage_reduction","label":"STR Damage Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_barrier_pierce","label":"Barrier Pierce","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_atk_boost","label":"ATK Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK, HP and RCV of Shooter, Slasher, Fighter and Striker characters by 50. Makes [QCK] orbs beneficial for Shooter, Slasher, Fighter and Striker characters"],"sailorNotes":"#{beneficial}","potentialAbilities":[{"Name":"[STR] Damage Reduction","description":["Reduces damage taken from [STR] characters by 5%"]},{"Name":"Reduce No Healing duration","description":["Reduces No Healing duration by 7 turns"]},{"Name":"Barrier Penetration","description":["This character''s normal attack will ignore barriers"]}],"supportData":[{"supportedCharactersText":"Monkey D. Luffy, Roronoa Zoro, Usopp and Nico Robin","levelDescriptions":["Once per adventure, when the supported character uses a Damage Dealing or Health Cutting special, boosts ATK of Fighter, Slasher, Shooter and Striker characters by 1.4x for 1 turn."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":230