      VALUES (2323, '{"characterId":2323,"captainAbility":"Boosts ATK of Fighter and Powerhouse characters by 2.5x and their HP by 1.2x. Deals 3x the damage taken from enemies in the previous turn in Typeless damage to all enemies at the end of each turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Fighter and Powerhouse characters by 2.5x and their HP by 1.2x. Deals 3x the damage taken from enemies in the previous turn in Typeless damage to all enemies at the end of each turn."}],"captainNotes":null,"specialName":"Scorching Fist","specialText":"Removes any Orb Rate Up and Orb Rate Down Buffs, changes [STR], [DEX], [QCK], [PSY] and [INT] orbs into [EMPTY] orbs, deals 7x-350x character''s ATK in [STR] damage to one enemy, depending on number of [STR], [DEX], [QCK], [PSY] or [INT] slots emptied. Changes all orbs into Matching orbs. If enemies have All Debuff Protection, Delay Debuff Protection or Poison Debuff Protection when the special is activated, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 1.75x for 1 turn. If during that turn you score 4 PERFECT hits, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 1.75x for 2 turns in the following turn.","specialNotes":"The exact multiplier used is chosen based on the number of [STR], [DEX], [QCK], [PSY] or [INT] orbs consumed: 0 orbs - 7x ATK; 1 orb - 52.5x ATK; 2 orbs - 105x ATK; 3 orbs - 157.5x ATK; 4 orbs - 210x ATK; 5 orbs - 262.5x ATK; 6 orbs - 350x ATK.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["charlotte oven","oven"],"characterTags":[],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"tap_timing_requirement","label":"Tap-Timing Requirement","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"delayed_effect_launch","label":"Delayed Effect Launch","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"potential_slot_bind_resistance","label":"Slot Bind Resistance","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_barrier_pierce","label":"Barrier Pierce","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_base_atk_boost","label":"Base ATK Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK of [STR], [DEX] and [QCK] characters by 40. Boosts base HP of [STR], [DEX] and [QCK] characters by 40"],"sailorNotes":null,"potentialAbilities":[{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 5 turns on this character"]},{"Name":"Barrier Penetration","description":["This character''s normal attack will ignore barriers if HP is above 50% at the start of the turn"]}],"supportData":[{"supportedCharactersText":"[STR] characters","levelDescriptions":["Adds 5% of this character''s base ATK to the supported character''s base ATK"]}],"swapData":null,"vsSpecial":null,"superType":null,"superTan