al":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK of top row characters by 80. If your Captain is a Fighter, Free Spirit or Powerhouse character, removes Blindness duration completely"],"sailorNotes":null,"potentialAbilities":[{"Name":"[DEX] Damage Reduction","description":["Reduces damage taken from [DEX] characters by 5%"]},{"Name":"Enrage/Reduce Increase Damage Taken duration","description":["Boosts base ATK by 200 the turn after taking damage and reduces Increase Damage Taken duration by 3 turns"]}],"supportData":[{"supportedCharactersText":"Edward Newgate (Whitebeard)","levelDescriptions":["Once per adventure, when the supported character uses a Damage Dealing or Health Cutting special, changes [EMPTY] and Badly Matching orbs of Free Spirit and Powerhouse characters into Matching orbs."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":2394,"basedOn":2393}}');


