      VALUES (2500, '{"characterId":2500,"captainAbility":"Always Active: Boosts HP of [STR], [DEX] and [QCK] characters by 1.3x and changes [RCV] orbs into [SEMLA] orbs. Standard Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 3.5x. Powered Up Captain: Boosts ATK of this character by 4.25x, boosts ATK of [STR], [DEX] and [QCK] characters by 4x and reduces damage received by 15%. Rampage Captain: Boosts ATK of this character by 12x and own attacks will ignore damage reducing Barriers and Buffs, boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x and boosts chances of getting [SEMLA] orbs.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Always Active: Boosts HP of [STR], [DEX] and [QCK] characters by 1.3x and changes [RCV] orbs into [SEMLA] orbs. Standard Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 3.5x. Powered Up Captain: Boosts ATK of this character by 4.25x, boosts ATK of [STR], [DEX] and [QCK] characters by 4x and reduces damage received by 15%. Rampage Captain: Boosts ATK of this character by 12x and own attacks will ignore damage reducing Barriers and Buffs, boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x and boosts chances of getting [SEMLA] orbs."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Always Active: Boosts HP of [STR], [DEX] and [QCK] characters by 1.3x and changes [RCV] orbs into [SEMLA] orbs. Standard Captain: Boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x. Powered Up Captain: Boosts ATK of this character by 4.25x, boosts ATK of [STR], [DEX] and [QCK] characters by 4x and reduces damage received by 15%. Rampage Captain: Boosts ATK of this character by 12x and own attacks will ignore damage reducing Barriers and Buffs and boosts ATK of [STR], [DEX] and [QCK] characters by 3.75x and boosts chances of getting [SEMLA] orbs."}],"captainNotes":"[SEMLA] orbs replace [RCV] orbs, are beneficial for all characters and heal at the end of the enemy turn and can not be controlled by special abilities. In order to Power Up Big Mom, you must eat a [SEMLA] orb and will be powered up the following turn. While in Rampage, Big Mom will always attack a random enemy on her own, even while Binded or Paralyzed and hit a HUNGRY, which deals the same damage as a PERFECT. This attack occurs after your chain, so Big Mom''s attack will not be affected by Chain Limiters, Chain Boosters, or Chain Lockers. You can not activate Big Mom''s special while in Rampage. To exit Rampage, you must consume a [SEMLA] orb.","specialName":"Ikoku Sovereignty","specialText":"Deals 300x character''s ATK in Typeless damage to one enemy and changes the orb, including [BLOCK] orbs, of this character into a [STR] orb. If Big Mom is your Captain or Friend/Guest Captain, boosts ATK of top row characters by 2x for 3 turns, boosts Orb Effects of top row characters by 2x for 3 turns and locks orbs for top row characters for 2 turns. If she is a Crewmate when the special is activated, boosts ATK of this character by 2x and boosts Orb Effects of this character by 2x for 1 turn instead.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["big mom","mom","charlotte linlin"],"characterTags":["Big Mom Pirates","Four Emperors","Homies","Paramythia-type","Whole Cake Island Arc"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"speci