      INSERT INTO character_details (character_id, detail_json)
      VALUES (2618, '{"characterId":2618,"captainAbility":"Boosts ATK of [STR] characters by 3.25x, boosts ATK of [DEX] and [INT] characters by 2.5x and makes [STR] orbs beneficial for [DEX] and [INT] characters.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of [STR] characters by 3.25x, boosts ATK of [DEX] and [INT] characters by 2.5x and makes [STR] orbs beneficial for [DEX] and [INT] characters."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of [INT] characters by 3.25x, boosts ATK of [STR] and [DEX] characters by 2.5x and makes [INT] orbs beneficial for [STR] and [DEX] characters."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of [STR], [DEX] and [INT] characters by 3.75x, makes [STR] and [INT] orbs beneficial for [STR], [DEX] and [INT] characters and deals 10% of enemies'' current HP in damage to all enemies at the end of each turn."}],"captainNotes":null,"specialName":"Heavenly Eruption","specialText":"Instantly defeats all enemies with HP equal to or below 120x character''s ATK, randomizes all orbs into either [STR] or [INT] orbs, deals 20% of enemies'' current HP in damage to all enemies and becomes Sakazuki & Issho for 2 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["sakazuki & issho","sakazuki","issho"],"characterTags":["Navy","Navy Fleet Admiral","Logia-type","Dressrosa Arc","Navy Admiral","Paramythia-type"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"defeat_enemy","label":"Defeat Enemy","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"potential_dex_damage_reduction","label":"DEX Damage Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"}],"sailorAbilities":["When any other [STR], [DEX] or [INT] character uses a special, reduces special cooldown of this character by 4 turns. Boosts base ATK and HP of [STR], [DEX] and [INT] characters by 25. Boosts base ATK and RCV of [STR], [DEX] and [INT] characters by 25. Boosts base ATK, HP and RCV of [STR], [DEX] and [INT] characters by 50"],"sailorNotes":null,"potentialAbilities":[{"Name":"[DEX] Damage Reduction","description":["Reduces damage taken from [DEX] characters by 5%"]},{"Name":"Enrage/Reduce Increase Damage Taken duration","description":["Boosts base ATK by 200 the turn after taking damage and reduces Increase Damage Taken duration by 3 turns"]}],"supportData":[],"swapData":"Boosts Orb Effects of [STR], [DEX] and [INT] characters by 1.5x for 1 turn and deals 7% of enemies'' current HP in damage to all enemies at the end of each turn for 1 turn.","vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":2618,"pattern":[{"type":"Normal","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"BAL","def":50,"spd":100},"cost":60}}');


