      INSERT INTO character_details (character_id, detail_json)
      VALUES (2631, '{"characterId":2631,"captainAbility":"Boosts ATK of all characters by 2.5x, but boosts ATK of this character by 1.25x, recovers 5x character''s RCV in HP at the end of each turn. If you don''t attack with her, reduces damage received by 15% for that turn.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Boosts ATK of all characters by 2.5x, but boosts ATK of this character by 1.25x, recovers 5x character''s RCV in HP at the end of each turn. If you don''t attack with her, reduces damage received by 15% for that turn."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Boosts ATK of all characters by 3.25x, but boosts ATK of this character by 1.25x, recovers 5x character''s RCV in HP at the end of each turn. If you don''t attack with her, reduces damage received by 15% for that turn."}],"captainNotes":null,"specialName":"A Glimpse of Poseidon''s Power","specialText":"Changes orbs, including [BLOCK] orbs, of adjacent characters into [RAINBOW] orbs, recovers 14x character''s RCV in HP and reduces RCV DOWN and No Healing duration by 5 turns.. Changes all orbs, including [BLOCK] orbs, into [RAINBOW] orbs, recovers 125x character''s RCV in HP and reduces RCV DOWN and No Healing duration by 15 turns.","specialNotes":"Rainbow orbs are the beneficial form of [BLOCK] orbs. They can not be shuffled or swapped by you or your opponent. They count as beneficial orbs to any character. They do not count as [STR] orbs for Sakazuki but do act like Matching orbs for Black Clad Ace or Fujitora captain abilities. #{stages}","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["princess shirahoshi","shirahoshi"],"characterTags":["Ryugu Kingdom","Royalty","Merfolk","Fish-Man Island Arc"],"builderAbilities":[{"key":"remove_no_healing","label":"Remove No Healing","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","cov