      INSERT INTO character_details (character_id, detail_json)
      VALUES (2632, '{"characterId":2632,"captainAbility":"Boosts ATK of all characters by 4.25x, boosts HP of all characters by 1.2x, makes [STR] and [DEX] orbs beneficial for all characters, and reduces ATK Down duration by 6 turns. If this character becomes your captain in the middle of an island, boosts ATK of Fighter, Powerhouse and Free Spirit characters by 5.5x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 4.25x, boosts HP of all characters by 1.2x, makes [STR] and [DEX] orbs beneficial for all characters, and reduces ATK Down duration by 6 turns. If this character becomes your captain in the middle of an island, boosts ATK of Fighter, Powerhouse and Free Spirit characters by 5.5x."}],"captainNotes":null,"specialName":"Parental Fist","specialText":"Deals 50x character''s ATK in [DEX] damage to one enemy. If your Captain is a Fighter or Powerhouse character, reduces Special Cooldown of Fighter and Powerhouses characters by 1 turn and reduces enemies'' Barrier and Damage Nullification duration by 1 turn. If this character is a Crewmate when the special is activated, swaps this unit with your captain for 1 turn.. Deals 200x character''s ATK in [DEX] damage to one enemy. If your Captain is a Fighter or Powerhouse character, reduces Special Cooldown of Fighter and Powerhouses characters by 2 turns and reduces enemies'' Barrier and Damage Nullification duration by 3 turns. If this character is a Crewmate when the special is activated, swaps this unit with your captain for 2 turns.","specialNotes":". LLB: For every 3 Special Cooldown charges after this special is charged to MAX, the Chain Addition increases by +0.1x until its maximum value.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["garp the fist","fist"],"characterTags":["Navy","Navy Vice Admiral","Marineford Paramount War Arc"],"builderAbilities":[{"key":"remove_