      INSERT INTO character_details (character_id, detail_json)
      VALUES (2785, '{"characterId":2785,"captainAbility":"Boosts ATK of Slasher and Cerebral characters by 2.75x, their HP by 1.2x and boosts chances of getting [INT] orbs.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Slasher and Cerebral characters by 2.75x, their HP by 1.2x and boosts chances of getting [INT] orbs."}],"captainNotes":null,"specialName":"Ready Swordsman","specialText":"Changes [BLOCK] orbs into [EMPTY] orbs, deals 50x-80x character''s ATK in Typeless damage to all enemies, depending on number of [BLOCK] slots emptied. Changes [EMPTY], [G] and [BOMB] orbs into [INT] orbs. If HP is above 99% when the special is activated, reduces any damage received above 3,000 HP by ?% for 1 turn and adds 0.9x to Chain multiplier for 1 turn. Otherwise, reduces damage received by 80% for 1 turn and adds 0.7x to Chain multiplier for 1 turn.","specialNotes":"The exact multiplier used is chosen based on the number of [BLOCK] orbs consumed: 0 orbs - 50x ATK; 1 orb - 50x ATK; 2 orbs - 57.5x ATK; 3 orbs - 65x ATK; 4 orbs - 70x ATK; 5 orbs - 75x ATK; 6 orbs - 80x ATK.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["napping kyoshiro","kyoshiro"],"characterTags":[],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_cerebral","label":"ATK Boost: Cerebral","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_cerebral","label":"RCV Boost: Cerebral","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_cerebral","label":"HP Boost: Cerebral","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_slot_bind_resistance","label":"Slot Bind Resistance","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_base_atk_boost_additional","label":"Base ATK Boost: Additional","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"},{"key":"support_base_hp_boost_additional","label":"Base HP Boost: Additional","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK, HP and RCV of Slasher and Cerebral characters by 50. Makes [INT] orbs beneficial for Slasher characters"],"sailorNotes":null,"potentialAbilities":[{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 5 turns on this character"]},{"Name":"Reduce No Healing duration","description":["Reduces No Healing duration by 5 turns"]}],"supportData":[{"supportedCharactersText":"Slasher characters","levelDescriptions":["Adds 6% of this character''s base ATK and HP to the supported character''s base ATK and HP."]}],"swapData":null,"vsSpecial":null,"superType":nu