      INSERT INTO character_details (character_id, detail_json)
      VALUES (3402, '{"characterId":3402,"captainAbility":"Boosts ATK of [INT], Cerebral and Powerhouse characters by 5x and their HP by 1.2x. If a crew member uses a special that inflicts Poison, Strong Poison or Toxic, inflicts all enemies with Reiju Poison. If your crew is inflicted with Poison, Strong Poison or Toxic, activates \"Lustrous Devilish Woman\" in the following turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [INT], Cerebral and Powerhouse characters by 5x and their HP by 1.2x. If a crew member uses a special that inflicts Poison, Strong Poison or Toxic, inflicts all enemies with Reiju Poison. If your crew is inflicted with Poison, Strong Poison or Toxic, activates \"Lustrous Devilish Woman\" in the following turn."}],"captainNotes":null,"specialName":"Lustrous Devilish Woman","specialText":"Boosts ATK of [INT], Cerebral and Powerhouse characters by 2.25x for 3 turns, and removes Paralysis and Poison duration completely. If enemies are inflicted with Poison, Strong Poison, Toxic or Reiju Poison when the special is activated, poison deals 30% of enemies'' current HP in damage to all enemies and removes enemies'' Poison duration completely. Otherwise, inflicts all enemies with Reiju Poison.","specialNotes":"Poison HP Cut deals damage in the same way as other poisons. Reiju Poison deals 20% of enemies'' current HP in damage at the end of each turn and recovers 20% crew''s MAX HP at the end of each turn. Reiju Poison is derivative of Normal Poison, so it fulfills Poison Status ATK Boosts and is affected by Poison Debuff Immunity.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["reiju"],"characterTags":[],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_poison","label":"Remove Poison",