      INSERT INTO character_details (character_id, detail_json)
      VALUES (3453, '{"characterId":3453,"captainAbility":"Boosts ATK of [INT], Shooter and Free Spirit characters by 4x and their HP by 1.3x. If enemies are inflicted with Negative, boosts ATK against enemies inflicted with Negative by 1.3x, boosts ATK against delayed enemies, enemies with reduced defense and Poisoned enemies by 1.25x otherwise.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [INT], Shooter and Free Spirit characters by 4x and their HP by 1.3x. If enemies are inflicted with Negative, boosts ATK against enemies inflicted with Negative by 1.3x, boosts ATK against delayed enemies, enemies with reduced defense and Poisoned enemies by 1.25x otherwise."}],"captainNotes":null,"specialName":"Ghost Dance Night Party","specialText":"Changes Badly Matching, [EMPTY], [BLOCK], [BOMB], [RCV], [TND] and [G] orbs into Matching orbs, boosts ATK against delayed enemies, enemies inflicted with Negative, enemies with reduced defense, Poisoned enemies, Strongly Poisoned enemies and enemies inflicted with Toxic by 2x for 3 turns and locks the chain multiplier at 3.25x for 3 turns. If HP is below 80% when the special is activated, ignores Debuff Protection and inflicts enemies with Negative for 1 turn. If your crew has Chain Lock when the special is activated, increases boost effects of Chain Lock buffs/debuffs by +0.5x and increases duration of any Chain Lock/Limit/Boundary buffs/debuffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["perona: halloween princess","princess"],"characterTags":[],"builderAbilities":[{"key":"chain_multiplier_lock","label":"Chain Multiplier: Lock","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverage