      INSERT INTO character_details (character_id, detail_json)
      VALUES (3492, '{"characterId":3492,"captainAbility":"Boosts ATK of Shooter, Cerebral and Free Spirit characters by 4.25x, their HP by 1.3x and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of Shooter, Cerebral and Free Spirit characters by 4.25x, their HP by 1.3x and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of Shooter, Cerebral and Free Spirit characters by 3.75x, their HP by 1.3x, boosts Shooter, Cerebral and Free Spirit characters ATK against delayed enemies by 1.2x and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of Shooter, Cerebral and Free Spirit characters by 4.25x, their HP by 1.3x, boosts Shooter, Cerebral and Free Spirit characters ATK against delayed enemies by 1.2x and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn. At the beginning of each Stage, increases the Attack Timer of all enemies by 1 turn."}],"captainNotes":"Delay chance is based on damage dealt with normal attacks and does not stack with any other delay specials or effects. Base Chances. 100,000 damage or more: 20% chance to delay. 1,000,000 damage or more: 50% chance to delay. 3,000,000 damage or more: 100% chance to delay. 5,000,000 damage or more: 100% chance to delay ignoring Delay Debuff Protection","specialName":"Encounter to Stop the Chase","specialText":"Paralyzes (75%) all enemies for 5 turns, delays all enemies by 2 turns, reduces Paralysis and Special Bind duration by 6 turns, boosts the Color Affinity of Shooter and Cerebral characters by 2.25x fo