      INSERT INTO character_details (character_id, detail_json)
      VALUES (3514, '{"characterId":3514,"captainAbility":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 4.75x, their HP by 1.5x recovers 1,000 HP at the end of each turn and makes all Specials that apply Class or Type restricted buffs apply to all characters instead.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 4.75x, their HP by 1.5x recovers 1,000 HP at the end of each turn and makes all Specials that apply Class or Type restricted buffs apply to all characters instead."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 4.5x, by 5x instead if they have a beneficial orb, their HP by 1.5x recovers 1,000 HP at the end of each turn and makes all Specials that apply Class or Type restricted buffs apply to all characters instead."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 5x, by 5.25x instead if they have a beneficial orb, their HP by 1.5x recovers 2,000 HP at the end of each turn and makes all Specials that apply Class or Type restricted buffs apply to all characters instead."}],"captainNotes":"Buff restriction override does not apply to \"Partial\" buffs. The buff restriction override applies to any effect that would normally affect only certain classes or types, including, but not restricted to: ATK buffs, Orb buffs, Base ATK buffs, Cooldown Reduction, Normal Attack Defensive Effect Bypass, Orb Lock buffs and Slot Barrier debuffs, but does not effect defensive buffs. This effect doesn''t not effect Swap abilities, Support abilities, Super Special abilities, VS Special abilities or effects obtained from Following Turn or Tap-Timing Following Turn buffs.","specialName":"Charging Straw Hats","specialText":"Deals 300x character''s ATK in Typeless damage to all enemies, changes all orbs, including [BLOCK] orbs, into [RAINBOW] orbs and becomes Luffy & Straw Hat Pirates for 3 turns. If your crew has 1 or fewer buffs when the special is activated, boosts ATK of all characters by 2x for 2 turns, boosts the Color Affinity of all characters by 2x for 2 turns, boosts Orb Effects of all characters by 2x for 2 turns, adds 0.8x to Chain multiplier for 2 turns and prevents adding any additional buffs to your team this turn. If your crew has 2 or more buffs when the special is activated, locks all orbs for 2 turns and increases duration of any ATK boosting, Orb Amplification, Base ATK boosting, Status ATK boosting, Affinity boosting, Chain Addition, Chain Multiplication buffs and Chain Lock/Limit/Boundary debuffs/buffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["luffy & straw hat pirates","luffy","straw hat pirates","pirates"],"characterTags":[],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_crew","label":"RCV Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_crew","label":"HP Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK and HP of all characters by 100. Boosts base ATK, HP and RCV of all characters by 100"],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":{"base":"Changes the orb, including [BLOCK] orb, of this character into a Matching orb and removes Slot Bind and Paralysis duration completely on this character.","super":"Changes the orb, including [BLOCK] orb, of this character into a Matching orb, removes Slot Bind and Paralysis duration completely on this character and reduces Ship Bind a