or effects obtained from Following Turn or Tap-Timing Following Turn buffs.","specialName":"Charging Straw Hats","specialText":"Deals 300x character''s ATK in Typeless damage to all enemies, changes all orbs, including [BLOCK] orbs, into [RAINBOW] orbs and becomes Luffy & Straw Hat Pirates for 3 turns. If your crew has 1 or fewer buffs when the special is activated, boosts ATK of all characters by 2x for 2 turns, boosts the Color Affinity of all characters by 2x for 2 turns, boosts Orb Effects of all characters by 2x for 2 turns, adds 0.8x to Chain multiplier for 2 turns and prevents adding any additional buffs to your team this turn. If your crew has 2 or more buffs when the special is activated, locks all orbs for 2 turns and increases duration of any ATK boosting, Orb Amplification, Base ATK boosting, Status ATK boosting, Affinity boosting, Chain Addition, Chain Multiplication buffs and Chain Lock/Limit/Boundary debuffs/buffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["luffy & straw hat pirates","luffy","straw hat pirates","pirates"],"characterTags":["Straw Hat Pirates","Worst Generation","Paramythia-type","Land of Wano Arc","Fish-Man","Zoan-type"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"is