      INSERT INTO character_details (character_id, detail_json)
      VALUES (3533, '{"characterId":3533,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns and advances Special Cooldown of this character to MAX at the start of the fight. Reduces Special Cooldown of this character by 5 turns at the start of Stage 3. Boosts ATK of Fighter, Slasher, Striker and Shooter characters by 4x and boosts ATK of [STR], [DEX] and [QCK] characters by an additional 1.25x. For 10 turns at the start of the fight, boosts chances of getting Matching orbs and, if HP is above 50% at the start of the turn, attacks will ignore damage reducing Barriers and Buffs.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 2 turns and advances Special Cooldown of this character to MAX at the start of the fight. Reduces Special Cooldown of this character by 5 turns at the start of Stage 3. Boosts ATK of Fighter, Slasher, Striker and Shooter characters by 4x and boosts ATK of [STR], [DEX] and [QCK] characters by an additional 1.25x. For 10 turns at the start of the fight, boosts chances of getting Matching orbs and, if HP is above 50% at the start of the turn, attacks will ignore damage reducing Barriers and Buffs."}],"captainNotes":"Attacks are still affected by DEF value. DEF boost buffs (Blue shield) still reduce your damage and you can not kill through Resilience, but Damage Negating (Yellow shield), % Damage Reduction (Rainbow shield), Barriers and Threshold Damage Reduction are ignored. Enemy attacks will go through YOUR defensive buffs.","specialName":"Brightly Shining King of the Day","specialText":"Reduces Special Cooldown of all characters by 2 turns and boosts ATK of Fighter, Slasher, Striker and Shooter characters by 2.5x for 1 turn. If during that turn you score 2 PERFECT hits, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 2.5x for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"super