      INSERT INTO character_details (character_id, detail_json)
      VALUES (3550, '{"characterId":3550,"captainAbility":"Boosts ATK of Driven characters by 4.5x if they have a beneficial orb, by 3.75x otherwise and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Boosts ATK of Driven characters by 4.5x if they have a beneficial orb, by 3.75x otherwise and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight. If they have a beneficial orb, boosts ATK of Driven characters by 4.75x, by 4x otherwise, and their HP by 1.4x. Lowers chances of getting [STR] orbs and makes [DEX] and [QCK] orbs beneficial for Driven characters."}],"captainNotes":"#{beneficial}","specialName":"Life-Stealing Thousand Arrows: Flapping Thread","specialText":"Deals 2.5x the damage dealt in Overkill Damage in the previous turn in Typeless damage to all enemies. If your crew has Normal Attack Only when the special is activated, boosts ATK of Driven characters by 2.5x for 1 turn and makes [PSY] and [INT] orbs beneficial for Driven characters for 1 turn.","specialNotes":"Overkill Damage is damage dealt over the enemies'' current HP with normal attacks that killed them. For example, dealing 2,100,000 damage to an enemy with 1,000,000 HP will count as 1,100,000 Overkill Damage. This stacks for each enemy killed in the previous turn. The Overkill Damage Counter caps out at 999,999,999 damage.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["donquixote doflamingo","doflamingo"],"characterTags":["Donquixote Pirates","Seven Warlords of the Sea","Paramythia-type","Dressrosa Arc"],"builderAbilities":[{"key":"boost_atk","label"