      INSERT INTO character_details (character_id, detail_json)
      VALUES (3625, '{"characterId":3625,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [STR] and [INT] characters by 4.5x and makes [STR] and [INT] orbs beneficial for [STR] and [INT] characters. Deals 0x-600x character''s ATK in Typeless damage to one enemy at the end of each turn depending on how many PERFECTs scored that turn.","captainAbilityVariants":[{"key":"base","label":"Base Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [STR] and [INT] characters by 4.5x and makes [STR] and [INT] orbs beneficial for [STR] and [INT] characters. Deals 0x-600x character''s ATK in Typeless damage to one enemy at the end of each turn depending on how many PERFECTs scored that turn."},{"key":"level1","label":"Limit Break Level 1 Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [STR] and [INT] characters by 4.75x, boosts HP of [STR] and [INT] characters by 1.3x, boosts chances of getting Matching orbs on [STR] and [INT] characters and makes [STR] and [INT] orbs beneficial for [STR] and [INT] characters. Deals 0x-800x character''s ATK in Typeless damage to one enemy at the end of each turn depending on how many PERFECTs scored that turn."}],"captainNotes":"End of turn damage is based on how many PERFECTs you hit this turn: 0 PERFECTs - 0x ATK; 1 PERFECT - 100x ATK; 2 PERFECTs - 200x ATK; 3 PERFECTs - 300x ATK; 4 PERFECTs - 400x ATK; 5 PERFECTs - 500x ATK; 6 PERFECTs - 600x ATK. [LLB] End of turn damage is based on how many PERFECTs you hit this turn: 0 PERFECTs - 0x ATK; 1 PERFECT - 150x ATK; 2 PERFECTs - 250x ATK; 3 PERFECTs - 350x ATK; 4 PERFECTs - 500x ATK; 5 PERFECTs - 650x ATK; 6 PERFECTs - 800x ATK. #{beneficial}","specialName":"Roiling Hound Blaze","specialText":"Deals 200x character''s ATK in Typeless True damage to one enemy, reduces enemies'' Increased Defense and Percent Damage Reduction duration by 2 turns, changes all orbs, including [BLOCK] orbs, into Matching orbs and boosts Orb Effects of [STR] and [INT] characters by 2.25x for 1 turn. If you have used 20 or more [STR] or [INT] orbs in attacks when the special is activated, reduces Special Cooldown of this character by 12 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["fleet admiral sakazuki","sakazuki"],"characterTags":["Navy","Navy Fleet Admiral","Logia-type"],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_damage_reduction","label":"Remove Damage Reduction","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens