      INSERT INTO character_details (character_id, detail_json)
      VALUES (3680, '{"characterId":3680,"captainAbility":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [INT], Striker and Cerebral characters by 5.25x, boosts HP of [INT], Striker and Cerebral characters by 1.3x and reduces Paralysis duration by 10 turns and restores Special Cooldown of all characters by 10 turns when they are rewinded.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [INT], Striker and Cerebral characters by 5.25x, boosts HP of [INT], Striker and Cerebral characters by 1.3x and reduces Paralysis duration by 10 turns and restores Special Cooldown of all characters by 10 turns when they are rewinded."}],"captainNotes":null,"specialName":"Joyous Song","specialText":"Applies a Turn Progress Effect for 3 turns that will apply the following effects: Turn 1 (Activation): Boosts ATK of Striker and Cerebral characters by 2.5x for 1 turn and boosts Orb Effects of Striker and Cerebral characters by 2x for 1 turn. Turn 2: Boosts ATK of Striker and Cerebral characters by 2.75x for 1 turn and boosts Orb Effects of Striker and Cerebral characters by 2.25x for 1 turn. Turn 3: Boosts ATK of Striker and Cerebral characters by 3x for 1 turn and boosts Orb Effects of Striker and Cerebral characters by 2.5x for 1 turn. On Effect Removal by Enemy: Boosts ATK of Striker and Cerebral characters by 2.5x for 1 turn and boosts Orb Effects of Striker and Cerebral characters by 2.5x for 1 turn. If your crew has Turn Progress Effect when the special is activated, changes all orbs, including [BLOCK] orbs, into [INT] orbs, locks all orbs for 2 turns and adds 1.4x to Chain multiplier for 3 turns.","specialNotes":null,"superSpecialText":"Increases boost effects of ATK UP and Orb Amplification buffs applied by Striker and Cerebral characters by 0.25x for 3 turns, recovers 30% of crew''s MAX HP and transforms Cerebral characters into Super Cerebral characters.","superSpecialCriteriaText":"This character must be captain and your crew must have ATK UP and Orb Effect.","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must have ATK UP and Orb Effect.","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"},"partyConflictKeys":["uta"],"characterTags":["Paramythia-type"],"builderAbilities":[{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_cerebral","label":"HP Boost: Cerebral","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_slot_bind_resistance","label":"Slot Bind Resistance","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_atk_boost","label":"ATK Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"},{"key":"support_slot_effect_boost","label":"Slot Effect Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Makes [PSY] and [INT] orbs beneficial for Cerebral characters. Boosts base HP of Cerebral characters by 1.1x"],"sailorNotes":null,"potentialAbilities":[{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 10 turns on this character"]},{"Name":"Pinch Healing","description":["If HP is below 50% at the start of the turn, recovers 2x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character"]},{"Name":"Last Tap","description":["Obtain Last Tap Lv.5"]}],"supportData":[{"supportedCharactersText":"[INT] Cerebral characters","levelDescriptions":["Once per adventure, when the supported character uses their special, boosts ATK of Cerebral characters by 1.5x for 1 turn and boosts Orb Effects of Cerebral characters by 1.5x for 1 turn."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":3680,"ability":[{"effects":[{"attributes":["HP","SPD"],"effect":"buff","level":6,"targeting":{"targets":["Cerebral"]}},{"attributes":["ATK","RCV"],"effect":"buff","level":2,"targeting":{"targets":["crew"]},"condition":{"type":"trigger","stat":"hit","count":4}}]}],"special":[{"cooldown":32,"effects":[{"attributes":["ATK"],"duration":15,"effect":"buff","le