      INSERT INTO character_details (character_id, detail_json)
      VALUES (3694, '{"characterId":3694,"captainAbility":"Boosts ATK of [QCK] characters by 5x, boosts ATK of all other characters by 4x, boosts HP of all characters by 1.5x, boosts Color Affinity of [QCK] characters by 1.1x, reduces damage received by 10%, makes [QCK], [RCV] and [TND] orbs beneficial for all characters and boosts chance of getting [QCK] and [TND] orbs.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [QCK] characters by 5x, boosts ATK of all other characters by 4x, boosts HP of all characters by 1.5x, boosts Color Affinity of [QCK] characters by 1.1x, reduces damage received by 10%, makes [QCK], [RCV] and [TND] orbs beneficial for all characters and boosts chance of getting [QCK] and [TND] orbs."}],"captainNotes":null,"specialName":"Haki Slash","specialText":"Deals 10% of enemies'' current HP in True damage to all enemies, changes all orbs, including [BLOCK] orbs, of left column characters into [QCK] orbs, changes all orbs, including [BLOCK] orbs, of right column characters into [TND] orbs and adds 1.4x to Chain multiplier for 1 turn. If your crew has 5 or more [QCK] characters, boosts Color Affinity of [QCK] characters by 2.75x for 1 turn; boosts Color Affinity of all characters by 2.25x for 1 turn otherwise. If your crew has Chain Addition and Color Affinity when the special is activated, reduces enemies'' Percent Damage Reduction and Threshold Damage Reduction duration by 7 turns and increases boost effects of Chain Addition buffs by +0.5x.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["shanks"],"characterTags":[],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":f