      VALUES (3706, '{"characterId":3706,"captainAbility":"Boosts ATK of [PSY], Fighter and Free Spirit characters by 5x. If you use \"Ending King Cobra\" in this turn boosts ATK of [PSY], Fighter and Free Spirit characters by 5.5x instead. If your crew has Roronoa Zoro, Vinsmoke Sanji, Usopp, Nami, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe or Shanks as a Sailor and they use their special, reduces Special Bind duration completely on this character and advances Special Cooldown of this character to MAX.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [PSY], Fighter and Free Spirit characters by 5x. If you use \"Ending King Cobra\" in this turn boosts ATK of [PSY], Fighter and Free Spirit characters by 5.5x instead. If your crew has Roronoa Zoro, Vinsmoke Sanji, Usopp, Nami, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe or Shanks as a Sailor and they use their special, reduces Special Bind duration completely on this character and advances Special Cooldown of this character to MAX."}],"captainNotes":"Cooldown Reduction and Paralysis Reduction on special effect is limited to 3 times per turn and 5 times per adventure. Effect only procs from crewmates who belong to those Character Families, not Captains or Friend/Guest Captains.","specialName":"Ending King Cobra","specialText":"Deals 200x character''s ATK in Typeless True damage to one enemy, and boosts ATK of [PSY], Fighter and Free Spirit characters by 3.25x for 1 turn. If your crew has ATK UP when the special is activated, boosts Orb Effects of [PSY], Fighter and Free Spirit characters by 2.75x for 1 turn. If your crew has ATK UP and Orb Amplification when the special is activated, changes all orbs, including [BLOCK] orbs, into Matching orbs and increases boost effects of ATK UP and Orb Amplification buffs by +0.25x. If this character has used their special 4 times or more and your crew does not have ATK UP, boosts Orb Effects of [PSY], Fighter and Free Spirit characters by 2.75x for 1 turn.","specialNotes":null,"superSpecialText":"Deals 120x character''s ATK in Typeless True damage to one enemy, reduces Special Cooldown of middle and bottom row characters by 2 turns and transforms [PSY] characters into Super [PSY] characters.","superSpecialCriteriaText":"This character must be captain and your crew must consist of any 1 or 2 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Vinsmoke Sanji, Usopp, Nami, Tony Tony Chopper, Nico Robin, Franky, Brook or Jinbe or Shanks.","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must consist of any 1 or 2 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Vinsmoke Sanji, Usopp, Nami, Tony Tony Chopper, Nico Robin, Franky, Brook or Jinbe or Shanks.","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Vinsmoke Sanji","acceptedKeys":["vinsmoke sanji","sanji"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},{"label":"Brook","acceptedKeys":["brook"]},{"label":"Jinbe","acceptedKeys":["jinbe"]},{"label":"Shanks","acceptedKeys":["shanks"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["monkey d. luffy","luffy"],"characterTags":["Straw Hat Pirates","Worst Generation","Paramythia-type"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"s