 Rebecca, Emporio Ivankov, Inazuma, Lindbergh, Belo Betty, Karasu, Morley or Bartholomew Kuma.","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Portgas D. Ace","acceptedKeys":["portgas d ace","ace"]},{"label":"Koala","acceptedKeys":["koala"]},{"label":"Rebecca","acceptedKeys":["rebecca"]},{"label":"Emporio Ivankov","acceptedKeys":["emporio ivankov","ivankov"]},{"label":"Inazuma","acceptedKeys":["inazuma"]},{"label":"Lindbergh","acceptedKeys":["lindbergh"]},{"label":"Belo Betty","acceptedKeys":["belo betty","betty"]},{"label":"Karasu","acceptedKeys":["karasu"]},{"label":"Morley","acceptedKeys":["morley"]},{"label":"Bartholomew Kuma","acceptedKeys":["bartholomew kuma","kuma"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["sabo"],"characterTags":["Revolutionary Army","Logia-type","Reverie Arc"],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"tap_timing_requirement","label":"Tap-Timing Requirement","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"delayed_effect_launch","label":"Delayed Effect Launch","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"chain_multiplier_multiplicative_boost","label":"Chain Multiplier: Multiplicative Boost","minTurns":null,"isCompleteRemoval":fals