      INSERT INTO character_details (character_id, detail_json)
      VALUES (3721, '{"characterId":3721,"captainAbility":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [INT], Driven and Powerhouse characters by 5.25x and boosts HP of [INT], Driven and Powerhouse characters by 1.3x. If you use \"Resonating Tot Musica: Finale\" on this character, boosts ATK of [INT], Driven and Powerhouse characters by 5.5x for 3 turns instead. If there is only 1 enemy on the stage, reduces damage received by 40%.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [INT], Driven and Powerhouse characters by 5.25x and boosts HP of [INT], Driven and Powerhouse characters by 1.3x. If you use \"Resonating Tot Musica: Finale\" on this character, boosts ATK of [INT], Driven and Powerhouse characters by 5.5x for 3 turns instead. If there is only 1 enemy on the stage, reduces damage received by 40%."}],"captainNotes":null,"specialName":"Resonating Tot Musica: Finale","specialText":"Applies a Turn Progress Effect for 3 turns that will apply the following effects: Start of Each Turn: Reduces crew''s current HP by 70% at the start of every turn. Turn 1 (Activation): Boosts Orb Effects of Driven and Powerhouse characters by 2.5x for 1 turn and boosts Color Affinity of Driven and Powerhouse characters by 2.25x for 1 turn. Turn 2: Boosts Orb Effects of Driven and Powerhouse characters by 2.75x for 1 turn and boosts Color Affinity of Driven and Powerhouse characters by 2.5x for 1 turn. Turn 3: Boosts Orb Effects of Driven and Powerhouse characters by 3x for 1 turn and boosts Color Affinity of Driven and Powerhouse characters by 2.75x for 1 turn. On Effect Removal by Enemy: Boosts Orb Effects of Driven and Powerhouse characters by 2.75x for 1 turn and boosts Color Affinity of Driven and Powerhouse characters by 2.5x for 1 turn. Effect Removal Condition & Effect: If your HP is below 70% at the end of your turn, removes Turn Progress Effect and binds themselves for 5 turns. If your crew has Turn Progress Effect when the special is activated, changes Effect Removal Condition & Effect to: If your HP is below 70% at the end of your turn, removes Turn Progress Effect and binds themselves for 5 turns; and changes the Start of Each Turn effect to: Reduces crew''s current HP by 30% at the start of every turn. If your crew has Turn Progress Effect when the special is activated, increases duration of any ATK boosting buffs buffs by 2 turns, locks all orbs for 2 turns and adds 1.4x to Chain multiplier for 3 turns.","specialNotes":null,"superSpecialText":"Increases boost effects of Orb Amplification and Color Affinity buffs applied by Driven and Powerhouse characters by 0.25x for 3 turns, changes all orbs of top and bottom row characters into Matching orbs and transforms Driven characters into Super Driven characters.","superSpecialCriteriaText":"This character must be captain and your crew must have Orb Effect and Color Affinity.","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must have Orb Effect and Color Affinity.","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"},"partyConflictKeys":["uta"],"characterTags":["Paramythia-type"],"builderAbilities":[{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_ally_status_effect","label":"Apply Status Effect (Ally)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_driven","label":"HP Boost: Driven","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_slot_bind_resistance","label":"Slot Bind Resistance","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_atk_boost","label":"ATK Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"},{"key":"support_slot_effect_boost","label":"Slot Effect Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Makes [PSY] and [INT] orbs beneficial for Driven characters. Boosts base HP of Driven characters by 1.1x"],"sailorNotes":null,"potentialAbilities":[{"Name":"Reduce Slot Bind duration","description":["Reduces Slot Bind duration by 10 turns on this character"]},{"Name":"Pinch Healing","description":["If HP is below 50% at the start of the turn, recovers 2x this character''s RCV at the