      INSERT INTO character_details (character_id, detail_json)
      VALUES (3787, '{"characterId":3787,"captainAbility":"Boosts ATK of Striker and Driven characters by 5.25x, by 5.5x instead if they have a beneficial orb, boosts HP of Striker and Driven characters by 1.5x, makes [INT] and [TND] orbs beneficial for Striker and Driven characters, changes [RCV] orbs into [WANO] orbs, reduces Special Bind duration by 10 turns on this character and restores Special Cooldown of this character by 10 turns when it is rewinded. If a crew member uses a special with an ATK UP, Orb Effect or Color Affinity buff, increases boost effects of those ATK Up, Orb Amplification and Color Affinity buffs by +0.25x.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of Striker and Driven characters by 5.25x, by 5.5x instead if they have a beneficial orb, boosts HP of Striker and Driven characters by 1.5x, makes [INT] and [TND] orbs beneficial for Striker and Driven characters, changes [RCV] orbs into [WANO] orbs, reduces Special Bind duration by 10 turns on this character and restores Special Cooldown of this character by 10 turns when it is rewinded. If a crew member uses a special with an ATK UP, Orb Effect or Color Affinity buff, increases boost effects of those ATK Up, Orb Amplification and Color Affinity buffs by +0.25x."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of Striker and Free Spirit characters by 5.5x, by 5.75x instead if they have a beneficial orb, boosts HP of Striker and Free Spirit characters by 1.3x, makes [TND] orbs beneficial for Striker and Free Spirit characters, boosts chances of getting [TND] orbs and reduces Despair duration by 10 turns."}],"captainNotes":"Kaido: The Boost buffs are stackable with other effects.","specialName":"Vajra Arrow • Hallowed Glacier Slash","specialText":"Removes all positive buffs on your team, reduces Special Cooldown of all characters by 20 turns, changes all orbs, including [BLOCK] orbs, of left column characters into [TND] orbs, changes all orbs, including [BLOCK] orbs, of right column characters into [WANO] orbs, boosts Orb Effects Striker and Driven characters by 3.25x for 2 turns and boosts ATK of Striker and Driven characters by 3x for 2 turns. Limits Special Uses to 2.. Changes all orbs, including [BLOCK] orbs, of right column characters into [TND] orbs, changes all orbs, including [BLOCK] orbs, of left column characters into [WANO] orbs and boosts ATK of Striker and Free Spirit characters by 3x for 1 turn. If your Captain is a Striker or Free Spirit character, boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 3 turns. If your crew has Crew Damage Reduction ATK UP when the special is activated, boosts Orb Effects of Striker and Free Spirit characters by 2.75x for 1 turn and reduces damage received by 80% for 1 turn.","specialNotes":"Kaido: This special removes the ability to activate more than 2 Specials total after the Special has been used. If you use another special that limits Special uses, you can not use any more Specials.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kaido vs yamato","yamato"],"characterTags":[],"builderAbilities":[{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_crew","label":"RCV Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_crew","label":"HP Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"}],"sailorAbilities":["Restores Special Cool