      INSERT INTO character_details (character_id, detail_json)
      VALUES (3791, '{"characterId":3791,"captainAbility":"Reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [QCK], Cerebral and Free Spirit characters by 5.25x, boosts HP of [QCK], Cerebral and Free Spirit characters by 1.25x and increases duration of any Status ATK boosting buffs applied by Specials by 1 turn. If you use \"Demonio Fleur: Grand Jacuzzi Clutch\" on this character, boosts ATK of [QCK], Cerebral and Free Spirit characters by 5.5x instead and reduces damage received by 30% for 3 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [QCK], Cerebral and Free Spirit characters by 5.25x, boosts HP of [QCK], Cerebral and Free Spirit characters by 1.25x and increases duration of any Status ATK boosting buffs applied by Specials by 1 turn. If you use \"Demonio Fleur: Grand Jacuzzi Clutch\" on this character, boosts ATK of [QCK], Cerebral and Free Spirit characters by 5.5x instead and reduces damage received by 30% for 3 turns."}],"captainNotes":null,"specialName":"Demonio Fleur: Grand Jacuzzi Clutch","specialText":"Deals 20% of enemies'' current HP in True damage to all enemies. If your Captain is a Cerebral character, allows crew to stack 2 different Status ATK Boost buffs for 3 turns. If you Captain is a Free Spirit character, allows crew to stack 2 different Status ATK Boost buffs for 1 turn. Boosts ATK against enemies with reduced defense by 2.25x for 2 turns. If enemies have Defense Reduction Debuff Protection or All Debuff Protection when the special is activated, ignores Defense Reduction Debuff Protection and reduces the defense of all enemies by 80% for 1 turn, reduces the defense of all enemies by 80% for 2 turns otherwise.","specialNotes":"Special requires testing for more information.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"sup