      INSERT INTO character_details (character_id, detail_json)
      VALUES (3805, '{"characterId":3805,"captainAbility":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts ATK of Cost 40 or less characters by 5.25x, boosts ATK of all other characters by 4.5x, boosts HP of all characters by 1.2x and makes [QCK] and [INT] orbs beneficial for all characters.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts ATK of Cost 40 or less characters by 5.25x, boosts ATK of all other characters by 4.5x, boosts HP of all characters by 1.2x and makes [QCK] and [INT] orbs beneficial for all characters."}],"captainNotes":null,"specialName":"Toy Revenge","specialText":"Changes all orbs into Matching orbs and select up to 5 characters to become Toy Bears with 40 cost and 2,750 base ATK for 3 turns.","specialNotes":"Toy Bears will automatically attack after Sugar attacks. Sugar and Toy Bears will ignore barriers and gain +0.8x chain addition on HOBBY-HOBBY hit, instead of +0.3x for PERFECTs. Toy Bears are immune to some debuffs including, but not limited to, Bind, Stun, Paralysis and Burn. Auto-attacking Toy Bears will hit a HOBBY-HOBBY tap timing, which is similar to a PERFECT.","superSpecialText":"Reduces Special Cooldown of this character by 3 turns, boosts Orb Effects of Cost 40 or less characters by 2.25x for 3 turns and transforms [QCK] characters into Super [QCK] characters.","superSpecialCriteriaText":"This character must be captain and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Donquixote Doflamingo, Trebol, Diamante, Pica, Monet or Toy Bears.","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Donquixote Doflamingo, Trebol, Diamante, Pica, Monet or Toy Bears.","