      INSERT INTO character_details (character_id, detail_json)
      VALUES (3824, '{"characterId":3824,"captainAbility":"Boosts ATK of Striker and Driven characters by 5.25x, boosts HP of Striker and Driven characters by 1.2x, makes [STR], [DEX] and [RCV] orbs beneficial for Striker and Driven characters, reduces damage received by 10% and restores Special Cooldown of all characters by 10 turns when they are rewinded.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Striker and Driven characters by 5.25x, boosts HP of Striker and Driven characters by 1.2x, makes [STR], [DEX] and [RCV] orbs beneficial for Striker and Driven characters, reduces damage received by 10% and restores Special Cooldown of all characters by 10 turns when they are rewinded."}],"captainNotes":null,"specialName":"Biting Candy Maiden","specialText":"Deals 10% of enemies'' current HP in damage to all enemies, reduces Special Cooldown of Striker and Driven characters by 1 turn, locks orbs for Striker and Driven characters for 1 turn and reduces damage received by 60% for 1 turn. If your Captain is a Striker or Driven character, sets Chain Boundaries to 2.75x and 10.0x for 1 turn.. Deals 10% of enemies'' current HP in damage to all enemies, reduces Special Cooldown of Striker and Driven characters by 2 turns, barriers Striker and Driven character''s orbs for 1 GREAT hit and reduces damage received by 95% for 1 turn. If your Captain is a Striker or Driven character, sets Chain Boundaries to 3.25x and 15.0x for 1 turn. If your crew has Chain Lock when the special is activated, boosts base ATK of Striker and Driven characters by 1,500 for 1 turn.","specialNotes":null,"superSpecialText":"Changes [STR], [DEX], [QCK], [PSY], [INT] and [BLOCK] orbs into Matching orbs, reduces enemies'' Striker Resistance by -30% for 1 turn and transforms Striker characters into Super Striker characters.","superSpecialCriteriaText":"This character must be captain and your crew must consist of any 6 of the following, excluding Supports and co