      INSERT INTO character_details (character_id, detail_json)
      VALUES (3877, '{"characterId":3877,"captainAbility":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts ATK of [STR] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs and reduces Bind duration by 10 turns. If this character defeats an enemy, reduces Switch Effect of this character by 1.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts ATK of [STR] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs and reduces Bind duration by 10 turns. If this character defeats an enemy, reduces Switch Effect of this character by 1."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Striker and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts RCV of all characters by 1.2x, boosts ATK of [DEX] and Free Spirit characters by 5x, boosts ATK of all other characters by 4.5x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, reduces damage received by 25% and reduces Bind duration by 10 turns. After each turn you take damage, reduces Switch Effect of this character by 1."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of [STR], [DEX], [QCK] characters by 2 turns at the start of the fight, reduces Special Cooldown of Fighter, Striker and Free Spirit characters by 1 turn at the start of the fight, boosts HP of all characters by 1.3x, boosts RCV of all characters by 1.2x, boosts ATK of [STR], [DEX], [QCK] and Free Spirit characters by 6x, boosts ATK of all other characters by 5.25x, makes [STR], [DEX], [RCV] and [TND] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs, reduces damage received by 30% and reduces Bind duration by 10 turns."}],"captainNotes":null,"specialName":"Club and Fists Beatdown","specialText":"Reduces Special Cooldown of all characters by 1 turn, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 3x for 1 turn, reduces damage received by 60% for 1 turn, changes orbs of adjacent characters into [RCV] orbs, inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn and becomes Luffy & Yamato for 3 turns. If your crew has Orb Amplification and Percent Damage Reduction when the special is activated, increases duration of any ATK UP, Orb Amplification and Chain Lock/Limit/Boundary buffs/debuffs by 1 turn.. Reduces Special Cooldown of all characters by 2 turns, boosts Orb Effects of [STR], [DEX] and [QCK] characters by 3.25x for 2 turns, reduces damage received by 80% for 1 turn, changes orbs of adjacent characters into [WANO] orbs, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2x for 1 turn and becomes Luffy & Yamato for 3 turns. If your crew has Orb Amplification and Percent Damage Reduction when the special is activated, increases duration of any ATK UP, Orb Amplification and Chain Lock/Limit/Boundary buffs/debuffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["luffy & yamato","luffy","yamato"],"characterTags":["Straw Hat Pirates","Worst Generation","Paramyth