      VALUES (3907, '{"characterId":3907,"captainAbility":"Reduces Special Cooldown of [PSY] and Powerhouse characters by 1 turn at the start of the fight, boosts ATK of [PSY] and Powerhouse characters by 5.5x, by 5.75x instead if HP is below 30% at the start of the turn, boosts HP of [PSY] and Powerhouse characters by 1.5x, makes [TND] orbs beneficial for [PSY] and Powerhouse characters, boosts chances of getting [TND] orbs, makes crew immune to Blow Away and reduces Despair duration by 10 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of [PSY] and Powerhouse characters by 1 turn at the start of the fight, boosts ATK of [PSY] and Powerhouse characters by 5.5x, by 5.75x instead if HP is below 30% at the start of the turn, boosts HP of [PSY] and Powerhouse characters by 1.5x, makes [TND] orbs beneficial for [PSY] and Powerhouse characters, boosts chances of getting [TND] orbs, makes crew immune to Blow Away and reduces Despair duration by 10 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of [DEX] and Powerhouse characters by 1 turn at the start of the fight, boosts ATK of [DEX] and Powerhouse characters by 5.5x, by 5.75x instead if HP is below 30% at the start of the turn, boosts HP of [DEX] and Powerhouse characters by 1.65x, makes [TND] orbs beneficial for [DEX] and Powerhouse characters, boosts chances of getting [TND] orbs and reduces crew''s current HP by 10% at the end of each turn. If a crew member uses a special with a Despair debuff, including Support Abilities, or you are inflicted with Despair, replaces that debuff with a Chain boost that will overwrite Chain boosts in the same special: Adds 1.2x to Chain multiplier for 3 turns."}],"captainNotes":"Blackbeard: If a Chain Addition is applied, Despair debuffs will still affect the crew.","specialName":"Tremoring Armosphere • All-Consuming Darkness","specialText":"Deals 1,000,000 Fixed True damage, ignoring Normal Attack Only, to all enemies, changes all orbs, including [BLOCK] orbs, into [TND] orbs and sets Chain Boundaries to 2.75x and 35.0x for 3 turns. If HP is above 50% when the special is activated, increases Chain Tap Timing Bonus of [PSY] and Powerhouse characters to +0.2x-0.6x for 1 turn depending on Tap Timing and after 1 turn, reduces crew''s current HP by 80%.. Deals 1,000,000 Fixed True damage, ignoring Normal Attack Only, to all enemies, changes all orbs, including [BLOCK] orbs, into [TND] orbs and boosts Orb Effects of [DEX] and Powerhouse characters by 2.5x for 3 turns and boosts base ATK of [DEX] and Powerhouse characters by 1,000-1,750 for 3 turns, depending on your current HP.","specialNotes":"Blackbeard: Current HP 51% or more: 1,000 base ATK. Current HP 21%-51%: 1,500. Current HP less than 21%: 1,750 base ATK.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["whitebeard vs blackbeard","blackbeard","marshall d teach"],"characterTags":[],"builderAbilities":[{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"delayed_effect_launch","label":"Delayed Effect Launch","minTurns":null,"is