      INSERT INTO character_details (character_id, detail_json)
      VALUES (3953, '{"characterId":3953,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts HP of Slasher characters by 1.3x, boosts ATK of Slasher charactrs by 5x, by 5.25x if HP is above 80% or below 25% at the start of the turn, makes [PSY], [RCV] and [TND] orbs beneficial for Slasher character and reduces Special Bind duration by 5 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts HP of Slasher characters by 1.3x, boosts ATK of Slasher charactrs by 5x, by 5.25x if HP is above 80% or below 25% at the start of the turn, makes [PSY], [RCV] and [TND] orbs beneficial for Slasher character and reduces Special Bind duration by 5 turns."}],"captainNotes":null,"specialName":"Kappa Style: River of Retribution","specialText":"Deals 100x character''s ATK in [PSY] True damage to all enemies. If HP is below 50% when the special is activated, changes orbs of this and adjacent characters into [WANO] orbs and locks all orbs for 1 turn. Reduces crew''s current HP by 60%, reduces Paralysis duration by 3 turns, reduces enemies'' Resilience duration by 3 turns and boosts base ATK of Slasher characters 1250 for 1 turn. If your crew has Base ATK Boost when the special is activated, increases boost effects of Base ATK Boost buffs by +250 and increases duration of any Base ATK Boost buffs by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kawamatsu"],"characterTags":[],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_resilience","label":"Remove Resilience","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"k