      INSERT INTO character_details (character_id, detail_json)
      VALUES (3955, '{"characterId":3955,"captainAbility":"Always Active: Boosts HP of [PSY] and Free Spirit characters by 1.2x, boosts chance of getting [PSY] and [RCV] orbs, makes [PSY] and [RCV] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs, reduces Bind duration by 10 turns and restores Special Cooldown of all characters by 10 turns when they are rewinded. Base Captain: Revives the team after a GAME OVER 1 time per adventure and becomes Gear Five. Boosts ATK of [PSY] and Free Spirit characters by 5.5x, boosts ATK of all other characters by 4.5x and reduces damage received by 20%. Gear 5 Captain: Attacks will ignore damage reducing Barriers and Buffs. Boosts ATK of [PSY] and Free Spirit characters by 6x, boosts ATK of all other characters by 5x and reduces crew''s current HP by 10% at the end of each turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Always Active: Boosts HP of [PSY] and Free Spirit characters by 1.2x, boosts chance of getting [PSY] and [RCV] orbs, makes [PSY] and [RCV] orbs beneficial for all characters, makes PERFECTs consume [RCV] orbs, reduces Bind duration by 10 turns and restores Special Cooldown of all characters by 10 turns when they are rewinded. Base Captain: Revives the team after a GAME OVER 1 time per adventure and becomes Gear Five. Boosts ATK of [PSY] and Free Spirit characters by 5.5x, boosts ATK of all other characters by 4.5x and reduces damage received by 20%. Gear 5 Captain: Attacks will ignore damage reducing Barriers and Buffs. Boosts ATK of [PSY] and Free Spirit characters by 6x, boosts ATK of all other characters by 5x and reduces crew''s current HP by 10% at the end of each turn."}],"captainNotes":"Revive does not remove crew buffs or debuffs.","specialName":"Reality-Altering Powers","specialText":"Deals 2,000,000 Fixed True damage, ignoring Normal Attack Only, to one enemy, boosts Color Affinity of [PSY] Free Spirit characters by 3x for 1 turn, boosts Color Affinity of other [PSY] and Free Spirit characters by 2.75x for 1 turn, and changes all orbs, including [BLOCK] orbs, into [PSY] orbs. If this character is in Gear 5 when the special is activated, boosts Orb Effects of [PSY] Free Spirit characters by 3.25x for 1 turn, boosts Orb Effects of other [PSY] and Free Spirit characters by 2.75x for 1 turn, and reduces enemies'' positive buffs duration by 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["monkey d. luffy","luffy"],"characterTags":[],"builderAbilities":[{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_bind","label":"Remove Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"consume_slots","label":"Consume Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":3955,"basedOn":3956}}');


