      INSERT INTO character_details (character_id, detail_json)
      VALUES (3992, '{"characterId":3992,"captainAbility":"Boosts ATK of [PSY], Free Spirit, and Shooter characters by 5.25x, by 5.5x instead if they have a [PSY] or [TND] orb, boosts HP of [PSY], Free Spirit, and Shooter characters HP by 1.3x, makes [TND] orbs beneficial for [PSY], Free Spirit and Shooter characters, boosts chances of getting [TND] orbs, reduces Despair duration by 10 turns, and allows HP Overfill up to 2x MAX HP.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [PSY], Free Spirit, and Shooter characters by 5.25x, by 5.5x instead if they have a [PSY] or [TND] orb, boosts HP of [PSY], Free Spirit, and Shooter characters HP by 1.3x, makes [TND] orbs beneficial for [PSY], Free Spirit and Shooter characters, boosts chances of getting [TND] orbs, reduces Despair duration by 10 turns, and allows HP Overfill up to 2x MAX HP."}],"captainNotes":null,"specialName":"Song Against the Backlight","specialText":"Changes the orb, including [BLOCK] orb, of this character into a [TND] orb and barriers this character''s orb for 1 PERFECT hit. If this character is a Crewmate when the special is activated, optionally swaps this unit with your captain for 5 turns. Applies a Turn Progress Effect for 3 turns that will apply the following effects: Turn 1 (Activation): Reduces Special Bind duration by 6 turns, and boosts ATK of [PSY], Free Spirit and Shooter characters by 2.5x for 1 turn. Turn 2: Reduces Special Bind duration by 6 turns, boosts ATK of [PSY], Free Spirit and Shooter characters by 2.75x for 3 turns, and boosts ATK against delayed enemies by 2x for 3 turns Turn 3: Reduces Special Bind duration by 6 turns, and increases boost effects of ATK Up and Status ATK Boost buffs by +0.25x. On Effect Removal by Enemy: Boosts ATK of [PSY], Free Spirit and Shooter characters by 2.75x for 1 turn. If your crew has Turn Progress Effect when the special is activated, sets Chain Boundaries to 2.75x and 35.0x for 3 turns.","specialNotes