      INSERT INTO character_details (character_id, detail_json)
      VALUES (3994, '{"characterId":3994,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [PSY], Slasher, and Shooter characters by 4.75x, by 5x instead if they have a [PSY] or [TND] orb, boosts HP of [PSY], Slasher, and Shooter characters by 1.3x, boosts chances of getting [TND] orbs, makes [PSY], [INT] and [TND] orbs beneficial for [PSY], Slasher, and Shooter characters and makes crew immune to Blow Away. If your crew has 3 or more Slasher characters, deals 10% of enemies'' current HP in damage to all enemies at the end of each turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [PSY], Slasher, and Shooter characters by 4.75x, by 5x instead if they have a [PSY] or [TND] orb, boosts HP of [PSY], Slasher, and Shooter characters by 1.3x, boosts chances of getting [TND] orbs, makes [PSY], [INT] and [TND] orbs beneficial for [PSY], Slasher, and Shooter characters and makes crew immune to Blow Away. If your crew has 3 or more Slasher characters, deals 10% of enemies'' current HP in damage to all enemies at the end of each turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [INT], Shooter, and Slasher characters by 4.75x, by 5x instead if they have a [INT] or [TND] orb, boosts HP of [INT], Shooter, and Slasher characters by 1.3x, boosts chances of getting [TND] orbs and makes [PSY], [INT] and [TND] orbs beneficial for [INT], Shooter, and Slasher characters. If your crew has 3 or more Shooter characters, adds 0.2x to Chain multiplier."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [PSY], [INT], Slasher, and Shooter characters by 5.25x, by 5.5x 