op and bottom row characters into [RAINBOW] orbs, boosts base ATK of all characters by 800 for 1 turn, and increases duration of any Base ATK Boost buffs by 1 turn, including effects activated in the same Ability and transforms [QCK] characters into Super [QCK] characters.","superSpecialCriteriaText":"This character must be captain and your crew must consist of all of the following, excluding Supports: Fighter, Slasher, Shooter, Free Spirit, Cerebral, Powerhouse characters","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must consist of all of the following, excluding Supports: Fighter, Slasher, Shooter, Free Spirit, Cerebral, Powerhouse characters","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"class_or_type_presence_all","requiredClasses":["Fighter","Slasher","Shooter","Free Spirit","Cerebral","Powerhouse"],"requiredTypes":[]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["gild tesoro","tesoro"],"characterTags":["Gran Tesoro","Paramythia-type"],"builderAbilities":[{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"chain_multiplier_lock","label":"Chain Multiplier: Lock","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],