      INSERT INTO character_details (character_id, detail_json)
      VALUES (4004, '{"characterId":4004,"captainAbility":"Boosts ATK of all characters by 3.25x and gives chance of duplicating a drop upon completion of the island.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 3.25x and gives chance of duplicating a drop upon completion of the island."}],"captainNotes":null,"specialName":"Betting for Freedom","specialText":"Applies various effects depending on the character''s Support Character''s type, Captain''s type, character''s orb, and current HP percentage when the Special is activated. ConditionEffectCaptain Type[STR] or [DEX]Deals 80x character''s ATK in [QCK] damage to all enemies at the end of the turn for 3 turns[QCK]Reduces Special Cooldown of all characters by 2 turns.[PSY] or [INT]Reduces Switch Effect and VS Gauge of all characters by 2 turns.Character''s Orb[STR], [DEX], [QCK], [PSY] or [INT]Reduces enemies'' Corresponding Type Resistance by -20% for 1 turn.[RCV] or [TND]Locks all orbs for 1 turn and adds 1.1x to Chain multiplier for 1 turn.[G] or [RAINBOW]Reduces enemies'' [STR], [DEX], [QCK], [PSY] and [INT] Resistance by -20% for 1 turn and barriers all character''s orbs for 1 GREAT hit.[SEMLA], [BLOCK] or [SUPERBLOCK]Increases damage received by 2x for 3 turns.Percent HP100%-80.01%Reduces damage received by 80% for 1 turn.80%-50.01%Recovers 20,000 HP.50%-10.01%Reduces damage received by 100% for 1 turn. Recovers all missing HP.Support Character Type[STR]Boosts ATK of all characters by 2x for 3 turns.[DEX]Boosts ATK of all characters by 2.25x for 2 turns.[QCK]Boosts ATK of all characters by 2.5x for 1 turn.[PSY]Increases boost effects of ATK UP buffs by +0.3x.[INT]Increases boost effects of ATK UP buffs to 2.5x.NoneBoosts Orb Effects of all characters by 2.25x for 2 turns.","specialNotes":"The following orbs have no effects: [WANO], [EMPTY], [BOMB]. Other orbs are untested.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["raise max","max"],"characterTags":[],"builderAbilities":[{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_resistance_reduction","label":"Resistance Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extra_drop_any","label":"Any Extra Drop","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_recover_special_bind","label":"Status Effect Recovery: Special Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_critical_atk","label":"Critical ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source