      INSERT INTO character_details (character_id, detail_json)
      VALUES (4019, '{"characterId":4019,"captainAbility":"Reduces Special Cooldown of [STR], [DEX], and [PSY] characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX], and [PSY] characters by 5.25x, by 5.75x If you use \"Scorching Onslaught of Power\" in this turn instead, boosts HP of [STR], [DEX], and [PSY] characters by 1.2x, and has a chance to ignore Debuff Protection and inflicts all enemies with Burn that will deal 100x enemies'' ATK in damage for 2 turns and reduces the defense of all enemies by 100% for 2 turns based on damage dealt in previous turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [STR], [DEX], and [PSY] characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX], and [PSY] characters by 5.25x, by 5.75x If you use \"Scorching Onslaught of Power\" in this turn instead, boosts HP of [STR], [DEX], and [PSY] characters by 1.2x, and has a chance to ignore Debuff Protection and inflicts all enemies with Burn that will deal 100x enemies'' ATK in damage for 2 turns and reduces the defense of all enemies by 100% for 2 turns based on damage dealt in previous turn."}],"captainNotes":"Debuff chance is based on damage dealt with normal attacks and does not stack with any other debuff specials or effects. Base Chances. 100,000 damage or more: 20% chance to debuff. 500,000 damage or more: 50% chance to debuff. 1,000,000 damage or more: 100% chance to debuff. 2,000,000 damage or more: 100% chance to debuff ignoring Debuff Protection","specialName":"Scorching Onslaught of Power","specialText":"If HP is above 61% when the special is activated, reduces crew''s current HP by 60% crew''s MAX HP and advances Special Cooldown of this character to MAX. Boosts chances of getting Matching orbs for 1 turn, randomizes non-Matching, non-[RCV] or non-[TND] orbs, including [BLOCK] orbs and boosts ATK against enemies with reduced defense by 2.5x for 2 turns. If your crew has Status ATK Boost when the special is activated, adds 1.5x to Chain multiplier for 2 turns. If your crew has Chain Addition when the special is activated, boosts base ATK of all characters by 1250 for 2 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["katakuri & oven","katakuri","oven"],"characterTags":[],"builderAbilities":[{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_rcv","label":"Boost RCV","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4019,"basedOn":4020}}');


