      INSERT INTO character_details (character_id, detail_json)
      VALUES (4022, '{"characterId":4022,"captainAbility":"Reduces crew''s current HP by 50% at the start of the fight, boosts HP of all characters by 1.3x and boosts ATK of [STR], Free Spirit, and Powerhouse characters by 3.5x, by 4x if HP is below 50% at the start of the turn otherwise.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces crew''s current HP by 50% at the start of the fight, boosts HP of all characters by 1.3x and boosts ATK of [STR], Free Spirit, and Powerhouse characters by 3.5x, by 4x if HP is below 50% at the start of the turn otherwise."}],"captainNotes":null,"specialName":"Cleaving Strike","specialText":"If HP is below 50% when the special is activated, advances Special Cooldown of this character by 4 turns. Deals 10% of enemies'' current HP in damage to one enemy, reduces enemies'' Percent Damage Reduction and Threshold Damage Reduction duration by 3 turns, boosts Color Affinity of all characters by 2x for 1 turn, and advances Special Cooldown of this character by 1-7 turns depending on how many times this character used \"Cleaving Strike\" this adventure.","specialNotes":"7 turns for 0 times, 3 turns for 1 time, 1 turn for 2 times or more","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["rockstar"],"characterTags":[],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slot