      INSERT INTO character_details (character_id, detail_json)
      VALUES (4040, '{"characterId":4040,"captainAbility":"Reduces Special Cooldown of Slasher and Free Spirit characters by 2 turns at the start of the fight, boosts HP of Slasher and Free Spirit characters by 1.35x, boosts ATK of Slasher and Free Spirit characters by 5.25x and makes [RCV] and [TND] orbs beneficial for Slasher and Free Spirit characters. If your crew has 4 or more Slasher characters, boosts ATK of Slasher and Free Spirit characters by 5.5x instead and adds 0.2x to Chain multiplier.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Slasher and Free Spirit characters by 2 turns at the start of the fight, boosts HP of Slasher and Free Spirit characters by 1.35x, boosts ATK of Slasher and Free Spirit characters by 5.25x and makes [RCV] and [TND] orbs beneficial for Slasher and Free Spirit characters. If your crew has 4 or more Slasher characters, boosts ATK of Slasher and Free Spirit characters by 5.5x instead and adds 0.2x to Chain multiplier."}],"captainNotes":null,"specialName":"Return of the Shogun Clan After Two Decades","specialText":"Reduces enemies'' Increased Defense and Threshold Damage Reduction duration by 7 turns. If your crew has 3 or fewer Slasher characters when the special is activated, sets Chain Boundaries to 2.75x and 30.0x for 2 turns. If your crew has 4 or more Slasher characters when the special is activated, sets Chain Boundaries to 3.0x and 30.0x for 3 turns, boosts Final Tap ATK of Slasher and Free Spirit characters by 30%, and boosts Final Tap ATK of Slasher and Free Spirit characters by 10% when a Slasher or Free Spirit character uses an ATK UP or Orb Amplification special for 3 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kozuki momonosuke","momonosuke"],"characterTags":[],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased