      INSERT INTO character_details (character_id, detail_json)
      VALUES (4054, '{"characterId":4054,"captainAbility":"Boosts ATK of [DEX], Free Spirit, and Powerhouse characters by 5.25x, by 5.5x instead if they have a [RCV], [TND], [WANO] or [SEMLA] orb, boosts RCV of [DEX], Free Spirit, and Powerhouse characters by 1.35x, makes [RCV], [TND] and [SEMLA] orbs beneficial for all characters, recovers 4,000 HP at the end of each turn, and allows HP Overfill up to 2x MAX HP.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [DEX], Free Spirit, and Powerhouse characters by 5.25x, by 5.5x instead if they have a [RCV], [TND], [WANO] or [SEMLA] orb, boosts RCV of [DEX], Free Spirit, and Powerhouse characters by 1.35x, makes [RCV], [TND] and [SEMLA] orbs beneficial for all characters, recovers 4,000 HP at the end of each turn, and allows HP Overfill up to 2x MAX HP."}],"captainNotes":null,"specialName":"Rally for Friends","specialText":"Recovers 15x character''s RCV in HP, allowing HP Overfill up to 2x MAX HP, reduces Despair and Bind duration by 4 turns, changes orbs, including [BLOCK] orb, of this and adjacent characters into [TND] orbs, increases boost effects of Orb Amplification and Status ATK Boost buffs by +0.25x, and increases boost effects of Orb Amplification and Status ATK Boost buffs applied by all characters by 0.25x for 1 turn. Recovers 30x character''s RCV in HP, allowing HP Overfill up to 2x MAX HP, reduces Despair and Bind duration by 7 turns, changes the orb, including [BLOCK] orb, of this character into a [TND] orb, changes orbs, including [BLOCK] orbs, of adjacent characters into [WANO] Orbs, increases boost effects of Orb Amplification and Status ATK Boost buffs by +0.5x, and increases boost effects of Orb Amplification and Status ATK Boost buffs applied by all characters by 0.5x for 1 turn.","specialNotes":null,"superSpecialText":"Recovers 20x character''s RCV in HP, ignores Defense Reduction Debuff Protection and reduces the defense of all enemies by 50% for 1 turn, bo