      INSERT INTO character_details (character_id, detail_json)
      VALUES (4059, '{"characterId":4059,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, reduces Special Cooldown of all characters by 1 turn at start of Battle 3, boosts HP of Striker and Slasher characters by 1.35x, boosts ATK of Striker and Slasher characters by 5.5x, boosts ATK of all other characters by 4.75x, makes [QCK], [RCV] and [TND] orbs beneficial for Striker and Slasher characters, and reduces Bind duration by 10 turns. Up to 14 times per adventure but up to 5 times per turn, when any other Striker or Slasher crewmate uses a Special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, reduces Special Cooldown of all characters by 1 turn at start of Battle 3, boosts HP of Striker and Slasher characters by 1.35x, boosts ATK of Striker and Slasher characters by 5.5x, boosts ATK of all other characters by 4.75x, makes [QCK], [RCV] and [TND] orbs beneficial for Striker and Slasher characters, and reduces Bind duration by 10 turns. Up to 14 times per adventure but up to 5 times per turn, when any other Striker or Slasher crewmate uses a Special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, reduces Special Cooldown of this character by 4 turns at the start of Stage 3, boosts HP of Striker and Slasher characters by 1.35x, boosts ATK of Striker and Slasher characters by 5.5x, boosts ATK of all other characters by 4.75x, makes [DEX], [RCV] and [TND] orbs beneficial for Striker and Slasher characters, and reduces Bind duration by 10 turns. Up to 14 times per adventure but up to 5 times per turn, when any other Striker or Slasher crewmate uses a Special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, reduces Special Cooldown of this character by 5 turns at the start of Stage 3, and reduces Special Cooldown of all characters by 1 turn at the start of Batte 3, boosts HP of Striker and Slasher characters by 1.5x, boosts ATK of Striker and Slasher characters by 6x, boosts ATK of all other characters by 5x, makes [DEX], [QCK], [RCV] and [TND] orbs beneficial for Striker and Slasher characters, and reduces Bind duration by 10 turns. Up to 14 times per adventure but up to 5 times per turn, when any other Striker or Slasher crewmate uses a Special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 10%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value."}],"captainNotes":null,"specialName":"Chain Cutting Strike","specialText":"Deals 100x character''s ATK in Typeless True Fixed damage to all enemies, reduces enemies'' Percent Damage Reduction duration by 7 turns, boosts Color Affinity of Striker a