t"},{"key":"remove_bind","label":"Remove Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"final_tap_atk_boost","label":"Final Tap ATK Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_slasher","label":"ATK Boost: Slasher","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK of Striker and Slasher characters by 100. Boosts base ATK of Striker and Slasher characters by 150"],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":{"base":"Removes Despair and Slot Bind duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a [WANO] orb, and boosts Final Tap ATK of all characters by 5%.","super":"Removes Despair and Slot Bind duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a [WANO] orb, changes orbs, including [BLOCK] orbs, of adjacent characters into [TND] orbs, boosts Final Tap ATK of all characters by 10%, reduces enemies'' Striker and Slasher Resistance by -20% for 1 turn, and becomes Yamato - Determined to Fight Alongside the Land of Wano for 3 turns.","superTurns":9},"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4059,"basedOn":4060}}');


