 Cerebral characters","superSpecialCriteriaText":"This character must be captain and your crew must consist of any 6 or 1 of the following, excluding Supports and counting only 1 per unit: Cerebral characters; or Monkey D. Luffy, Shakuyaku, Boa Sandersonia, Boa Marigold, Silvers Rayleigh","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must consist of any 6 or 1 of the following, excluding Supports and counting only 1 per unit: Cerebral characters; or Monkey D. Luffy, Shakuyaku, Boa Sandersonia, Boa Marigold, Silvers Rayleigh","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"},"partyConflictKeys":["boa hancock","hancock"],"characterTags":["Kuja Pirates","Paramythia-type","Land of Wano Arc"],"builderAbilities":[{"key":"remove_pain","label":"Remove Pain","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_delay","label":"Delay","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemo