      INSERT INTO character_details (character_id, detail_json)
      VALUES (4099, '{"characterId":4099,"captainAbility":"Attacks will ignore damage reducing Barriers and Buffs. Boosts ATK of Driven and Powerhouse characters by 5x, by 5.75x instead if you have a Striker, Shooter, Fighter and Slasher character on your crew, boosts HP of Driven and Powerhouse characters by 1.2x, and makes [DEX], [QCK] and [TND] orbs beneficial for Driven and Powerhouse characters. If a crew member uses a special with a Threshold Damage Reduction buff and if you have a Striker, Shooter, Fighter and Slasher character on your crew, replaces those buffs with a Status ATK boost that will overwrite Status ATK boosts in the same special: Boosts ATK against enemies inflicted with Increase Damage Taken by 2.25x for 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Attacks will ignore damage reducing Barriers and Buffs. Boosts ATK of Driven and Powerhouse characters by 5x, by 5.75x instead if you have a Striker, Shooter, Fighter and Slasher character on your crew, boosts HP of Driven and Powerhouse characters by 1.2x, and makes [DEX], [QCK] and [TND] orbs beneficial for Driven and Powerhouse characters. If a crew member uses a special with a Threshold Damage Reduction buff and if you have a Striker, Shooter, Fighter and Slasher character on your crew, replaces those buffs with a Status ATK boost that will overwrite Status ATK boosts in the same special: Boosts ATK against enemies inflicted with Increase Damage Taken by 2.25x for 1 turn."}],"captainNotes":null,"specialName":"Darkness of Despair","specialText":"If the enemy has Percent Damage Reduction or Threshold Damage Reduction Buff for 6 or more turns when the Special is activated, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.25x for 1 turn. If your crew has 5 or more characters with all the same of either [STR], [DEX], [QCK], [RCV] or [TND] orbs, boosts Orb Effects of [STR], Driven, and Powerhouse characters by 3x for 3 turns, preventing buff clears, increases boost effects of ATK UP buffs by +0.25x, and changes the orb, including [BLOCK] orb, of this character into a [TND] orb. If your crew has 5 or more characters with all the same of either [BLOCK], [PSY] or [INT], changes all orbs, including [BLOCK] orbs, into [EMPTY] orbs, increases Orb Effects of [EMPTY] orbs to 2.25x for 3 turns and boosts Orb Effects of [STR], Driven, and Powerhouse characters by 3x for 1 turn. Boosts Orb Effects of [STR], Driven, and Powerhouse characters by 2.75x for 1 turn otherwise, and inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["marshall d. teach","teach"],"characterTags":[],"builderAbilities":[{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4099,"basedOn":4100}}');


