      INSERT INTO character_details (character_id, detail_json)
      VALUES (4121, '{"characterId":4121,"captainAbility":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts HP of Driven and Cerebral characters by 1.2x, boosts ATK of Driven and Cerebral characters by 4.75x, by 5x instead if they have an [EMPTY], [G] or beneficial orb, makes [QCK] orbs beneficial for all characters, reduces damage received by 20%, and reduces Special Bind duration by 10 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts HP of Driven and Cerebral characters by 1.2x, boosts ATK of Driven and Cerebral characters by 4.75x, by 5x instead if they have an [EMPTY], [G] or beneficial orb, makes [QCK] orbs beneficial for all characters, reduces damage received by 20%, and reduces Special Bind duration by 10 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts HP of Driven and Cerebral characters by 1.2x, boosts ATK of Driven and Cerebral characters by 4.75x, by 5x instead if they have an [EMPTY], [G] or beneficial orb, makes [INT] orbs beneficial for all characters, recovers 0.3x this character''s RCV at the end of the turn for each time you hit a PERFECT, and reduces Special Bind duration by 10 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of Driven and Cerebral characters by 1 turn at the start of the fight, boosts HP of Driven and Cerebral characters by 1.2x, boosts ATK of Driven and Cerebral characters by 5.25x, by 6x instead if they have an [EMPTY], [G] or beneficial orb, makes [QCK] and [INT] orbs beneficial for all characters, recovers 0.5x this character''s RCV at the end of the turn for each time you hit a PERFECT, reduces damage received by 20%, and reduces Special Bind duration by 10 turns."}],"captainNotes":null,"specialName":"Assault of Strings and Toys","specialText":"Reduces enemies'' Barrier duration by 3 turns, deals 1x the damage dealt in Overkill Damage in the previous turn in Typeless damage to all enemies, and becomes Doflamingo & Sugar for 2 turns. Boosts Color Affinity of Driven and Cerebral characters by 2.25x-2.75x for 1 turn based on the number of status effects applied on enemy. If enemies have 8 or more status effects when the special is activated, increases boost effects of Color Affinity buffs by +0.25x, including effects activated in the same Ability. If your Captain is a Driven or Cerebral character, inflicts all enemies with Weaken by 1.5x, by 1.875x instead if enemies are inflicted with Increase Damage Taken, for 1 turn.","specialNotes":"2.25x for 0-2 effects, 2.5x for 3-5 effects, 2.75x for 6+ effects","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["doflamingo & sugar","doflamingo","sugar"],"characterTags":[],"builderAbilities":[{"key":"remove_enemy_barrier","label":"Remove Enemy Barrier","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"}],"sailorAbilities":["Makes [QCK] and [INT] orbs beneficial for Driven and Cerebral characters"],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":{"base":"Removes Despair duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a Matching orb, inflicts all enemies with Increase Damage Taken by 1.25x for 1 turn, and reduces the ATK of all enemies by 20% for 1 turn.","super":"Removes Despair duration completely on this character, changes the orb, including [BLOCK] orbs, of this character into a Matching orb, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn and reduces the ATK of all enemies by 50% for 1 turn.","superTurns":6},"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4121,"basedOn":4122}}');


