l":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_chain_multiplier_boost","label":"Chain Multiplier: Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Makes [DEX] orbs beneficial for Cerebral characters. Makes [QCK] orbs beneficial for [INT] characters"],"sailorNotes":null,"potentialAbilities":[{"Name":"Pinch Healing","description":["If HP is below 50% at the start of the turn, recovers 1x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character"]},{"Name":"Reduce Sailor Despair duration","description":["Reduces Sailor Despair duration by 5 turns on this character"]}],"supportData":[{"supportedCharactersText":"[INT] Cerebral characters","levelDescriptions":["Once per adventure, when the supported character uses an Orb Converting or Orb Randomizing special, increases boost effects of Chain Addition buffs by +0.2x."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4134,"patter