      INSERT INTO character_details (character_id, detail_json)
      VALUES (4135, '{"characterId":4135,"captainAbility":"Boosts ATK of [INT] and Cerebral characters by 3.5x, by 4.25x instead if they have a beneficial orb, boosts HP of [INT] and Cerebral characters by 1.35x, and makes [RCV] and [SEMLA] orbs beneficial for [INT] and Cerebral characters. If any characters has a [RCV] or [SEMLA] orb and you hit a PERFECT with them, keep their orb for the next turn. If a crew member uses a Special with Base ATK UP, increases boost effects of Base ATK Boost buffs by +250.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [INT] and Cerebral characters by 3.5x, by 4.25x instead if they have a beneficial orb, boosts HP of [INT] and Cerebral characters by 1.35x, and makes [RCV] and [SEMLA] orbs beneficial for [INT] and Cerebral characters. If any characters has a [RCV] or [SEMLA] orb and you hit a PERFECT with them, keep their orb for the next turn. If a crew member uses a Special with Base ATK UP, increases boost effects of Base ATK Boost buffs by +250."}],"captainNotes":null,"specialName":"Greed-Fulfilling Genius Scientist","specialText":"Binds self for 10 turns, reduces Counter-Heal and Counter-RCV duration by 6 turns, recovers 20% of crew''s MAX HP, recovers 10,000 HP at end of each turn for 3 turns, increases Chain Tap Timing Bonus of Cerebral characters to +0.2x-0.5x for 2 turns depending on Tap Timing, boosts base ATK of Cerebral characters by 1,000 for 2 turns, and increases boost effects of Base ATK Boost buffs by +500, including effects activated in the same Ability.","specialNotes":"GOOD +0.2; GREAT +0.4; PERFECT +0.5","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["dr. vegapunk \"york the greedy\"","greedy\""],"characterTags":["Vegapunk","Scientist","Egghead Arc"],"builderAbilities":[{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"spe