      INSERT INTO character_details (character_id, detail_json)
      VALUES (4136, '{"characterId":4136,"captainAbility":"Reduces Special Cooldown of Cerebral characters by 2 turns at the start of the fight, makes [TND], [BOMB] and [SUPERBOMB] orbs beneficial for Cerebral characters and boosts HP of Cerebral characters by 1.35x. If your crew has 6 Cerebral characters, boosts ATK of Cerebral characters by 5.25x, by 5.75x instead if they have a beneficial orb and reduces Paralysis and Bind duration by 10 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Cerebral characters by 2 turns at the start of the fight, makes [TND], [BOMB] and [SUPERBOMB] orbs beneficial for Cerebral characters and boosts HP of Cerebral characters by 1.35x. If your crew has 6 Cerebral characters, boosts ATK of Cerebral characters by 5.25x, by 5.75x instead if they have a beneficial orb and reduces Paralysis and Bind duration by 10 turns."}],"captainNotes":null,"specialName":"Infinite Possibilities of Science","specialText":"Reduces Special Bind duration by 10 turns, changes the orb, including [BLOCK] orbs, of this character into a [TND] orb, and barriers this character''s orb for 1 PERFECT hit. Allows you to select up to 2 of the following effects to launch, launched effects will bypass Special Interrupts: Boosts ATK of Cerebral characters by 2.75x, can be enhanced up to 2 times, for 1 turn. Boosts Orb Effects of Cerebral characters by 2.75x, can be enhanced up to 2 times, for 1 turn. Boosts Color Affinity of Cerebral characters by 2.5x, can be enhanced up to 2 times, for 1 turn. Boosts base ATK of Cerebral characters by 1,500, can be enhanced up to 2 times, for 1 turn. Adds 1.8x, can be enhanced up to 2 times, to Chain multiplier for 1 turn. Boosts ATK against delayed enemies, enemies with reduced defense and poisoned enemies by 2.5x, can be enhanced up to 2 times, for 1 turn. If your crew has 6 [INT] characters on your crew, changes Class 2 of all non-Cerebral Class 2 Powerhouse characters to Cerebral class for 1 turn. If this character is your Captain or Friend/Guest Captain, reduces enemies'' Cerebral Resistance by -20% for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["dr. vegapunk","vegapunk"],"characterTags":[],"builderAbilities":[{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_resistance_reduction","label":"Resistance Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"tap_timing_requirement","label":"Tap-Timing Requirement","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"class_change","label":"Class Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_bind","label":"Remove Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"}],"sailorAbilities":[],"sailorNotes":null,"potentialAbilities":[],"supportData":[],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4136,"basedOn":4137}}');


