      INSERT INTO character_details (character_id, detail_json)
      VALUES (4154, '{"characterId":4154,"captainAbility":"Reduces Special Cooldown of [DEX], Shooter and Free Spirit characters by 50% of Max Cooldown, rounded down, at the start of the fight, boosts ATK of [DEX], Shooter and Free Spirit characters by 6x-6.25x, depending on how many previous consecutive turns you have defeated an enemy, up to 4 turns, boosts ATK of all other characters by 4.5x, boosts HP of [DEX], Shooter and Free Spirit characters by 1.35x, makes [DEX], [PSY], [INT] and [TND] orbs beneficial for all characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and increases duration of any Orb Amplification buffs applied by Specials by 1 turn. If this character is your Captain and performs EXCELLENT with their Action Special, boosts ATK of [DEX], Shooter and Free Spirit characters by 6.5x instead for 3 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [DEX], Shooter and Free Spirit characters by 50% of Max Cooldown, rounded down, at the start of the fight, boosts ATK of [DEX], Shooter and Free Spirit characters by 6x-6.25x, depending on how many previous consecutive turns you have defeated an enemy, up to 4 turns, boosts ATK of all other characters by 4.5x, boosts HP of [DEX], Shooter and Free Spirit characters by 1.35x, makes [DEX], [PSY], [INT] and [TND] orbs beneficial for all characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and increases duration of any Orb Amplification buffs applied by Specials by 1 turn. If this character is your Captain and performs EXCELLENT with their Action Special, boosts ATK of [DEX], Shooter and Free Spirit characters by 6.5x instead for 3 turns."}],"captainNotes":null,"specialName":"Fleeing at Full Speed","specialText":"Reduces Special Cooldown of all characters by 1 turn, reduces Paralysis duration by 10 turns, reduces enemies'' Damage Nullification duration by 3 turns, and changes