      INSERT INTO character_details (character_id, detail_json)
      VALUES (4191, '{"characterId":4191,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [DEX], Slasher and Powerhouse characters by 4.25x, and boosts HP of [DEX], Slasher and Powerhouse characters by 1.5x. Boosts ATK of [DEX], Slasher and Powerhouse characters against enemies with reduced Defense by 1.2x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [DEX], Slasher and Powerhouse characters by 4.25x, and boosts HP of [DEX], Slasher and Powerhouse characters by 1.5x. Boosts ATK of [DEX], Slasher and Powerhouse characters against enemies with reduced Defense by 1.2x."}],"captainNotes":null,"specialName":"Forced Submission to the \"Superior Race\"","specialText":"Reduces Special Cooldown of [DEX], Slasher and Powerhouse characters by 1 turn, reduces the Defense of all enemies by 100% for 2 turns, reduces crew''s current HP by 50%, deals 30x the amount of HP subtracted in Typeless damage to all enemies, and reduces any damage received above 5,000 HP by 97% for 1 turn. If enemies have Percent Damage Reduction when the Special is activated, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 1.5x for 1 turn, and adds 1.1x to Chain Multiplier for 1 turn. If enemies have Threshold Damage Reduction when the Special is activated, boosts Base ATK of [DEX], Slasher and Powerhouse characters by 1,250 for 2 turns; after 1 turn, adds 1.3x to Chain Multiplier for 2 turns. If enemies have Increased Defense when the Special is activated, increases boost effects of enemies'' Increase Damage Taken debuffs by +0.25x and increases duration of any Base ATK Boost buffs by 1 turn, including effects activated in the same Ability. Boosts Base ATK of [DEX], Slasher and Powerhouse characters by 1,000 for 1 turn; after 1 turn, adds 1.2x to Chain Multiplier for 1 turn.","specialNo