      INSERT INTO character_details (character_id, detail_json)
      VALUES (4210, '{"characterId":4210,"captainAbility":"Boosts ATK of all characters by 5x-6x depending on the number of Free Spirit characters on the crew, boosts HP of all characters by 1.3x, and makes [QCK] and [RCV] orbs beneficial for all characters. If crew uses a special with an ATK Up buff, increases boost effects of ATK Up buff by +0.25x. If your crew has 4+ Free Spirit characters, reduces Burn and Bind duration by 10 turns. If your crew has 6 Free Spirit characters and field has Territory: Free Spirit, boosts ATK of Free Spirit characters by 6.5x. If your crew has 6 Free Spirit characters and crew uses a Special to reduce enemies'' Resilience, Percent Damage Reduction, Threshold Damage Reduction or Increased Defense, reduces the duration by 1 additional turn. If this character is your Captain and performs EXCELLENT with their Action Special, the following effects are added to this character''s Captain Ability for 3 turns: if crew uses a special with an Orb Amplification buff, increases boost effects of Orb Amplification buff by +0.25x; if your crew has 6 Free Spirit characters and crew uses a Special to reduce enemies'' Resilience, Percent Damage Reduction, Threshold Damage Reduction or Increased Defense, reduces the duration by 2 additional turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of all characters by 5x-6x depending on the number of Free Spirit characters on the crew, boosts HP of all characters by 1.3x, and makes [QCK] and [RCV] orbs beneficial for all characters. If crew uses a special with an ATK Up buff, increases boost effects of ATK Up buff by +0.25x. If your crew has 4+ Free Spirit characters, reduces Burn and Bind duration by 10 turns. If your crew has 6 Free Spirit characters and field has Territory: Free Spirit, boosts ATK of Free Spirit characters by 6.5x. If your crew has 6 Free Spirit characters and crew uses a Special to reduce enemies'' Resilience, Percent Damage Reduction, Threshold Damage Reduction or Increased Defense, reduces the duration by 1 additional turn. If this character is your Captain and performs EXCELLENT with their Action Special, the following effects are added to this character''s Captain Ability for 3 turns: if crew uses a special with an Orb Amplification buff, increases boost effects of Orb Amplification buff by +0.25x; if your crew has 6 Free Spirit characters and crew uses a Special to reduce enemies'' Resilience, Percent Damage Reduction, Threshold Damage Reduction or Increased Defense, reduces the duration by 2 additional turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of all characters by 5x-6x depending on the number of Driven characters on the crew, boosts HP of all characters by 1.3x, and makes [TND] orbs beneficial for all characters. If crew uses a special to inflict enemies with Increase Damage Taken, increases boost effects of enemies'' Increase Damage Taken debuffs by +0.5x. If your crew has 4+ Driven characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and reduces Paralysis duration by 10 turns. If your crew has 6 Driven characters, allows effects that inflict Defense Reduction, Paralysis, Burn, Delay, Negative, Poison, Increase Damage Taken, Weaken and ATK Down to ignore Debuff Protection. If your crew has 6 Driven characters and enemy is inflicted with 10+ Status Effects, boosts ATK of Driven characters by 6.5x, and the following effect is added to this character''s Captain Ability for 3 turns: deals 500x character''s ATK in [DEX] damage to all enemies at the end of each turn."}],"captainNotes":null,"specialName":"Collision of Fate-Deciding Powers","specialText":"Applies Territory: Free Spirit to the field for 3 turns, reduces ATK Down duration by 10 turns, and boosts ATK against enemies inflicted with Increase Damage Taken and enemies with reduced defense by 2.5x-3x for 2 turns depending on the outcome of Action Special. If your crew has ATK Up, Orb Amplification and Chain Lock when the special is activated, increases duration of any ATK Up, Orb Amplification and Chain Lock buffs by 2 turns. Sets Chain Boundaries to 3.0x and 35.0x for 1 turn. If your crew has 6 Free Spirit characters, increases boost effects of Status ATK Boost and Chain Lock buffs by +0.25x, including effects activated in the same Ability.. Deals 10% of enemies'' current HP in damage to all enemies, changes all orbs, including [BLOCK] orbs, of right column characters into [TND] orbs, changes all orbs, including [BLOCK] orbs, of left column characters into [WANO] orbs, increases boost effects of ATK Up buffs to 3.5x, and boosts ATK of Driven characters by 3x-4x for 1 turn depending on the number of Status Effects applied on enemy when Special is activated. If your crew has 6 Driven characters, reduces enemies'' Threshold Damage Reduction and Percent Damage Reduction duration by 10 turns, and ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.25x for 1 turn; reduces enemies'' Threshold Damage Reduction and Percent Damage Reduction by 6 turns, and inflicts all enemies with Increase Damage Taken by 2x for 1 turn otherwise.","specialNotes":". Character 1: 0-1: 1.0x, 0%; 2: 1.05x, 5%; 3: 1.1x, 10%; 4: 1.2x, 15%; 5: 1.35x, 20%; 6: 1.5x, 25%. Character 2: 3x for 0 effects, 3.25x for 1-3 effects, 3.5x for 4-6 effects, 3.75x for 7-9 effects, 4x for 10+ effects","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["luffy vs kaido","kaido"],"characterTags":[],"builderAbilities":[{"key":"remove_atk_down","label":"Remove ATK Down","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode"