      INSERT INTO character_details (character_id, detail_json)
      VALUES (4212, '{"characterId":4212,"captainAbility":"Reduces Special Cooldown of Free Spirit and Cerebral characters by 2 turns at the start of the fight, boosts ATK of Free Spirit and Cerebral characters by 5.75x-6.25x depending on number of Status Effects inflicted on Crew, boosts ATK of all other characters by 5x, changes [RCV] orbs into [WANO] orbs, makes [INT] and [TND] orbs beneficial for Free Spirit and Cerebral characters, and allows HP Overfill up to 2x MAX HP. If you have 6 Free Spirit characters in your crew, reduces Bind and Paralysis duration by 3 turns. If you have 6 Cerebral characters in your crew, restores Special Cooldown of all characters by 3 turns when they are rewinded, and reduces Despair duration by 3 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Free Spirit and Cerebral characters by 2 turns at the start of the fight, boosts ATK of Free Spirit and Cerebral characters by 5.75x-6.25x depending on number of Status Effects inflicted on Crew, boosts ATK of all other characters by 5x, changes [RCV] orbs into [WANO] orbs, makes [INT] and [TND] orbs beneficial for Free Spirit and Cerebral characters, and allows HP Overfill up to 2x MAX HP. If you have 6 Free Spirit characters in your crew, reduces Bind and Paralysis duration by 3 turns. If you have 6 Cerebral characters in your crew, restores Special Cooldown of all characters by 3 turns when they are rewinded, and reduces Despair duration by 3 turns."}],"captainNotes":"+0.1x for every 2 Status Effects","specialName":"Night Stroll in Wano","specialText":"Reduces 1 selected debuff duration by 7 turns, and boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. If your crew has 6 Free Spirit characters, boosts ATK of Free Spirit characters by 3.25x for 1 turn, and boosts Orb Effects of Free Spirit characters by 1.75, allowing override, for 1 turn. If your crew has 6 Cerebral characters, boosts Color Affinity of Cerebral characters by 3x for 1 turn, and increases boost effects of ATK Up and Orb Amplification buffs by +0.25x, including effects activated in the same Ability. If your crew has Percent Damage Reduction and End of Turn Healing when the special is activated, increases duration of any Percent Damage Reduction to ATK, End of Turn Healing and Percent Damage Reduction buffs by 2 turns, including effects activated in the same Ability.","specialNotes":"The debuff reduction only works on debuffs whose icons are located in the bottom left of the adventure screen, above the HP bar. This DOES NOT include: Bind, Despair, Paralysis, Special Bind, Slot Bind, and Target Lock.","superSpecialText":"Reduces damage received by 80% for 1 turn, recovers 10,000 HP at the end of the turn for 1 turn, boosts Super Class Effects of Free Spirit and Cerebral characters to 1.3x for 3 turns, recovers 20% of crew''s MAX HP, and transforms Free Spirit and Cerebral characters into Super Free Spirit and Super Cerebral characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Portgas D. Ace, Trafalgar Law, Eustass Kid, Kozuki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Oden","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Portgas D. Ace, Trafalgar Law, Eustass Kid, Kozuki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Oden","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","opti