      INSERT INTO character_details (character_id, detail_json)
      VALUES (4213, '{"characterId":4213,"captainAbility":"Reduces Special Cooldown of [STR], Slasher and Free Spirit characters by 2 turns at the start of the fight, boosts ATK of [STR], Slasher and Free Spirit characters by 5x-5.75x depending on the number of Slasher characters on the crew, makes [RCV] and [TND] orbs beneficial for all characters, and adds 0.3x to Chain multiplier. If crew is inflicted with Burn from a Special, Support Ability or Enemy Action, replaces that debuff with the following effect: boosts ATK of [STR], Slasher and Free Spirit characters by 2.75x for 2 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [STR], Slasher and Free Spirit characters by 2 turns at the start of the fight, boosts ATK of [STR], Slasher and Free Spirit characters by 5x-5.75x depending on the number of Slasher characters on the crew, makes [RCV] and [TND] orbs beneficial for all characters, and adds 0.3x to Chain multiplier. If crew is inflicted with Burn from a Special, Support Ability or Enemy Action, replaces that debuff with the following effect: boosts ATK of [STR], Slasher and Free Spirit characters by 2.75x for 2 turns."}],"captainNotes":null,"specialName":"Vow of the New Shogun","specialText":"Reduces Special Cooldown of all characters by 1 turn, reduces Despair, Counter-Healing and Counter-RCV duration by 6 turns, and changes orbs, including [BLOCK] orbs, of adjacent characters into [WANO] orbs. If your Captain is a Slasher or Free Spirit character, boosts Chain Multiplier Growth Rate by 1.5x for 1 turn; if during the following turn you score 2 PERFECT hits, boosts Chain Multiplier Growth Rate by 1.5x for 1 turn in the following turn. If enemies have 4 turns or more of Percent Damage Reduction, Increased Defense or Threshold Damage Reduction when special is activated, increases Chain Tap Timing Bonus of all characters to +0.3x-0.7x for 3 turns depending on Tap Timing; increases Chain Tap Timing Bon