      INSERT INTO character_details (character_id, detail_json)
      VALUES (4216, '{"characterId":4216,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Powerhouse and Striker characters by 5.5x-6x depending on the crew''s current HP, boosts HP of Powerhouse and Striker characters by 1.3x, makes [TND] orbs beneficial for Powerhouse and Striker character, and increases duration of any Chain Multiplier Growth Rate buffs applied by Specials by 2 turns. If HP is above 51% at the start of the turn, reduces damage received by 25%.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Powerhouse and Striker characters by 5.5x-6x depending on the crew''s current HP, boosts HP of Powerhouse and Striker characters by 1.3x, makes [TND] orbs beneficial for Powerhouse and Striker character, and increases duration of any Chain Multiplier Growth Rate buffs applied by Specials by 2 turns. If HP is above 51% at the start of the turn, reduces damage received by 25%."}],"captainNotes":null,"specialName":"Deadly Battle for His Sons","specialText":"Reduces Special Bind and Chain Coefficient Reduction duration by 6 turns. If your Captain is a Powerhouse or Striker character when the special is activated, boosts Chain Multiplier Growth Rate by 1.5x for 1 turn. If your crew has 3 turns or more of Chain Lock when the special is activated, decreases duration of any Chain Lock buffs by 2 turns and increases boost effects of Chain Lock buffs by +0.8x. If your Captain is a Powerhouse or Striker character and HP is below 51% when the special is activated, changes Class 1 of all non-Powerhouse characters to Powerhouse class for 1 turn and sets Chain Boundaries to 3.0x and 30.0x for 2 turns.. Reduces Special Bind and Chain Coefficient Reduction duration by 7 turns, changes all orbs, including [BLOCK] orbs, into [TND] orbs, and sets Chain Boundaries to 3.25x and 30.0x for 3 turns. I