      INSERT INTO character_details (character_id, detail_json)
      VALUES (4218, '{"characterId":4218,"captainAbility":"Boosts ATK of Powerhouse characters by 5x-6x depending on the crew''s current HP, and boosts ATK of all other characters by 5x. If your crew has 4 or more Powerhouse characters, reduces ATK Down duration by 10 turns, and increases duration of any ATK boosting and Base ATK boosting buffs applied by Specials by 1 turn. If your crew has 6 Powerhouse characters and Territory: Powerhouse is on the field, further boosts ATK of this character by 1.1x. If this character is your Captain and performs EXCELLENT with their Action Special, the following effect is added to this character''s Captain Ability for 3 turns: If a crew member uses a special with an Orb Effect or Color Affinity buff, increases boost effects of those Orb Amplification and Color Affinity buffs by +0.3x; further boosts ATK of this character by 1.1x. If HP is above 15% after a special is launched, reduces crew''s current HP by 30%, and reduces VS Gauge of this character by 1 (effect can be activated again for each 10% threshold of maximum HP or if HP goes above 15%). If your crew has 6 Powerhouse characters and HP is below 20% after a special is launched, up to 1 time per adventure, activates HP Guard of 100% effect for 3 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of Powerhouse characters by 5x-6x depending on the crew''s current HP, and boosts ATK of all other characters by 5x. If your crew has 4 or more Powerhouse characters, reduces ATK Down duration by 10 turns, and increases duration of any ATK boosting and Base ATK boosting buffs applied by Specials by 1 turn. If your crew has 6 Powerhouse characters and Territory: Powerhouse is on the field, further boosts ATK of this character by 1.1x. If this character is your Captain and performs EXCELLENT with their Action Special, the following effect is added to this character''s Captain Ability for 3 turns: If a crew member uses a special with an Orb Effect or Color Affinity buff, increases boost effects of those Orb Amplification and Color Affinity buffs by +0.3x; further boosts ATK of this character by 1.1x. If HP is above 15% after a special is launched, reduces crew''s current HP by 30%, and reduces VS Gauge of this character by 1 (effect can be activated again for each 10% threshold of maximum HP or if HP goes above 15%). If your crew has 6 Powerhouse characters and HP is below 20% after a special is launched, up to 1 time per adventure, activates HP Guard of 100% effect for 3 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of Striker characters by 1 turn at the start of the fight, boosts ATK of all characters by 5x-6x depending on the number of Striker characters on the crew, makes [PSY], [RCV] and [TND] orbs beneficial for all characters, and makes PERFECTs consume [RCV] orbs. If your crew has 4 or more Striker characters, reduces Despair duration by 10 turns, and increases duration of any Color Affinity and ATK boosting buffs applied by Specials by 1 turn. If your crew has 6 Striker characters and Final Tap ATK of 50% or more, boosts ATK of Striker characters by 6.5x. If HP is above 70% after a special is launched, up to 3 times per adventure, reduces VS Gauge of this character by 3 and boosts Final Tap ATK of Striker characters by 20% (effect can be activated again if HP goes below 70%). If your crew has 6 Striker characters and HP is below 70% after a special is launched, up to 1 time per adventure, recovers 50% of crew''s MAX HP and boosts Final Tap ATK of Striker characters by 30%."}],"captainNotes":null,"specialName":"Winner-Takes-All Battle for Supremacy","specialText":"Applies Territory: Powerhouse to the field for 3 turns, boosts Base ATK of Powerhouse characters by 1,500-3,000 for 1 turn depending on the outcome of Action Special, increases boost effects of ATK Up buffs to 3.5x, and boosts ATK of Powerhouse characters by 3x-4x for 1 turn depending on the crew''s current HP. If your crew has 6 Powerhouse characters and HP is below 25% when the special is activated, up to 1 time per adventure, deals 30% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies. Reduces crew''s current HP by 60%.. Ignores Debuff Protection and reduces the defense of all enemies by 100% for 2 turns. If your crew has Orb Amplification when the special is activated, boosts ATK of Striker characters by 3.25x for 2 turns, and allows HP Overfill up to 2x MAX HP for 2 turns. If your crew has Final Tap ATK when the special is activated, boosts Orb Effects of Striker characters by 3.5x, can be enhanced up to 2 times, for 2 turns; boosts Orb Effects of Striker characters by 3.25x for 1 turn otherwise. If you have used 7+ Special Abilities when the special is activated, increases duration of any Orb Amplification buffs by 1 turn, and increases boost effects of Orb Amplification buffs by +0.3x, including effects activated in the same Ability. If your crew has 6 Striker characters, swaps middle-right character with your Captain for 1 turn, up to 1 time per adventure reduces Special Cooldown of Captain character by 20 turns, and recovers 60% of crew''s MAX HP.","specialNotes":". Character 1: 0-1: 1.0x, 0%; 2: 1.05x, 5%; 3: 1.1x, 10%; 4: 1.2x, 15%; 5: 1.35x, 20%; 6: 1.5x, 25%","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["blackbeard vs law","law"],"characterTags":[],"builderAbilities":[{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotToke