      VALUES (4223, '{"characterId":4223,"captainAbility":"Boosts ATK of Powerhouse and Shooter characters by 3.5x, and boosts HP of Powerhouse and Shooter characters by 1.25x. If you defeat an enemy, increases ATK boost slightly. Stacks up to 3 times to a maximum of 4.5x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Powerhouse and Shooter characters by 3.5x, and boosts HP of Powerhouse and Shooter characters by 1.25x. If you defeat an enemy, increases ATK boost slightly. Stacks up to 3 times to a maximum of 4.5x."}],"captainNotes":null,"specialName":"Blind Spot Shot","specialText":"Deals 10% of enemies'' current HP in damage to all enemies, reduces Special Cooldown of Powerhouse characters by 1 turn, reduces VS Gauge of Powerhouse characters by 1, reduces Bind duration by 2 turns, and changes all orbs, including [BLOCK] orbs, of Powerhouse characters into Matching orbs.. Deals 10% of enemies'' current HP in damage to all enemies, reduces Special Cooldown of Powerhouse characters by 2 turns, reduces VS Gauge of Powerhouse characters by 2, reduces Bind duration by 5 turns, reduces enemies'' Powerhouse Resistance by -20% for 1 turn, and changes all orbs, including [BLOCK] orbs, of Powerhouse characters into Matching orbs. If your crew has 6 Powerhouse characters and HP is below 50% when the special is activated, increases boost effects of ATK Up and Orb Amplification buffs applied by Powerhouse characters by +0.3x for 3 turns, and reduces Special Cooldown of this character by 7 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["van ogre","ogre"],"characterTags":["Blackbeard Pirates","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"defeat_enemy","label":"Defeat Enemy","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_powerhouse","label":"ATK Boost: Powerhouse","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"support_base_atk_boost","label":"Base ATK Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Restores Special Cooldown of this character by 3 turns when it is rewinded.. If your crew has 6 Powerhouse characters, boosts base ATK of Powerhouse characters by 125; boosts base ATK of Powerhouse character by 50 otherwise."],"sailorNotes":null,"potentialAbilities":[{"Name":"Cooldown Reduction","description":["Reduces character''s Special charge time by 3 turns at the start of the fight"]},{"Name":"Enrage/Reduce Increase Damage Taken duration","description":["Boosts base ATK by 200 the turn after taking damage and reduces Increase Damag