      INSERT INTO character_details (character_id, detail_json)
      VALUES (4224, '{"characterId":4224,"captainAbility":"Reduces Special Cooldown of this character by 5 turns at the start of the fight, boosts ATK of Powerhouse and Striker characters by 4.25x, boosts HP of Powerhouse and Striker characters by 1.3x, and makes [RCV] orbs beneficial for Powerhouse and Striker characters. If this character becomes your captain in the middle of an island, attacks will ignore damage reducing Barriers and Buffs.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of this character by 5 turns at the start of the fight, boosts ATK of Powerhouse and Striker characters by 4.25x, boosts HP of Powerhouse and Striker characters by 1.3x, and makes [RCV] orbs beneficial for Powerhouse and Striker characters. If this character becomes your captain in the middle of an island, attacks will ignore damage reducing Barriers and Buffs."}],"captainNotes":"Attacks are still affected by DEF value. DEF boost buffs (Blue shield) still reduce your damage and you cannot kill through Resilience, but Damage Negating (Yellow shield), % Damage Reduction (Rainbow shield), Barriers and Threshold Damage Reduction are ignored. Enemy attacks will go through YOUR defensive buffs.","specialName":"True Form of the Polar Bear","specialText":"Reduces all enemies'' Percent Damage Reduction duration by 2 turns, and boosts Color Affinity of [PSY], Powerhouse, and Striker characters by 1.75x, can be enhanced up to 2 times, for 2 turns. If this character used \"True Form of the Polar Bear\" 1 or more times this adventure and HP is below 70%, increases boost effects of Color Affinity buffs by +0.2x, including effects activated in the same Ability, and increases the duration of any Color Affinity buffs by 1 turn. If this character used \"True Form of the Polar Bear\" 1 or more times this adventure and HP is above 70%, reduces crew''s current HP by 50%, and increases boost effects of Color Affinity buffs by +0.4x, including effe