      INSERT INTO character_details (character_id, detail_json)
      VALUES (4232, '{"characterId":4232,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5.5x, boosts HP of Slasher and Free Spirit characters by 1.6x, makes [RCV] and [TND] orbs beneficial for Slasher and Free Spirit characters, makes PERFECTs consume [RCV] orbs, reduces damage received by 20%, makes crew immune to Blow Away, and reduces Special Bind duration by 10 turns. When a Slasher or Free Spirit character performs a Critical Hit, reduces enemies'' Percent Damage Reduction duration by 2 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5.5x, boosts HP of Slasher and Free Spirit characters by 1.6x, makes [RCV] and [TND] orbs beneficial for Slasher and Free Spirit characters, makes PERFECTs consume [RCV] orbs, reduces damage received by 20%, makes crew immune to Blow Away, and reduces Special Bind duration by 10 turns. When a Slasher or Free Spirit character performs a Critical Hit, reduces enemies'' Percent Damage Reduction duration by 2 turns."}],"captainNotes":null,"specialName":"Hakoku Sovereignty of Destruction","specialText":"Deals 3x the damage dealt by this character with normal attacks in Typeless damage to all enemies at the end of each turn for 1 turn, reduces Burn and Special Bind duration by 7 turns, and boosts ATK of Slasher and Free Spirit characters by 2.5x for 1 turn. If your crew has Critical Hit Rate or Critical Hit Damage when the special is activated, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn, and reduces damage received by 90% for 1 turn. If your Captain is a Slasher character, changes all orbs, including [BLOCK] orbs, of right column characters into [TND] orbs, and increases boost effects of ATK Up buffs by +0.25x, inclu