      INSERT INTO character_details (character_id, detail_json)
      VALUES (4239, '{"characterId":4239,"captainAbility":"Boosts ATK of Fighter and Free Spirit characters by 5.25x, by 5.75x instead if HP is above 99% or below 10%, boosts ATK of all other characters by 4.5x, boosts HP of Fighter and Free Spirit characters by 1.5x, and makes [PSY], [RCV], and [TND] orbs beneficial for all characters. If this character has a [RCV] orb and you attack with this character, increases duration of any End of Turn Healing buffs by 3 turns. If you have 6 Fighter characters or there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, allows HP Overfill up to 2x MAX HP, and when a crew member uses a special with an Additional Damage buff, replaces that buff with increases duration of any End of Turn Healing buffs by 2 turns. At the start of the fight, applies the following buff: recovers 2x character''s RCV in HP at the end of each turn, preventing buff clears, for 8 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Fighter and Free Spirit characters by 5.25x, by 5.75x instead if HP is above 99% or below 10%, boosts ATK of all other characters by 4.5x, boosts HP of Fighter and Free Spirit characters by 1.5x, and makes [PSY], [RCV], and [TND] orbs beneficial for all characters. If this character has a [RCV] orb and you attack with this character, increases duration of any End of Turn Healing buffs by 3 turns. If you have 6 Fighter characters or there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, allows HP Overfill up to 2x MAX HP, and when a crew member uses a special with an Additional Damage buff, replaces that buff with increases duration of any End of Turn Healing buffs by 2 turns. At the start of the fight, applies the following buff: recovers 2x character''s RCV in HP at the end of each turn, preventing buff clears, for 8 turns."}],"captainNotes":null,"specialName":"Galaxy Impact","specialText":"Reduces enemies'' Increased Defense duration by 10 turns, changes all orbs, including [BLOCK] orbs, of left column characters into [RCV] orbs, and changes all orbs, including [BLOCK] orbs, of right column characters into [TND] orbs. If a [PSY] character is supporting this character, boosts Orb Effects of Fighter and Free Spirit characters by 2.5x for 2 turns; boosts ATK against delayed enemies by 2.5x for 2 turns otherwise. If your crew has End of Turn Healing when the special is activated, boosts Final Tap ATK of Fighter and Free Spirit characters by 30%-100% and reduces enemies'' Fighter and Free Spirit Resistance by 10%-40% based on the duration of the End of Turn Healing buff. If your crew has 15 turns or more of End of Turn Healing when the special is activated, changes Class 1 of all non-Fighter characters to Fighter class for 1 turn. Reduces crew''s current HP by 95%, deals 50x the amount of HP subtracted in Typeless damage to all enemies, and reduces End of Turn Healing duration by 10 turns.","specialNotes":"If HP is not full when the special is activated, reduces the effect of the Final Tap ATK and Resistance by 50%. 30% and 10% for 0-6 turns, 50% and 20% for 7-14 turns, 100% and 40% for 15+ turns","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["monkey d. garp","garp"],"characterTags":[],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_enemy_end_of_turn_heal","label":"Remove End of Turn Heal","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","c