Cooldown of this character by 12 turns otherwise.","specialNotes":null,"superSpecialText":"Reduces Special Cooldown of top row characters by 2 turns, inflicts all enemies with Set Target, increasing damage taken from Fighter, Slasher, Striker and Shooter characters by 1.75x and reducing Special Cooldown of Fighter, Slasher, Striker and Shooter characters by 2 turns when they defeat an enemy, for 1 turn, and transforms [INT] characters into Super [INT] characters.","superSpecialCriteriaText":"This character must be captain and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Monkey D. Garp, Coby, Helmeppo, X Drake","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Monkey D. Garp, Coby, Helmeppo, X Drake","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Coby","acceptedKeys":["coby"]},{"label":"Helmeppo","acceptedKeys":["helmeppo"]},{"label":"X Drake","acceptedKeys":["x drake","drake"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["prince grus & kujaku & hibari","prince grus","kujaku","hibari"],"characterTags":["SWORD","Navy","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":4,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"ke