      INSERT INTO character_details (character_id, detail_json)
      VALUES (4257, '{"characterId":4257,"captainAbility":"Reduces Special Cooldown of ship by 5 turns at the start of the fight, boosts ATK of Slasher characters by 5.5x, boosts ATK of all other characters by 5x, boosts HP of Slasher characters by 1.25x, makes [STR] and [INT] orbs beneficial for Slasher characters, and reduces Bind duration completely. When a [STR] or [INT] character performs a Critical Hit, reduces enemies'' Percent Damage Reduction duration by 2 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of ship by 5 turns at the start of the fight, boosts ATK of Slasher characters by 5.5x, boosts ATK of all other characters by 5x, boosts HP of Slasher characters by 1.25x, makes [STR] and [INT] orbs beneficial for Slasher characters, and reduces Bind duration completely. When a [STR] or [INT] character performs a Critical Hit, reduces enemies'' Percent Damage Reduction duration by 2 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of all characters by 5.25x, boosts HP and RCV of all characters by 1.25x, makes [STR] and [INT] orbs beneficial for all characters, reduces damage received by 20%, and reduces Bind duration completely. When a [STR] or [INT] character performs a Critical Hit, reduces enemies'' Increased Defense duration by 2 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of ship by 5 turns at the start of the fight, boosts ATK of Slasher characters by 5.75x, boosts ATK of all other characters by 5.5x, boosts HP and RCV of all characters by 1.25x, makes [STR] and [INT] orbs beneficial for all characters, reduces damage received by 20%, and reduces Bind duration completely. When a [STR] or [INT] character performs a Critical Hit, reduces enemies'' Percent Damage Reduction and Increased Defense duration by 2 turns."}],"captainNotes":null,"specialName":"Furious Onslaught","specialText":"D