00,"duration":20,"targeting":{"targets":["enemies"]}},{"amount":4,"effect":"damage","type":"atk","targeting":{"targets":["enemies"],"count":3,"priority":"lowest","stat":"HP"}}]}],"superspecial":[{"condition":{"type":"specialreceived","team":"enemy","count":2},"effects":[{"amount":60,"effect":"damage","type":"cut","targeting":{"targets":["enemies"],"count":1,"priority":"highest","stat":"HP"}},{"attributes":["Half DEF"],"effect":"hinderance","chance":100,"duration":30,"targeting":{"targets":["enemies"]}},{"amount":4.5,"effect":"damage","type":"atk","targeting":{"targets":["enemies"],"count":3,"priority":"lowest","stat":"HP"}},{"amount":100,"effect":"recharge","type":"percentage","targeting":{"targets":["self"]}}]}],"llbsuperspecial":[{"condition":{"type":"specialreceived","team":"enemy","count":2},"effects":[{"amount":60,"effect":"damage","type":"cut","targeting":{"targets":["enemies"]}},{"attributes":["Half DEF"],"effect":"hinderance","chance":100,"duration":30,"targeting":{"targets":["enemies"]}},{"amount":5,"effect":"damage","type":"atk","targeting":{"targets":["enemies"],"count":3,"priority":"lowest","stat":"HP"}},{"amount":100,"effect":"recharge","type":"percentage","targeting":{"targets":["self"]}}]}],"resilience":[{"amount":250,"interval":5,"type":"healing"},{"attribute":"Fighter","percentage":30,"type":"damage"},{"attribute":"Driven","percentage":30,"type":"damage"}],"gpability":[{"effects":[{"attributes":["ATK"],"level":3,"effect":"buff","targeting":{"targets":["crew"]}},{"attributes":["HP","SPD"],"level":3,"effect":"buff","targeting":{"targets":["crew"]}}]}],"gpspecial":[{"uses":2,"effects":[{"amount":1000,"effect":"damage","type":"fixed","targeting":{"targets":["enemies"]}}]}],"gpcondition":[{"count":2,"type":"defeat","team":"crew"}],"pattern":[{"type":"Normal","action":"attack"},{"type":"Normal","action":"attack"},{"type":"Power","action":"attack"},{"type":"Full","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"ATK","def":182,"spd":1