      INSERT INTO character_details (character_id, detail_json)
      VALUES (4269, '{"characterId":4269,"captainAbility":"Reduces Special Cooldown of Driven and Powerhouse characters by 3 turns at the start of Stage 2, boosts ATK of Driven and Powerhouse characters by 4x, by 5x instead if HP is below 30% at the start of the turn, and boosts HP of Driven and Powerhouse characters by 1.5x. One time per an adventure, if Captain Swap is in effect or another status effect is applied to the crew, all enemies, or an individual enemy on the same turn after the required effect was applied, activates \"Dreadful Onslaught\" in the following turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Driven and Powerhouse characters by 3 turns at the start of Stage 2, boosts ATK of Driven and Powerhouse characters by 4x, by 5x instead if HP is below 30% at the start of the turn, and boosts HP of Driven and Powerhouse characters by 1.5x. One time per an adventure, if Captain Swap is in effect or another status effect is applied to the crew, all enemies, or an individual enemy on the same turn after the required effect was applied, activates \"Dreadful Onslaught\" in the following turn."}],"captainNotes":null,"specialName":"Dreadful Onslaught","specialText":"Removes Poison duration completely and reduces Burn duration by 6 turns. If your crew has Color Affinity when the special is activated, increases boost effects of Color Affinity buffs by +0.25x. If HP is below 25% when the special is activated and crew has Color Affinity when the special is activated, sets Chain Boundaries to 2.5x and 15.0x for 3 turns. Reduces crew''s current HP by 80%, deals 30x the amount of HP subtracted in Typeless damage to all enemies, and boosts Color Affinity of Driven and Powerhouse characters by 2.25x, preventing buff clears, for 3 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["blackbeard & shiryu",