      INSERT INTO character_details (character_id, detail_json)
      VALUES (4275, '{"characterId":4275,"captainAbility":"Reduces Special Cooldown of Slasher and Free Spirit characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5x, by 5.5x instead if they have a [WANO] orb, boosts HP of Slasher and Free Spirit characters by 1.25x, boosts chances of getting [QCK] orbs, changes [QCK] orbs into [WANO] orbs, and makes [DEX] and [STR] orbs beneficial for all characters. If your crew has 4 or more Slasher characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and recovers 5,000 HP at the end of each turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of Slasher and Free Spirit characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5x, by 5.5x instead if they have a [WANO] orb, boosts HP of Slasher and Free Spirit characters by 1.25x, boosts chances of getting [QCK] orbs, changes [QCK] orbs into [WANO] orbs, and makes [DEX] and [STR] orbs beneficial for all characters. If your crew has 4 or more Slasher characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and recovers 5,000 HP at the end of each turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of Slasher and Free Spirit characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5.25x, boosts HP of Slasher and Free Spirit characters by 1.25x, boosts chances of getting [QCK] orbs, changes [QCK] orbs into [WANO] orbs, and makes [DEX] and [STR] orbs beneficial for all characters. If your crew has 4 or more Slasher characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, and recovers 5,000 HP at the end of each turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of Slasher and Free Spirit characters by 1 turn at the start of the fight, boosts ATK of Slasher and Free Spirit characters by 5.25x, by 6x instead if they have a [WANO] orb, boosts HP of Slasher and Free Spirit characters by 1.25x, boosts chances of getting [QCK] orbs, changes [QCK] orbs into [WANO] orbs, and makes [DEX] and [STR] orbs beneficial for all characters. If your crew has 4 or more Slasher characters, restores Special Cooldown of all characters by 10 turns when they are rewinded, recovers 5,000 HP at the end of each turn, and reduces enemies'' Slasher and Free Spirit Resistance by -4% for 1 turn when a Slasher character performs a Critical Hit."}],"captainNotes":null,"specialName":"Samurai Challenging the Dragon","specialText":"Reduces Paralysis duration by 10 turns, changes [DEX] orbs into [WANO] orbs for 3 turns, changes [BLOCK] and Matching orbs into [DEX] orbs, allows all characters to perform Super Tandem with [WANO] orbs for 3 turns, enables ATK Up and Orb Amplification buffs applied by Slasher and Free Spirit characters to be enhanced up to 2 times for 3 turns. If your crew has Chain Lock when the special is activated, inflicts all enemies with Increase Damage Taken by 2.25x for 1 turn; sets Chain Boundaries to 3.5x and 30.0x for 3 turns otherwise. Becomes Oden & Kin''emon & Denjiro for 3 turns.","specialNotes":null,"superSpecialText":"Optionally removes Captain Swap duration completely, reduces Burn duration by 6 turns, increases boost effects of ATK Up and Orb Amplification buffs by +0.3x, and transforms [DEX] or [STR] characters into Super [DEX] or [STR] characters depending on the type of this character.","superSpecialCriteriaText":"Can be launched as crewmate. When character becomes Oden & Kin''emon & Denjiro during Captain Shift and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Kozuki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kanjuro, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Izo, Gol D. Roger, Edward Newgate (Whitebeard), Yamato, Monkey D. Luffy","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When character becomes Oden & Kin''emon & Denjiro during Captain Shift and your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Kozuki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kanjuro, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Izo, Gol D. Roger, Edward Newgate (Whitebeard), Yamato, Monkey D. Luffy","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Kozuki Momonosuke","acceptedKeys":["kozuki momonosuke","momonosuke"]},{"label":"Kozuki Hiyori (Komurasaki)","acceptedKeys":["kozuki hiyori komurasaki","kozuki hiyori","komurasaki","hiyori"]},{"label":"Kozuki Toki","acceptedKeys":["kozuki toki","toki"]},{"label":"Kozuki Sukiyaki (Tenguyama Hitetsu)","acceptedKeys":["kozuki sukiyaki tenguyama hitetsu","kozuki sukiyaki","tenguyama hitetsu","sukiyaki"]},{"label":"Kanjuro","acceptedKeys":["kanjuro"]},{"label":"Raizo","acceptedKeys":["raizo"]},{"label":"Okiku","acceptedKeys":["okiku"]},{"label":"Ashura Doji (Shutenmaru)","acceptedKeys":["ashura doji shutenmaru","ashura doji","shutenmaru","doji"]},{"label":"Dogstorm","acceptedKeys":["dogstorm","inuarashi"]},{"label":"Cat Viper","acceptedKeys":["cat viper","viper","nekomamushi"]},{"label":"Kawamatsu","acceptedKeys":["kawamatsu"]},{"label":"Izo","acceptedKeys":["izo"]},{"label":"Gol D. Roger","acceptedKeys":["gol d roger","roger"]},{"label":"Edward Newgate (Whitebeard)","acceptedKeys":["edward newgate whitebeard","edward newgate","whitebeard","newgate"]},{"label":"Yamato","acceptedKeys":["yamato"]},{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]}]}],"hasNonRosterBranches":