ki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kanjuro, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Izo, Gol D. Roger, Edward Newgate (Whitebeard), Yamato, Monkey D. Luffy","levels":[{"level":5,"effect":"Increases Orb Effects of beneficial [WANO] orbs to 3x for 1 turn, and boosts Tandem ATK of Slasher and Free Spirit characters by 2.25x for 1 turn."}],"criteria":{"rawText":"Your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Kozuki Momonosuke, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kanjuro, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Izo, Gol D. Roger, Edward Newgate (Whitebeard), Yamato, Monkey D. Luffy","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Kozuki Momonosuke","acceptedKeys":["kozuki momonosuke","momonosuke"]},{"label":"Kozuki Hiyori (Komurasaki)","acceptedKeys":["kozuki hiyori komurasaki","kozuki hiyori","komurasaki","hiyori"]},{"label":"Kozuki Toki","acceptedKeys":["kozuki toki","toki"]},{"label":"Kozuki Sukiyaki (Tenguyama Hitetsu)","acceptedKeys":["kozuki sukiyaki tenguyama hitetsu","kozuki sukiyaki","tenguyama hitetsu","sukiyaki"]},{"label":"Kanjuro","acceptedKeys":["kanjuro"]},{"label":"Raizo","acceptedKeys":["raizo"]},{"label":"Okiku","acceptedKeys":["okiku"]},{"label":"Ashura Doji (Shutenmaru)","acceptedKeys":["ashura doji shutenmaru","ashura doji","shutenmaru","doji"]},{"label":"Dogstorm","acceptedKeys":["dogstorm","inuarashi"]},{"label":"Cat Viper","acceptedKeys":["cat viper","viper","nekomamushi"]},{"label":"Kawamatsu","acceptedKeys":["kawamatsu"]},{"label":"Izo","acceptedKeys":["izo"]},{"label":"Gol D. Roger","acceptedKeys":["gol d roger","roger"]},{"label":"Edward Newgate (Whitebeard)","acceptedKeys":["edward newgate whitebeard","edward newg