      INSERT INTO character_details (character_id, detail_json)
      VALUES (4276, '{"characterId":4276,"captainAbility":"Reduces Special Cooldown of this character by 3 turns at the start of the fight, reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX] and [QCK] characters by 4.25x and boosts ATK of Fighter, Slasher, Striker and Shooter characters by 1.2x, by 5.1x if character has both type and class, boosts HP of [STR], [DEX] and [QCK] characters by 1.2x, boosts chances of getting Matching orbs, and reduces crew''s current HP by 10% at the end of each turn. If HP is above 85% at the start of the turn, attacks will ignore damage reducing Barriers and Buffs.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of this character by 3 turns at the start of the fight, reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX] and [QCK] characters by 4.25x and boosts ATK of Fighter, Slasher, Striker and Shooter characters by 1.2x, by 5.1x if character has both type and class, boosts HP of [STR], [DEX] and [QCK] characters by 1.2x, boosts chances of getting Matching orbs, and reduces crew''s current HP by 10% at the end of each turn. If HP is above 85% at the start of the turn, attacks will ignore damage reducing Barriers and Buffs."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of this character by 3 turns at the start of the fight, reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX] and [QCK] characters by 5x, boosts HP of [STR], [DEX] and [QCK] characters by 1.2x, boosts chances of getting Matching orbs, and reduces crew''s current HP by 10% at the end of each turn. If HP is above 85% at the start of the turn, attacks will ignore damage reducing Barriers and Buffs."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of this character by 3 turns at the start of the fight, reduces Special Cooldown of all other characters by 1 turn at the start of the fight, boosts ATK of [STR], [DEX] and [QCK] characters by 5x and boosts ATK of Fighter, Slasher, Striker and Shooter characters by 1.15x, by 5.75x if character has both type and class, boosts HP of [STR], [DEX] and [QCK] characters by 1.2x, boosts chances of getting Matching orbs, reduces crew''s current HP by 10% at the end of each turn, and attacks will ignore damage reducing Barriers and Buffs."}],"captainNotes":"Attacks are still affected by DEF value. DEF boost buffs (Blue shield) still reduce your damage and you can not kill through Resilience, but Damage Negating (Yellow shield), % Damage Reduction (Rainbow shield), Barriers and Threshold Damage Reduction are ignored. Enemy attacks will go through YOUR defensive buffs.","specialName":"Moonlit Assault","specialText":"Reduces Special Cooldown of all characters by 1 turn, reduces ATK Down duration by 7 turns, adds 1.5x to Chain multiplier for 1 turn, and boosts Enemy Damage Reduction to ATK of Fighter and Slasher characters by 1.5x-2.5x, proportional to the strength of enemies'' Percent Damage Reduction buff, for 1 turn. Becomes Carrot & Dogstorm & Cat Viper for 1 turn.. Reduces Special Cooldown of all characters by 2 turns, reduces ATK Down duration by 7 turns, adds 1.7x to Chain multiplier for 1 turn, and boosts Enemy Damage Reduction to ATK of all characters by 1.7x-2.7x, proportional to the strength of enemies'' Percent Damage Reduction buff, for 1 turn.","specialNotes":"If enemy does not have Percent Damage Reduction, boosts ATK by 1x.","superSpecialText":"Reduces enemies'' damage received by 50% for 6 turns, boosts Super Class Effects of Slasher characters to 1.5x for 1 turn, and transforms Slasher characters into Super Slasher characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Kozuki Momonosuke, Kozuki Oden, Kin''emon, Denjiro (Kyoshiro), Raizo, Okiku, Ashura Doji (Shutenmaru), Kawamatsu, Izo, Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Wanda, Yamato","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Kozuki Momonosuke, Kozuki Oden, Kin''emon, Denjiro (Kyoshiro), Raizo, Okiku, Ashura Doji (Shutenmaru), Kawamatsu, Izo, Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Wanda, Yamato","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Kozuki Momonosuke","acceptedKeys":["kozuki momonosuke","momonosuke"]},{"label":"Kozuki Oden","acceptedKeys":["kozuki oden","oden"]},{"label":"Kin''emon","acceptedKeys":["kin emon"]},{"label":"Denjiro (Kyoshiro)","acceptedKeys":["denjiro kyoshiro","denjiro","kyoshiro"]},{"label":"Raizo","acceptedKeys":["raizo"]},{"label":"Okiku","acceptedKeys":["okiku"]},{"label":"Ashura Doji (Shutenmaru)","acceptedKeys":["ashura doji shutenmaru","ashura doji","shutenmaru","doji"]},{"label":"Kawamatsu","acceptedKeys":["kawamatsu"]},{"label":"Izo","acceptedKeys":["izo"]},{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Sanji","acceptedKeys":["sanji"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},