      INSERT INTO character_details (character_id, detail_json)
      VALUES (4285, '{"characterId":4285,"captainAbility":"Reduces Special Cooldown of Cerebral characters by 2 turns at the start of the fight, boosts ATK of Cerebral characters by 5.25x, by 5.5x instead if they have a beneficial orb, boosts HP of Cerebral characters by 1.35x, and makes [PSY] orbs beneficial for [INT] and Cerebral characters. Up to 2 times per adventure, when Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Atlas the Violent\" or Dr. Vegapunk \"York the Greedy\" uses a Special as crewmate, advances Special Cooldown of this character to MAX, and reduces Chain Coefficient Reduction duration by 10 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Cerebral characters by 2 turns at the start of the fight, boosts ATK of Cerebral characters by 5.25x, by 5.5x instead if they have a beneficial orb, boosts HP of Cerebral characters by 1.35x, and makes [PSY] orbs beneficial for [INT] and Cerebral characters. Up to 2 times per adventure, when Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Atlas the Violent\" or Dr. Vegapunk \"York the Greedy\" uses a Special as crewmate, advances Special Cooldown of this character to MAX, and reduces Chain Coefficient Reduction duration by 10 turns."}],"captainNotes":null,"specialName":"Utilizing the Intelligence of the Satellites","specialText":"Boosts Chain Multiplier Growth Rate by 1.5x, can be enhanced up to 2 times, for 1 turn, and ignores Debuff Protection and reduces the defense of all enemies by 100% for 1 turn. If your crew has Chain Multiplication when the special is activated, increases Chain Tap Timing Bonus of Cerebral characters to +0.2x-0.6x, can be enhanced up to 2 times, for 1 turn depending on Tap Timing, reduces enemies'' Percent Damage Reduction and Threshold Damage Reduction duration by 1 turn, and reduces ATK Down duration by 1 turn. If your crew has Chain Multiplication and Chain Tap Timing Bonus when the special is activated, inflicts all enemies with Set Target, increasing damage taken from Cerebral characters by 2x and reducing Special Cooldown of Cerebral characters by 2 turns when they defeat an enemy, for 1 turn, increases boost effects of Chain Multiplication buffs by +0.2x, and increases boost effects of Chain Tap Timing Bonus buffs by +0.1x. Up to 1 time per adventure, if the Special Counter of this characters is 1, reduces Special Cooldown of Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"York the Greedy\" and Dr. Vegapunk \"Atlas the Violent\" characters by 15 turns.","specialNotes":"GOOD: +0.2, GREAT: +0.4, PERFECT: +0.6","superSpecialText":"Sets Special Counter of this character to 1, changes all orbs, including [BLOCK] orbs, into [PSY] orbs, reduces Special Cooldown of Cerebral characters by 1 turn, and transforms [INT] characters into Super [INT] characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Atlas the Violent\", Dr. Vegapunk \"York the Greedy\", Stussy","superSpecialNotes":"Special Counter counts the number of times that the character''s special has been used in the adventure.","superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Atlas the Violent\", Dr. Vegapunk \"York the Greedy\", Stussy","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Dr. Vegapunk (Stella)","acceptedKeys":["dr vegapunk stella","dr vegapunk","stella","vegapunk"]},{"label":"Dr. Vegapunk \"Lilith the Evil\"","acceptedKeys":["dr vegapunk lilith the evil","evil"]},