      INSERT INTO character_details (character_id, detail_json)
      VALUES (4286, '{"characterId":4286,"captainAbility":"Boosts ATK of [INT], Cerebral and Free Spirit characters by 3.75x, boosts HP of [INT], Cerebral and Free Spirit characters by 1.4x, and reduces damage received by 10%.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [INT], Cerebral and Free Spirit characters by 3.75x, boosts HP of [INT], Cerebral and Free Spirit characters by 1.4x, and reduces damage received by 10%."}],"captainNotes":null,"specialName":"Genius Scientist Seeking Escape","specialText":"Reduces enemies'' Threshold Damage Reduction duration by 6 turns, reduces Paralysis duration by 6 turns, boosts Color Affinity of [INT] Cerebral characters by 2.5x for 1 turn, and boosts ATK against enemies with reduced defense by 2.25x for 1 turn. If this character has used \"Genius Scientist Seeking Escape\" 1 time this adventure, boosts Orb Effects of [INT] Cerebral characters by 2.5x for 1 turn, and increases boost effects of ATK Up, Orb Amplification, Color Affinity and Status ATK Boost buffs by +0.25x, including effects activated in the same Ability.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["dr. vegapunk","vegapunk"],"characterTags":["Vegapunk","Scientist","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens