il\", Dr. Vegapunk \"Atlas the Violent\", Dr. Vegapunk \"York the Greedy\", Dr. Vegapunk \"Shaka the Good\", Dr. Vegapunk \"Edison the Thinker\", Dr. Vegapunk \"Pythagoras the Wise\"","levelDescriptions":["Once per adventure, when the supported character uses their special, reduces Paralysis duration by 2 turns."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4286,"pattern":[{"type":"Normal","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"SPT","def":50,"spd":100},"cost":30}}');


