      INSERT INTO character_details (character_id, detail_json)
      VALUES (4290, '{"characterId":4290,"captainAbility":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 5.25x, boosts HP of all characters by 1.2x, and makes [STR] and [RCV] orbs beneficial for all characters. Adds the following effects based on what Gear this character is in:. Gear 2: Makes PERFECTs consume [RCV] orbs, and recovers 25% of damage taken from enemies in the previous stage when entering a new stage. Gear 3: Boosts ATK of all characters by 5.25x-6.077x instead, by a further 1.05x for each Super Effect they have. Gear 4 - Bounceman: Reduces damage received by 25%, and recovers 5,000 HP at the end of each turn. Gear 4 - Snakeman: Reduces Paralysis duration by 10 turns. Gear 5: Boosts ATK of all characters by 5.25x-6.987x instead, by a further 1.1x for each Super Effect they have. If crew uses a special with an ATK Up, Chain Multiplication or Chain Addition buff, increases boost effects of those ATK Up, Chain Multiplication and Chain Addition buffs by +0.25x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of all characters by 5.25x, boosts HP of all characters by 1.2x, and makes [STR] and [RCV] orbs beneficial for all characters. Adds the following effects based on what Gear this character is in:. Gear 2: Makes PERFECTs consume [RCV] orbs, and recovers 25% of damage taken from enemies in the previous stage when entering a new stage. Gear 3: Boosts ATK of all characters by 5.25x-6.077x instead, by a further 1.05x for each Super Effect they have. Gear 4 - Bounceman: Reduces damage received by 25%, and recovers 5,000 HP at the end of each turn. Gear 4 - Snakeman: Reduces Paralysis duration by 10 turns. Gear 5: Boosts ATK of all characters by 5.25x-6.987x instead, by a further 1.1x for each Super Effect they have. If crew uses a special with an ATK Up, Chain Multiplication or Chain Addition buff, increases boost effects of those ATK Up, Chain Multiplication and Chain Addition buffs by +0.25x."}],"captainNotes":". Luffy changes Gears depending on how many Super Type/Class Effects are active on the crew: Gear 2: 1 Super Effect. Gear 3: 1 Super Type and 1 Super Class. Gear 4 - Bounceman: 3 Super Effects. Gear 4 - Snakeman: 3 Super Effects with at least 1 Super Type and 1 Super Class. Gear 5: 4+ Super Effects.","specialName":"Fist for the High Seas","specialText":"Deals 400x character''s ATK in Typeless Fixed True damage to all enemies, removes enemies'' Increased Defense duration completely, and applies Territory: Fighter to the field for 3 turns. If enemies have Increase Damage Taken or your crew has 10+ turns of End of Turn Healing when the special is activated, boosts ATK against enemies inflicted with Increase Damage Taken by 3x for 2 turns. Ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.25x-3x for 2 turns depending on the outcome of Action Special.","specialNotes":". Territory: 0-1: 1.0x, 0%; 2: 1.05x, 5%; 3: 1.1x, 10%; 4: 1.2x, 15%; 5: 1.35x, 20%; 6: 1.5x, 25%. Increase Damage Taken: MISS: 2.25x, GOOD: 2.4x, GREAT: 2.5x, PERFECT: 2.75x, EXCELLENT: 3x","superSpecialText":"Adds 100x character''s ATK as Additional Typeless Damage for 5 turns, ignores Debuff Protection and inflicts all enemies with Weaken by 1.3x, by 1.69x instead if enemies are inflicted with Increase Damage Taken, for 1 turn, transforms [STR] characters into Super [STR] characters, transforms Fighter characters into Super Fighter characters, and transforms Free Spirit characters into Super Free Spirit characters.","superSpecialCriteriaText":"This character must be captain and this character must be in Gear Five or your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and this character must be in Gear Five or your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Sanji","acceptedKeys":["sanji"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},{"label":"Brook","acceptedKeys":["brook"]},{"label":"Jinbe","acceptedKeys":["jinbe"]}]}],"hasNonRosterBranches":true,"parserStatus":"mixed"},"partyConflictKeys":["monkey d. luffy","luffy"],"characterTags":["Straw Hat Pirates","Worst Generation","Mythical Zoan-type","Land of Wano Arc"],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"end_of_turn_additional_damage","label":"End of Turn Additional Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"territory","label":"Territory","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"consume_slots","label":"Consume Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_fighter","label":"ATK Boost: Fighter","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_crew","label":"RCV Boost: Crew","minTurns":nu