      INSERT INTO character_details (character_id, detail_json)
      VALUES (4291, '{"characterId":4291,"captainAbility":"Boosts ATK of [INT], Cerebral and Fighter characters by 6x, by 6.25x instead if crew is inflicted with 10+ status effects, boosts ATK of all other characters by 4.5x, boosts HP of [INT], Cerebral and Fighter characters by 1.2x, makes [TND] orbs beneficial for all characters, reduces Despair duration by 10 turns, removes Special Bind duration completely on this character, and increases duration of any Advantageous Class Effect buffs applied by specials by 1 turn. If this character is your Captain and performs EXCELLENT with their Action Special, boosts ATK of [INT], Cerebral and Fighter characters by 6.5x instead for 3 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [INT], Cerebral and Fighter characters by 6x, by 6.25x instead if crew is inflicted with 10+ status effects, boosts ATK of all other characters by 4.5x, boosts HP of [INT], Cerebral and Fighter characters by 1.2x, makes [TND] orbs beneficial for all characters, reduces Despair duration by 10 turns, removes Special Bind duration completely on this character, and increases duration of any Advantageous Class Effect buffs applied by specials by 1 turn. If this character is your Captain and performs EXCELLENT with their Action Special, boosts ATK of [INT], Cerebral and Fighter characters by 6.5x instead for 3 turns."}],"captainNotes":null,"specialName":"Rescuing Fire Fist: Rook Check","specialText":"Deals 300x character''s ATK in Typeless Fixed True damage to all enemies, reduces Special Bind and Burn duration by 10 turns, and applies Territory: Cerebral to the field for 3 turns. If your crew has Advantageous Class Effect or your crew has 5+ turns of Additional Damage when the special is activated, boosts Chain Multiplier Growth Rate by 1.5x, can be enhanced up to 2 times, for 2 turns. Boosts Advantageous Class Effect of Cerebral and Fighter characters by 2.5x-3x for 2 turns depending on the outcome of Action Special.","specialNotes":". Advantageous Class Effect boosts damage against enemies with Class Weakness. Action Special: MISS: 2.5x, GOOD: 2.7x, GREAT: 2.8x, PERFECT: 2.9x, EXCELLENT: 3x","superSpecialText":"Changes all orbs, including [BLOCK] orbs, into [TND] orbs, recovers 8,000 HP at the end of the turn for 10 turns, increases boost effects of Base ATK buffs by 1.5x (up to 4,000), boosts Orb Effects of Cerebral and Fighter characters by 2x, allowing override, for 1 turn, transforms [INT] characters into Super [INT] characters, and transforms Cerebral characters into Super Cerebral characters.","superSpecialCriteriaText":"Can be launched as crewmate. When crew has used 8 specials or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Portgas D. Ace, Monkey D. Garp, Curly Dadan, Emporio Ivankov, Belo Betty, Morley, Karasu, Lindbergh, Koala, Hack, Inazuma, Bartholomew Kuma, Ginny, Monkey D. Dragon, Nico Robin","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When crew has used 8 specials or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Portgas D. Ace, Monkey D. Garp, Curly Dadan, Emporio Ivankov, Belo Betty, Morley, Karasu, Lindbergh, Koala, Hack, Inazuma, Bartholomew Kuma, Ginny, Monkey D. Dragon, Nico Robin","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Portgas D. Ace","acceptedKeys":["portgas d ace","ace"]},{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Curly Dadan","acceptedKeys":["curly dadan","dadan"]},{"label":"Emporio Ivankov","acceptedKeys":["emporio ivankov","ivankov"]},{"label":"Belo Betty","acceptedKeys":["belo betty","betty"]},{"label":"Morley","acceptedKeys