rts and counting only 1 per unit: Monkey D. Luffy, Portgas D. Ace, Monkey D. Garp, Curly Dadan, Nico Robin, Emporio Ivankov, Belo Betty, Morley, Karasu, Lindbergh, Koala, Hack, Inazuma, Bartholomew Kuma","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Portgas D. Ace","acceptedKeys":["portgas d ace","ace"]},{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Curly Dadan","acceptedKeys":["curly dadan","dadan"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Emporio Ivankov","acceptedKeys":["emporio ivankov","ivankov"]},{"label":"Belo Betty","acceptedKeys":["belo betty","betty"]},{"label":"Morley","acceptedKeys":["morley"]},{"label":"Karasu","acceptedKeys":["karasu"]},{"label":"Lindbergh","acceptedKeys":["lindbergh"]},{"label":"Koala","acceptedKeys":["koala"]},{"label":"Hack","acceptedKeys":["hack"]},{"label":"Inazuma","acceptedKeys":["inazuma"]},{"label":"Bartholomew Kuma","acceptedKeys":["bartholomew kuma","kuma"]}]}],"hasNonRosterBranches":true,"parserStatus":"mixed"}},"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4291,"basedOn":4292}}');


