      INSERT INTO character_details (character_id, detail_json)
      VALUES (4293, '{"characterId":4293,"captainAbility":"Advances Special Cooldown of Ship to MAX at the start of the fight, boosts ATK of Powerhouse and Fighter characters by 5.25x, by 6x instead if HP is above 99% or below 25% at the start of the turn, boosts HP of Powerhouse and Fighter characters by 1.3x, makes [QCK], [TND] and [RCV] orbs beneficial for all characters, reduces damage received by 15%, reduces Special Use Limit duration by 10 turns, and increases duration of any ATK Up buffs applied by specials by 1 turn. If a Whitebeard Pirates Commander uses a special, activates the following effect: See Dual Characters Captain Ability for list of effects.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Advances Special Cooldown of Ship to MAX at the start of the fight, boosts ATK of Powerhouse and Fighter characters by 5.25x, by 6x instead if HP is above 99% or below 25% at the start of the turn, boosts HP of Powerhouse and Fighter characters by 1.3x, makes [QCK], [TND] and [RCV] orbs beneficial for all characters, reduces damage received by 15%, reduces Special Use Limit duration by 10 turns, and increases duration of any ATK Up buffs applied by specials by 1 turn. If a Whitebeard Pirates Commander uses a special, activates the following effect: See Dual Characters Captain Ability for list of effects."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 3 turns at the start of the fight, boosts ATK of Powerhouse and Fighter characters by 5x, by 5.75x instead if they have a beneficial orb, boosts HP of Powerhouse and Fighter characters by 1.3x, makes [QCK], [TND] and [RCV] orbs beneficial for all characters, reduces Special Use Limit duration by 10 turns, and increases duration of any ATK Up buffs applied by specials by 1 turn. If a Whitebeard Pirates Commander uses a special, activates the following effect: See Dual Characters Captain Ability for list of effects."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of Powerhouse and Fighter characters by 6x, by 6.25x instead if HP is above 99% or below 25% at the start of the turn, boosts HP of Powerhouse and Fighter characters by 1.3x, makes [QCK], [TND] and [RCV] orbs beneficial for all characters, reduces damage received by 20%, reduces Special Use Limit duration by 10 turns, and increases duration of any ATK Up buffs applied by specials by 1 turn. If a Whitebeard Pirates Commander uses a special, activates the following effect: Marco: Adds 150x character''s ATK as Additional Typeless Damage for 5 turns, and activates HP Guard of 100% effect for 1 turn. Jozu, Oden: Boosts Crew Damage Reduction to ATK of all characters by 1x-2.5x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. Thatch, Vista, Izo: Ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.5x for 1 turn. Blamenco, Rakuyo, Namule: Reduces enemies'' Increased Defense duration by 6 turns, and increases boost effects of enemies'' Increase Damage Taken debuffs by +0.5x. Blenheim, Curiel, Kingdew: Reduces enemies'' Threshold Damage Reduction duration by 6 turns, and increases boost effects of Orb Amplification buffs by +0.75x. Haruta, Atmos, Speed Jil, Fossa: Reduces enemies'' Percent Damage Reduction duration by 6 turns, and increases boost effects of Base ATK Boost buffs by +1,000."}],"captainNotes":"Only the character that used the special counts for Dual Characters. If a character used the special in a Dual form or any other multiple characters form, effect only applies for 1 character. Similar effect of Captain and Friend/Helper Captain will not activate at the same time.","specialName":"Frenzied Onslaught","specialText":"Reduces ATK Down duration by 10 turns, and applies Territory: Powerhouse to the field for 3 turns. If your crew has ATK Up or your crew has 5+ turns of Additional Damage when the special is activated, adds 2.2x to Chain Multiplier for 1 turn. Boosts ATK of Powerhouse and Fighter characters by 3.5x-4.25x for 1 turn depending on the number of specials crew has used.. Reduces ATK Down duration by 10 turns, and applies Territory: Powerhouse to the field for 3 turns. If your crew has ATK Up or your crew has 5+ turns of Additional Damage when the special is activated, adds 2.5x to Chain Multiplier for 2 turns. If your crew has ATK Up with an effect of 3x or more when the special is activated, increases boost effects of ATK Up buffs by 1.5x (up to 6x). Boosts ATK of Powerhouse and Fighter characters by 3.5x-4.5x for 2 turns depending on the number of specials crew has used; if your crew has used 8+ specials, changes Class 2 of all non-Powerhouse Class 2 Cerebral, Class 2 Free Spirit and Class 2 Driven characters to Powerhouse class for 2 turns.","specialNotes":". Solo: 3.5x for 0 specials, 3.6x for 1-2 specials, 3.75x for 3-5 specials, 4x for 6-7 specials, 4.25x for 8+ specials. Dual: 3.5x for 0 specials, 3.75x for 1-2 specials, 4x for 3-5 specials, 4.25x for 6-7 specials, 4.5x for 8+ specials","superSpecialText":"Boosts Base ATK of Powerhouse and Fighter characters by 1,250 for 1 turn, transforms Powerhouse characters into Super Powerhouse characters, and transforms Fighter characters into Super Fighter characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Sabo, Monkey D. Garp, Curly Dadan, Marco, Jozu, Thatch, Vista, Blamenco, Rakuyo, Namule, Blenheim, Curiel, Kingdew, Haruta, Atmos, Speed Jil, Fossa, Izo, Kozuki Oden, Jinbe, Sir Crocodile (Mr. 0), Boa Hancock, Emporio Ivankov, Inazuma, Buggy, Daz Bonez (Mr. 1), Galdino (Mr. 3)","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Sabo, Monkey D. Garp, Curly Dadan, Marco, Jozu, Thatch, Vista, Blamenco, Rakuyo, Namule, Blenheim, Curiel, Kingdew, Haruta, Atmos, Speed Jil, Fossa, Izo, Kozuki Oden, Jinbe, Sir Crocodile (Mr. 0), Boa Hancock, Emporio Ivankov, Inazuma, Buggy, Daz Bonez (Mr. 1), Galdino (Mr. 3)","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Sabo","acceptedKeys":["sabo"]},{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Curly Dadan","acceptedKeys":["curly dadan","dadan"]},{"label":"Marco","acceptedKeys":["marco"]},{"label":"Jozu","acceptedKeys":["jozu"]},{"label":"Thatch","acceptedKeys":["thatch"]},{"label":"Vista","acceptedKeys":["vista"]},{"label":"Blamenco","acceptedKeys":["blamenco"]},{"label":"Rakuyo","acceptedKeys":["rakuyo"]},{"label":"Namule","acceptedKeys":["namule"]},{"label":"Blenheim","acceptedKeys":["blenheim"]},{"label":"Curiel","acceptedKeys":["curiel"]},{"label":"Kingdew","acceptedKeys":["kingdew"]},{"label":"Haruta","acceptedKeys":["haruta"]},{"label":"Atmos","acceptedKeys":["atmos"]},{"label":"Speed Jil","acceptedKeys":["speed jil","jil"]},{"label":"Fossa","acceptedKeys":["fossa"]},{"label":"Izo","acceptedKeys":["izo"]},{"label":"Kozuki Oden","acceptedKeys":["kozuki oden","oden"]},{"label":"Jinbe","acceptedKeys":["jinbe"]},{"label":"Sir Crocodile (Mr. 0)","acceptedKeys":["sir crocodile mr 0","sir crocodile","mr 0","crocodile"]},{"label":"Boa Hancock","acceptedKeys":["boa hancock","hancock"]},{"label":"Emporio Ivankov","acceptedKeys":["emporio ivankov","ivankov"]},{"label":"Inazuma","acceptedKeys":["inazuma"]},{"label":"Buggy","acceptedKeys":["buggy"]},{"label":"Daz Bonez (Mr. 1)","acceptedKeys":["daz bonez mr 1","daz bonez