      INSERT INTO character_details (character_id, detail_json)
      VALUES (4319, '{"characterId":4319,"captainAbility":"Boosts ATK of [DEX], [PSY], Fighter and Cerebral characters by 5x, boosts HP and RCV of [DEX], [PSY], Fighter and Cerebral characters by 1.3x, makes [DEX], [PSY] and [TND] orbs beneficial for [DEX], [PSY], Fighter and Cerebral characters, reduces ATK Down duration by 10 turns, and allows HP Overfill up to 2x MAX. At the start of the fight, boosts Base ATK of [DEX], [PSY], Fighter and Cerebral characters by 2,250 for 5 turns, and reduces Switch Effect of this characters by 1.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of [DEX], [PSY], Fighter and Cerebral characters by 5x, boosts HP and RCV of [DEX], [PSY], Fighter and Cerebral characters by 1.3x, makes [DEX], [PSY] and [TND] orbs beneficial for [DEX], [PSY], Fighter and Cerebral characters, reduces ATK Down duration by 10 turns, and allows HP Overfill up to 2x MAX. At the start of the fight, boosts Base ATK of [DEX], [PSY], Fighter and Cerebral characters by 2,250 for 5 turns, and reduces Switch Effect of this characters by 1."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of [DEX], [PSY], Fighter and Cerebral characters by 5x, boosts HP and RCV of [DEX], [PSY], Fighter and Cerebral characters by 1.3x, makes [DEX], [PSY] and [TND] orbs beneficial for [DEX], [PSY], Fighter and Cerebral characters, reduces ATK Down duration by 10 turns, and allows HP Overfill up to 2x MAX. At the start of the fight, boosts Chain Multiplier Growth Rate by 2x for 5 turns, and reduces Switch Effect of this characters by 1."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of [DEX], [PSY], Fighter and Cerebral characters by 5.25x-6x depending on the amount healed in the last turn, boosts HP and RCV of [DEX], [PSY], Fighter and Cerebral characters by 1.3x, makes [DEX], [PSY] and [TND] orbs beneficial for [DEX], [PSY], Fighter and Cerebral characters, reduces ATK Down duration by 10 turns, and allows HP Overfill up to 2x MAX."}],"captainNotes":null,"specialName":"Hurrying the Search","specialText":"Recovers 25% of crew''s MAX HP, recovers 5x character''s RCV in HP at the end of each turn for 10 turns, reduces enemies'' Percent Damage Reduction duration by 7 turns, and boosts Base ATK of [DEX], [PSY], Fighter and Cerebral characters by 1,750 for 3 turns. If your crew has Base ATK Boost when the special is activated, boosts Chain Multiplier Growth Rate by 1.75x for 3 turns. If your crew has Base ATK Boost and Chain Multiplication when the special is activated, boosts Crew Damage Reduction to ATK of all characters by 1.2x-2.2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. Becomes Chopper & Robin for 3 turns.","specialNotes":null,"superSpecialText":"Enables Base ATK buffs to be enhanced up to 2 times, increases boost effects of Base ATK Boost buffs by 1.2x (up to 4,000), and transforms Cerebral characters into Super Cerebral characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Sanji, Usopp, Brook, Jinbe, Franky, Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Shaka the Good\", Dr. Vegapunk \"Edison the Thinker\", Dr. Vegapunk \"Pythagoras the Wise\", Dr. Vegapunk \"Atlas the Violent\", Jewelry Bonney","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 3 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Sanji, Usopp, Brook, Jinbe, Franky, Dr. Vegapunk (Stella), Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Shaka the Good\", Dr. Vegapunk \"Edison the Thinker\", Dr