      INSERT INTO character_details (character_id, detail_json)
      VALUES (4322, '{"characterId":4322,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of Fighter, Shooter, Free Spirit and Slasher characters by 5x, by 5.5x instead if HP is above 70% at the start of the turn, boosts HP of Fighter, Shooter, Free Spirit and Slasher characters by 1.3x, makes [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. When a Barrier Penetration Enabled character hits an enemy with their normal attack, reduces enemies'' Barrier duration by 1 turn. When a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Increased Defense duration by 1 turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of Fighter, Shooter, Free Spirit and Slasher characters by 5x, by 5.5x instead if HP is above 70% at the start of the turn, boosts HP of Fighter, Shooter, Free Spirit and Slasher characters by 1.3x, makes [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. When a Barrier Penetration Enabled character hits an enemy with their normal attack, reduces enemies'' Barrier duration by 1 turn. When a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Increased Defense duration by 1 turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of Fighter, Shooter, Free Spirit and Slasher characters by 5.25x, by 5.5x instead if HP is below 30% at the start of the turn, boosts HP of Fighter, Shooter, Free Spirit and Slasher characters by 1.3x, makes [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. When a Barrier Penetration Enabled character hits an enemy with their normal attack, reduces enemies'' Resilience duration by 1 turn. When a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Increased Defense duration by 1 turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of Fighter, Shooter, Free Spirit and Slasher characters by 5.5x, by 6x instead if HP is above 70% or below 30% at the start of the turn, boosts HP of Fighter, Shooter, Free Spirit and Slasher characters by 1.3x, makes [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. When a Barrier Penetration Enabled character hits an enemy with their normal attack, reduces enemies'' Barrier and Resilience duration by 1 turn. When a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Increased Defense duration by 1 turn."}],"captainNotes":null,"specialName":"Unusual United Front","specialText":"Deals 300x character''s ATK in Typeless Fixed True damage to one enemy, and reduces Special Bind duration by 7 turns. If your Captain is a [DEX] or [QCK] Fighter or Slasher character, allows crew to stack 2 different Status ATK Boost buffs for 1 turn. If your Captain is a [DEX] or [QCK] Shooter or Free Spirit character, inflicts all enemies with Set Target, increasing damage taken from all characters by 1.75x and reducing Special Cooldown of all characters by 1 turn when they defeat an enemy, for 1 turn. Becomes Luffy & Lucci for 3 turns.","specialNotes":"Captain must fulfill both the type and class requirements.","superSpecialText":"Changes all orbs, including [BLOCK] orbs, into [TND] orbs, changes [SUPERBLOCK] orb of this character into a [TND] orb, boosts ATK against delayed enemies and paralyzed enemies by 2.25x for 1 turn, optionally removes Captain Swap durati