      INSERT INTO character_details (character_id, detail_json)
      VALUES (4338, '{"characterId":4338,"captainAbility":"Reduces Special Cooldown of Slasher and Driven characters by 2 turns at the start of the fight, boosts ATK of Slasher and Driven characters by 5.5x, by 5.75x instead if they have a beneficial orb, boosts HP of Slasher and Driven characters by 1.35x, makes [TND] orbs beneficial for Slasher and Driven characters, and reduces damage received by 25%. Up to 10 times per adventure but up to 5 times per turn, when a crewmate uses a special, boosts Final Tap ATK of Slasher and Driven characters by 5%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of Slasher and Driven characters by 2 turns at the start of the fight, boosts ATK of Slasher and Driven characters by 5.5x, by 5.75x instead if they have a beneficial orb, boosts HP of Slasher and Driven characters by 1.35x, makes [TND] orbs beneficial for Slasher and Driven characters, and reduces damage received by 25%. Up to 10 times per adventure but up to 5 times per turn, when a crewmate uses a special, boosts Final Tap ATK of Slasher and Driven characters by 5%. If the Final Tap ATK boost effect activates before the Final Stage, effect accumulates until the Final Stage. At the start of the Final Stage, applies Final Tap ATK boost based on the accumulated value."}],"captainNotes":null,"specialName":"Dicing Slashes","specialText":"Reduces Special Cooldown of top-right and middle right characters by 2 turns, reduces enemies'' Percent Damage Reduction duration by 3 turns, and changes the orb, including [BLOCK] and [WANO] orb, of this character into a [TND] orb. Launches the following effects depending on the Special Counter of this character when the special is activated: 0: Boosts ATK of Slasher and Driven characters by 2.75x for 2 turns. If your crew has 5+ Slasher or 5+ Driven characters when the special is activated, reduces Special Cooldown of this character by 13 turns. Sets Special Counter of this character to 1. 1: Reduces Bind duration by 7 turns, and reduces enemies'' Slasher and Driven Resistance by -30% for 1 turn. If your crew has ATK Up and Orb Amplification when the special is activated, increases boost effects of ATK Up and Orb Amplification buffs by +0.5x, and increases duration of any ATK Up and Orb Amplification buffs by 1 turn.","specialNotes":"Special Counter counts the number of times that the character''s special has been used in the adventure.","superSpecialText":"Enables Orb Amplification buffs to be enhanced up to 2 times, activates HP Guard of 75% effect for 1 turn, boosts Final Tap ATK of Slasher and Driven characters by 20%, and transforms Slasher characters into Super Slasher characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Sir Crocodile (Mr. 0)","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Roronoa Zoro, Sir Crocodile (Mr. 0)","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":1,"matchMode":"unique_options","options":[{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Sir Crocodile (Mr. 0)","acceptedKeys":["sir crocodile mr 0","sir crocodile","mr 0","crocodile"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["mr. 1"],"characterTags":["Baroque Works","Paramythia-type","Alabasta Arc"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key"