      INSERT INTO character_details (character_id, detail_json)
      VALUES (4339, '{"characterId":4339,"captainAbility":"Boosts ATK of all characters by 3.5x, and boost HP of all characters by 1.75x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of all characters by 3.5x, and boost HP of all characters by 1.75x."}],"captainNotes":null,"specialName":"Repelling-Out the Critical Pain","specialText":"Deals 100x the damage taken from enemies before the special is activated in Typeless damage to all enemies, recovers 30% of crew''s MAX HP, reduces Paralysis and Pain duration by 3 turns, and boosts Orb Effects of all characters by 1.75x for 1 turn. If your crew has exactly 1 Fighter character when the special is activated, sets Chain Boundaries to 2.75x and 15.0x for 2 turns. If your crew has 2+ Fighter characters when the special is activated, locks the chain multiplier at 3.25x for 3 turns. If your crew has exactly 1 Powerhouse character when the special is activated, increases duration of any Chain Lock buffs by 1 turn and increases boost effects of Chain Lock buffs by +0.5x, including effects activated in the same Ability. If your crew has 2+ Powerhouse characters when the special is activated, increases boost effects of Chain Lock buffs by +0.25x, including effects activated in the same Ability.","specialNotes":"The amount of damage possible caps at 10,000 damage taken, so 1,000,000 AOE Typeless damage.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["bartholomew kuma","kuma"],"characterTags":["Seven Warlords of the Sea","Paramythia-type","Thriller Bark Arc"],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_pain","label":"Remove Pain","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"chain_multiplier_lock","label":"Chain Multiplier: Lock","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"crewmate_hp_boost_crew","label":"HP Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"support_base_hp_boost","label":"Base HP Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base HP of all characters by 200.. This character cannot be Blown Away."],"sailorNotes":null,"potentialAbilities":[{"Name":"Enrage/Reduce Increase Damage Taken duration","description":["Boosts base ATK by 200 the turn after taking damage and reduces Increase Damage Taken duration by 2 turns"]},{"Name":"Nutrition/Reduce Hunger stacks","description":["Boosts base ATK by 200 the turn after recovering 3,000, HP and reduces Hunger stack by 2 stack"]}],"supportData":[{"supportedCharactersText":"Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Choppe