      INSERT INTO character_details (character_id, detail_json)
      VALUES (4344, '{"characterId":4344,"captainAbility":"Boosts ATK of Driven characters by 5.25x, boosts ATK of all other characters by 3.75x, boosts HP of all characters by 1.3x, makes [DEX] and [QCK] orbs beneficial for Driven characters, and reduces Special Bind duration by 10 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Driven characters by 5.25x, boosts ATK of all other characters by 3.75x, boosts HP of all characters by 1.3x, makes [DEX] and [QCK] orbs beneficial for Driven characters, and reduces Special Bind duration by 10 turns."}],"captainNotes":null,"specialName":"Sixteen Holy Bullets: Godthread","specialText":"Deals 300x character''s ATK in Typeless damage to all enemies, changes all orbs, including [BLOCK] orbs, into Matching orbs, and recovers 30% of crew''s MAX HP. If your crew has ATK Up and Orb Amplification when the special is activated, boosts Base ATK of Driven characters by 1,250, preventing buff clears, for 2 turns, and adds 1.5 to Chain Multiplier, preventing buff clears, for 2 turns; otherwise, boosts ATK of Driven characters by 2.5x, preventing buff clears, for 2 turns, and boosts Orb Effects of Driven characters by 2.5x, preventing buff clears, for 2 turns.","specialNotes":null,"superSpecialText":"Deals 150x character''s ATK in Typeless damage to all enemies, reduces Special Cooldown of Driven and Slasher characters by 2 turns, and transforms Driven characters into Super Driven characters.","superSpecialCriteriaText":"This character must be captain and an active support ability must have been activated by being inflicted by an enemy action or your crew must consist of any 1 of the following, excluding Supports and counting only 1 per unit: Monkey D. Luffy, Trafalgar Law, Diamante, Pica, Trebol, Vergo, Sugar, Kaido, Caesar Clown (Gastino), Monet","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain and an active support ability must have been activ