      INSERT INTO character_details (character_id, detail_json)
      VALUES (4366, '{"characterId":4366,"captainAbility":"Reduces Special Cooldown of all characters by 4 turns at the start of the fight, boosts ATK of [Egghead Arc], [Logia-type] and [Navy] characters by 1.1x, boosts ATK of [DEX], Shooter and Slasher characters by 6x, by 6.6x instead if they have the applicable tag, boosts ATK of all other characters by 4.5x, by 4.95x instead if they have the applicable tag, boosts HP of all characters by 1.35x, and makes [DEX] and [TND] orbs beneficial for all characters. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Egghead Arc], [Logia-type] and [Navy] characters by 1.3x instead, boosts ATK of [PSY], Free Spirit and Slasher characters by 7.8x instead if they have the applicable tag, and boosts ATK of all other characters by 5.85x instead if they have the applicable tag. If your crew has 3+ [Egghead Arc], [Logia-type] or [Navy] characters, reduces Burn and Special Bind duration by 10 turns. If your crew has 4+ [Navy] characters, makes all Specials that apply Class or Type restricted buffs apply to all characters instead.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 4 turns at the start of the fight, boosts ATK of [Egghead Arc], [Logia-type] and [Navy] characters by 1.1x, boosts ATK of [DEX], Shooter and Slasher characters by 6x, by 6.6x instead if they have the applicable tag, boosts ATK of all other characters by 4.5x, by 4.95x instead if they have the applicable tag, boosts HP of all characters by 1.35x, and makes [DEX] and [TND] orbs beneficial for all characters. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Egghead Arc], [Logia-type] and [Navy] characters by 1.3x instead, boosts ATK of [PSY], Free Spirit and Slasher characters by 7.8x instead if they have the applicable tag, and boosts ATK of all other characters by 5.85x instead if they have the applicable tag. If your crew has 3+ [Egghead Arc], [Logia-type] or [Navy] characters, reduces Burn and Special Bind duration by 10 turns. If your crew has 4+ [Navy] characters, makes all Specials that apply Class or Type restricted buffs apply to all characters instead."}],"captainNotes":"Buff restriction override does not apply to \"Partial\" buffs. The buff restriction override applies to any effect that would normally affect only certain classes or types, including, but not restricted to: ATK buffs, Orb buffs, Base ATK buffs, Cooldown Reduction, Normal Attack Defensive Effect Bypass, Orb Lock buffs and Slot Barrier debuffs, but does not affect defensive buffs. This effect doesn''t not affect Swap abilities, Support abilities, Super Special abilities, VS Special abilities or effects obtained from Following Turn or Tap-Timing Following Turn buffs.","specialName":"Obstacle-Eliminating Ama no Murakumo Sword","specialText":"Up to 2 times per adventure, reduces Special Cooldown of middle row characters by 6 turns. Sets Chain Boundaries to 3.25x-4x and 35.0x for 2 turns depending on the outcome of Action Special. If a [PSY] character is supporting this character, applies Territory: Slasher to the field for 3 turns; applies Territory: Shooter to the field for 3 turns otherwise. If your crew has 5+ [Egghead Arc], [Navy] or [Logia-type] characters, increases Chain Tap Timing Bonus of [DEX], Shooter and Slasher characters to +0.3x-0.7x, can be enhanced up to 2 times, for 2 turns depending on Tap Timing; increases Chain Tap Timing Bonus of [DEX], Shooter and Slasher characters to +0.3x-0.5x for 1 turn depending on Tap Timing otherwise.","specialNotes":". Chain Boundary: MISS: 3.25x, GOOD: 3.5x, GREAT: 3.7x, PERFECT: 3.9x, EXCELLENT 4x. Tap Timing: GOOD: +0.3, GREAT: +0.5, PERFECT: +0.7; GOOD: +0.3, GREAT: +0.4, PERFECT: +0.5 otherwise.","superSpecialText":"Reduces enemies'' Intimidation duration by 2 turns, reduces Special Cooldown of top row characters by 4 turns, boosts Orb Effects of all characters by 2.5x, allowing override, for 2 turns, transforms [DEX] characters into Super [DEX] characters, and transforms Shooter character into Super Shooter characters.","superSpecialCriteriaText":"This character must be captain. Your crew must have 6 Shooter or Slasher characters; or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Sakazuki (Akainu), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Monkey D. Garp, Sentomaru, Vice Admiral Doll, Tsuru, Zephyr (Z), Tashigi, Kuzan (Aokiji), Coby, Rob Lucci, Kaku, Dr. Vegapunk (Stella)","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. Your crew must have 6 Shooter or Slasher characters; or your crew must consist of any 2 of the following, excluding Supports and counting only 1 per unit: Sakazuki (Akainu), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Monkey D. Garp, Sentomaru, Vice Admiral Doll, Tsuru, Zephyr (Z), Tashigi, Kuzan (Aokiji), Coby, Rob Lucci, Kaku, Dr. Vegapunk (Stella)","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Sakazuki (Akainu)","acceptedKeys":["sakazuki akainu","sakazuki","akainu"]},{"label":"Issho (Fujitora)","acceptedKeys":["issho fujitora","issho","fujitora"]},{"label":"Aramaki (Ryokugyu)","acceptedKeys":["aramaki ryokugyu","aramaki","ryokugyu"]},{"label":"Sengoku","acceptedKeys":["sengoku"]},{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Sentomaru","acceptedKeys":["sentomaru"]},{"label":"Vice Admiral Doll","acceptedKeys":["vice admiral doll","doll"]},{"label":"Tsuru","acceptedKeys":["tsuru"]},{"label":"Zephyr (Z)","acceptedKeys":["zephyr z","zephyr","z"]},{"label":"Tashigi","acceptedKeys":["tashigi"]},{"label":"Kuzan (Aokiji)","acceptedKeys":["kuzan aokiji","kuzan","aokiji"]},{"label":"Coby","acceptedKeys":["