      INSERT INTO character_details (character_id, detail_json)
      VALUES (4381, '{"characterId":4381,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Slasher and Striker characters by 5.25x, by 5.775x instead if your crew has 4+ [Egghead Arc] characters, boosts RCV of Slasher and Striker characters by 1.25x, makes [PSY], [RCV] and [TND] orbs beneficial for Slasher and Striker characters, and reduces Burn duration by 10 turns. If your crew has 5+ [Egghead Arc], [Worst Generation] or [Paramythia-type] characters, restores Special Cooldown of all characters by 2 turns when they are rewinded.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Slasher and Striker characters by 5.25x, by 5.775x instead if your crew has 4+ [Egghead Arc] characters, boosts RCV of Slasher and Striker characters by 1.25x, makes [PSY], [RCV] and [TND] orbs beneficial for Slasher and Striker characters, and reduces Burn duration by 10 turns. If your crew has 5+ [Egghead Arc], [Worst Generation] or [Paramythia-type] characters, restores Special Cooldown of all characters by 2 turns when they are rewinded."}],"captainNotes":null,"specialName":"Strike for Her Father","specialText":"Deals 300x character''s ATK in Typeless Fixed True damage to one enemy, reduces enemies'' Threshold Damage Reduction duration by 7 turns, increases Orb Effects of beneficial [PSY], [RCV], [TND] and [SEMLA] orbs to 3x for 3 turns, and increases boost effects of ATK Up buffs by 1.25x (up to 10x). If your crew has 4+ [Egghead Arc], [Worst Generation] or [Paramythia-type] characters, increases boost effects of Chain Addition buffs by +1.0x, and adds 1.6x, can be enhanced up to 2 times, to Chain Multiplier for 3 turns; adds 1.4x, can be enhanced up to 2 times, to Chain Multiplier for 1 turn otherwise.","specialNotes":null,"superSpecialText":"Changes all orbs, including [BLOCK] orbs, into [TND] orbs, cha