      INSERT INTO character_details (character_id, detail_json)
      VALUES (4387, '{"characterId":4387,"captainAbility":"Reduces Special Cooldown of [INT], Slasher and Striker characters by 2 turns at the start of the fight, reduces VS Gauge and Switch Effect of [INT], Slasher and Striker characters by 2 at the start of the fight, boosts ATK of [INT], Slasher and Striker characters by 6x, boosts ATK of all other characters by 4x, boosts HP of [INT], Slasher and Striker characters by 1.35x, makes [INT] and [TND] orbs beneficial for all characters, and reduces damage received by 20%. If this character is your Captain and performs EXCELLENT with their Action Special, adds the following effect for 3 turns: boosts Color Affinity of all characters by 1.3x. If a crew member uses a special to boost Chain Multiplier Growth Rate, increases duration of any Chain Multiplier Growth Rate buffs by 1 turn, and increases boost effects of Chain Multiplier Growth Rate buffs by +0.25x. If a crew member uses a special to boost Chain Tap Timing, increases duration of any Chain Tap Timing buffs by 1 turn, and increases boost effects of Chain Tap Timing buffs by +0.25x. If the enemy has Threshold Damage Reduction status, reduces enemies'' Threshold Damage Reduction effect by 100%.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [INT], Slasher and Striker characters by 2 turns at the start of the fight, reduces VS Gauge and Switch Effect of [INT], Slasher and Striker characters by 2 at the start of the fight, boosts ATK of [INT], Slasher and Striker characters by 6x, boosts ATK of all other characters by 4x, boosts HP of [INT], Slasher and Striker characters by 1.35x, makes [INT] and [TND] orbs beneficial for all characters, and reduces damage received by 20%. If this character is your Captain and performs EXCELLENT with their Action Special, adds the following effect for 3 turns: boosts Color Affinity of all characters by 1.3x. If a crew member uses a special to boost Chain Multiplier Growth Rate, increases duration of any Chain Multiplier Growth Rate buffs by 1 turn, and increases boost effects of Chain Multiplier Growth Rate buffs by +0.25x. If a crew member uses a special to boost Chain Tap Timing, increases duration of any Chain Tap Timing buffs by 1 turn, and increases boost effects of Chain Tap Timing buffs by +0.25x. If the enemy has Threshold Damage Reduction status, reduces enemies'' Threshold Damage Reduction effect by 100%."}],"captainNotes":null,"specialName":"Storming God Valley","specialText":"Reduces Special Bind and Chain Coefficient Reduction duration by 10 turns, applies Territory: [INT] to the field for 3 turns, and boosts Color Affinity of Slasher and Striker characters by 2.75x, can be enhanced up to 2 times, for 2 turns. If your Captain is a Slasher or Striker character, boosts Chain Multiplier Growth Rate by 1.75x-2.5x for 2 turns depending on the outcome of Action Special. If your crew has 6 Slasher or 6 Striker characters when the special is activated, boosts Advantageous Class Effect of Slasher and Striker characters by 2.25x for 2 turns. If the enemy is a [Logia-type], [Paramythia-type], [Zoan-type], [Mythical Zoan-type] or [Ancient Zoan-type] character, increases boost effects of Advantageous Class Effect buffs by +0.25x, including effects activated in the same ability.","specialNotes":"MISS: 1.75x, GOOD: 2.0x, GREAT: 2.1x, PERFECT: 2.3x, EXCELLENT 2.5x","superSpecialText":"Changes Class 1 of all non-Slasher Fighter characters to Slasher class for 3 turns, reduces enemies'' positive buffs duration by 1 turn, transforms Slasher character into Super Slasher characters, and transforms Striker character into Super Striker characters.","superSpecialCriteriaText":"This character must be captain. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Portgas D. Ace, Shanks, Buggy, Edward Newgate (Whitebeard), Kozuki Oden, Kozuki Toki, Crocus, Dogstorm, Cat Viper, Nozudon, Sambel, Douglas Bu