      INSERT INTO character_details (character_id, detail_json)
      VALUES (4390, '{"characterId":4390,"captainAbility":"Boosts ATK of Striker and Powerhouse characters by 3.75x, and boosts HP of [STR] characters by 1.35x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Striker and Powerhouse characters by 3.75x, and boosts HP of [STR] characters by 1.35x."}],"captainNotes":null,"specialName":"Recalled Grudge","specialText":"Delays all enemies by 1 turn, reduces crew''s current HP by 85%, deals 30x the amount of HP subtracted in Typeless damage to all enemies, reduces ATK Down duration by 6 turns, and boosts Base ATK of Striker and Powerhouse characters by 1,250 for 1 turn. If your crew has 4+ [Egghead Arc] characters or your crew has Base ATK Boost when the special is activated, inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kaido"],"characterTags":["Rocks Pirates","Egghead Arc"],"builderAbilities":[{"key":"remove_atk_down","label":"Remove ATK Down","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_delay","label":"Delay","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"crewmate_atk_boost_powerhouse","label":"ATK Boost: Powerhouse","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_powerhouse","label":"RCV Boost: Powerhouse","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_powerhouse","label":"HP Boost: Powerhouse","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_super_tandem","label":"Super Tandem","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_super_tandem","label":"Super Tandem","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"superTandemData","coverageMode":"explicit"},{"key":"support_base_atk_boost_damage","label":"Base ATK Boost","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK, HP and RCV of [STR], Striker and Powerhouse characters by 50.. If this character has a [SEMLA] or [WANO] orb and you attack with this character, reduces enemies'' Striker and Powerhouse Resistance by -10% for 1 turn."],"sailorNotes":null,"potentialAbilities":[{"Name":"Enrage/Reduce Increase Damage Taken duration","description":["Boosts base ATK by 200 the turn after taking damage and reduces Increase Damage Taken duration by 2 turns"]},{"Name":"Super Tandem","description":["Obtain Super Tandem Lv.5"]}],"supportData":[{"supportedCharactersText":"[STR] Striker characters","levelDescriptions":["Once per adventure, when you reach the final stage, boosts base ATK of Striker characters by 300 for 1 turn."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":{"requirement":"Your crew must consist of 2 Striker characters and any 1 of the following, excluding supports and counting only 1 per unit: Edward Newgate (Whitebeard), Shiki, Charlotte Linlin (Big Mom)","levels":[{"level":5,"effect":"Boosts Tandem ATK of [STR], Striker and Powerhouse characters by 1.5x for 1 turn, and boosts Crew Damage Reduction to ATK of all characters by 1x-1.5x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn."}],"criteria":{"rawText":"Your crew must consist of 2 Striker characters and any 1 of the following, excluding supports and counting only 1 per unit: Edward Newgate (Whitebeard), Shiki, Charlotte Linlin (Big Mom)","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"}},"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4390,"pattern":[{"type":"Normal","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"ATK","def":50,"spd":100},"cost":30}}');


