      INSERT INTO character_details (character_id, detail_json)
      VALUES (4391, '{"characterId":4391,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [Revolutionary Army] characters by 1.1x, boosts ATK of Cerebral characters by 5x-5.5x, by 5.25x-5.775x instead if they have a beneficial orb, boosts HP of Cerebral characters by 1.25x, and makes [DEX], [INT] and [TND] orbs beneficial for all characters. If your crew has 5+ [Revolutionary Army] characters, attacks will ignore damage reducing Barriers and Buffs.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of [Revolutionary Army] characters by 1.1x, boosts ATK of Cerebral characters by 5x-5.5x, by 5.25x-5.775x instead if they have a beneficial orb, boosts HP of Cerebral characters by 1.25x, and makes [DEX], [INT] and [TND] orbs beneficial for all characters. If your crew has 5+ [Revolutionary Army] characters, attacks will ignore damage reducing Barriers and Buffs."}],"captainNotes":"Attacks are still affected by DEF value. DEF boost buffs (Blue shield) still reduce your damage and you cannot kill through Resilience, but Damage Negating (Yellow shield), % Damage Reduction (Rainbow shield), Barriers and Threshold Damage Reduction are ignored. Enemy attacks will go through YOUR defensive buffs.","specialName":"Signaling the Revolution","specialText":"Ignores Debuff Protection and reduces the defense of all enemies by 80% for 1 turn, and reduces enemies'' Threshold Damage Reduction duration by 7 turns. If your crew has 6 Cerebral characters, swaps middle-left character with your Captain for 1 turn, and ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.25x, can be enhanced up to 2 times, for 1 turn; inflicts all enemies with Increase Damage Taken by 2x for 1 turn otherwise. If your crew has 3+ [Revolutionary Army] characters, allows crew to stack 2 different Status ATK Boost buffs for 1 turn.","specialNotes":null,"superSpecialText":"Optionally removes Captain Swap duration completely, adds 100x character''s ATK as Additional Typeless Damage for 5 turns, boosts ATK against enemies with reduced defense by 2.5x for 1 turn, transforms [DEX] characters into Super [DEX] characters, and transforms Cerebral character into Super Cerebral characters.","superSpecialCriteriaText":"This character must be captain. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: Sabo, Koala, Inazuma, Morley, Karasu, Lindbergh, Belo Betty, Ginny, Hack, Nico Robin, Monkey D. Luffy","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: Sabo, Koala, Inazuma, Morley, Karasu, Lindbergh, Belo Betty, Ginny, Hack, Nico Robin, Monkey D. Luffy","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Sabo","acceptedKeys":["sabo"]},{"label":"Koala","acceptedKeys":["koala"]},{"label":"Inazuma","acceptedKeys":["inazuma"]},{"label":"Morley","acceptedKeys":["morley"]},{"label":"Karasu","acceptedKeys":["karasu"]},{"label":"Lindbergh","acceptedKeys":["lindbergh"]},{"label":"Belo Betty","acceptedKeys":["belo betty","betty"]},{"label":"Ginny","acceptedKeys":["ginny"]},{"label":"Hack","acceptedKeys":["hack"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["dragon & ivankov & kuma","dragon","ivankov","kuma"],"characterTags":["Revolutionary Army","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":7,"isCompleteRemoval":false,"slot