      INSERT INTO character_details (character_id, detail_json)
      VALUES (4392, '{"characterId":4392,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of [DEX], Shooter and Cerebral characters by 5.25x, by 5.75x instead if they have a [RCV] or [TND] orb, boosts RCV of [DEX], Shooter and Cerebral characters by 1.3x, and makes [DEX], [RCV] and [TND] orbs beneficial for [DEX], Shooter and Cerebral characters. When a [DEX], Shooter or Cerebral character attacks with Type Advantage, changes the orb of that character to [RCV] after attacking.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of [DEX], Shooter and Cerebral characters by 5.25x, by 5.75x instead if they have a [RCV] or [TND] orb, boosts RCV of [DEX], Shooter and Cerebral characters by 1.3x, and makes [DEX], [RCV] and [TND] orbs beneficial for [DEX], Shooter and Cerebral characters. When a [DEX], Shooter or Cerebral character attacks with Type Advantage, changes the orb of that character to [RCV] after attacking."}],"captainNotes":null,"specialName":"Awaited Reunion","specialText":"Reduces Bind duration by 6 turns, reduces enemies'' Percent Damage Reduction duration by 6 turns, and boosts Orb Effects of Shooter and Cerebral characters by 3x, can be enhanced up to 2 times, for 2 turns. If you have used 10+ [RCV] orbs in normal attacks or your crew has 8+ turns of End of Turn Healing when the special is activated, increases boost effects of Orb Amplification buffs by +0.5x and increases duration of any Orb Amplification buffs by 1 turn, including effects activated in the same ability. If your crew has 3+ [Revolutionary Army] characters, optionally removes Captain Swap duration completely, and inflicts all enemies with Set Target, increasing damage taken from Shooter and Cerebral characters by 2x and reducing Special Cooldown of Shooter and Cerebral characters by 2 turns when they defeat an ene