      INSERT INTO character_details (character_id, detail_json)
      VALUES (4420, '{"characterId":4420,"captainAbility":"Boosts ATK of Cerebral characters by 4.25x, boosts HP of Cerebral characters by 1.25x, and makes [DEX], [PSY] and [TND] orbs beneficial for all characters.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Cerebral characters by 4.25x, boosts HP of Cerebral characters by 1.25x, and makes [DEX], [PSY] and [TND] orbs beneficial for all characters."}],"captainNotes":null,"specialName":"Caring for a Friend","specialText":"Locks all orbs for 1 turn, and reduces enemies'' Resilience duration by 6 turns. If enemies have Increase Damage Taken when the special is activated, boosts ATK against enemies inflicted with Weaken by 2x for 1 turn; inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn otherwise. If your crew has 4+ [Revolutionary Army] characters, boosts ATK of [DEX], Fighter and Cerebral characters by 2.75x, can be enhanced up to 2 times, for 3 turns, and increases duration of any Chain Lock buffs by 1 turn; boosts ATK of [DEX], Fighter and Cerebral characters by 2.25x for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["koala"],"characterTags":["Revolutionary Army","Egghead Arc"],"builderAbilities":[{"key":"remove_resilience","label":"Remove Resilience","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"exten