      INSERT INTO character_details (character_id, detail_json)
      VALUES (4423, '{"characterId":4423,"captainAbility":"Boosts ATK of Cerebral and Free Spirit characters by 4x, boosts HP of Cerebral and Free Spirit characters by 1.2x, and makes [STR] orbs beneficial for Cerebral and Free Spirit characters.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Cerebral and Free Spirit characters by 4x, boosts HP of Cerebral and Free Spirit characters by 1.2x, and makes [STR] orbs beneficial for Cerebral and Free Spirit characters."}],"captainNotes":null,"specialName":"Emotional Last Words","specialText":"Reduces enemies'' Percent Damage Reduction duration by 6 turns, reduces Paralysis duration by 6 turns, removes Poison duration completely, sets Chain Boundaries to 2.75x and 15.0x for 1 turn, randomizes all orbs into [STR], [DEX], [QCK], [INT] or [RCV] orbs, and becomes unable to change to [PSY] and [TND] orbs for 1 turn. If your crew has 6 Free Spirit characters, reduces enemies'' Free Spirit Resistance by -30% for 1 turn. If your crew has 2+ [Scientist] characters, reduces enemies'' Cerebral Resistance by -30% for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["dr. vegapunk","vegapunk"],"characterTags":["Vegapunk","Scientist","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_poison","label":"Remove Poison","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"e