      INSERT INTO character_details (character_id, detail_json)
      VALUES (4425, '{"characterId":4425,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of Powerhouse and Free Spirit characters by 5.25x, boosts HP of Powerhouse and Free Spirit characters by 1.4x, makes [QCK], [BOMB] and [SUPERBOMB] orbs beneficial for Powerhouse and Free Spirit characters, and [BOMB] and [SUPERBOMB] orbs will deal 95% less damage to the crew. If your crew has 4+ [Straw Hat Pirates], [Logia-type] or [Scientist] characters, boosts ATK of Powerhouse and Free Spirit characters by 5.775x instead; additionally, if this character has a [BOMB] or [SUPERBOMB] orb and you attack with this character, reduces enemies'' Threshold Damage Reduction duration by 6 turns. If your crew has 4+ [Egghead Arc] characters, reduces Bind duration by 3 turns, and makes crew immune to Blow Away.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of Powerhouse and Free Spirit characters by 5.25x, boosts HP of Powerhouse and Free Spirit characters by 1.4x, makes [QCK], [BOMB] and [SUPERBOMB] orbs beneficial for Powerhouse and Free Spirit characters, and [BOMB] and [SUPERBOMB] orbs will deal 95% less damage to the crew. If your crew has 4+ [Straw Hat Pirates], [Logia-type] or [Scientist] characters, boosts ATK of Powerhouse and Free Spirit characters by 5.775x instead; additionally, if this character has a [BOMB] or [SUPERBOMB] orb and you attack with this character, reduces enemies'' Threshold Damage Reduction duration by 6 turns. If your crew has 4+ [Egghead Arc] characters, reduces Bind duration by 3 turns, and makes crew immune to Blow Away."}],"captainNotes":null,"specialName":"Benefactor-Protecting Radical Beam","specialText":"Deals 120x character''s 