      INSERT INTO character_details (character_id, detail_json)
      VALUES (4430, '{"characterId":4430,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of all characters by 4x-4.5, depending on how many previous consecutive turns you have defeated an enemy, up to 5 turns, boosts HP of all characters by 1.2x, boosts base ATK of [Navy] characters by 500, and makes [PSY] and [INT] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, restores Special Cooldown of all characters by 3 turns when they are rewinded.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, boosts ATK of all characters by 4x-4.5, depending on how many previous consecutive turns you have defeated an enemy, up to 5 turns, boosts HP of all characters by 1.2x, boosts base ATK of [Navy] characters by 500, and makes [PSY] and [INT] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, restores Special Cooldown of all characters by 3 turns when they are rewinded."}],"captainNotes":null,"specialName":"Piercing Ama no Murakumo Sword","specialText":"Reduces Special Cooldown of all characters by 1 turn, deals 100x character''s ATK in Typeless damage to one enemy, reduces enemies'' Resilience duration by 6 turns, adds 1.2x-1.8x to chain multiplier for 3 turns, and recovers 30% of crew''s MAX HP. If HP is below 50% when the special is activated or your crew has 2+ [Navy] characters, locks all orbs for 2 turns, and carries over 0.1x-1.5x of Chain Multiplier on this turn to the next turn. If your crew has 3+ [Navy] characters, increases duration of any team Damage Nullification and Threshold Damage Reduction buffs by 1 turn.","specialNotes":"For every 5 Special Cooldown charges after this special is charged to MAX, the Chain Addition increases by +0.1x until its maximum values. Carried-over chain amount is equal to 0.1 ✕ final chain multiplier this turn and will be added into the next turn''s chain multiplier; in order to get +1.5 chain carried over, you need to reach 15x or higher chain multiplier.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kizaru","borsalino"],"characterTags":["Navy","Navy Admiral","Logia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_resilience","label":"Remove Resilience","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage_other","label":"Other","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"chain_multiplier_lock_min_max","label":"Chain Multiplier: Lock Multiplier Min/Max","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"lock_slots","label":"Lock Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_chain_coefficient_reduction","label":"Remove Chain Coefficient Reduction","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_critical_atk","label":"Critical ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_reduce_enemy_effect_turns_resilience","label":"Reduce Enemy Effect Turns: Resilience","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"},{"key":"support_hp_recovery","label":"HP Recovery","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Makes [PSY] orbs beneficial for Slasher and Powerhouse characters.. If your crew has 2+ [Navy] or [World Government] characters, reduces Chain Coefficient Reduction duration by 2 turns."],"sailorNotes":null,"potentialAbilities":[{"Name":"Critical Hit","description":["If you hit a PERFECT with this character, there is a 80% chance to deal 8% of this character''s attack in extra damage"]},{"Name":"Pinch Healing","description":["If HP is below 50% at the start of the turn, recovers 1x this character''s RCV at the end of the turn for each time you hit a PERFECT with this character"]},{"Name":"Cooldown Reduction","description":["Reduces Special Cooldown of this character by 9 turns at the start of the fight"]}],"supportData":[{"supportedCharactersText":"[Navy] characters","levelDescriptions":["Once per adventure, when the supported character uses their special, reduces enemies'' Resilience duration by 1 turn, and recovers 2,000 HP."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4430,"ability":[{"effects":[{"attributes":["HP","ATK","SPD"],"effect":"buff","level":5,"targeting":{"targets":["[PSY]","Slasher"]}},{"attributes":["Guard"],"effect":"buff","level":4,"targeting":{"targets":["[PSY]","Slasher"]}}]}],"special":[{"cooldown":22,"effects":[{"amount":3000,"effect":"damage","type":"fixed","targeting":{"targets":["enemies"],"count":2}},{"attributes":["ATK","SPD"],"level":4,"duration":15,"effect":"buff","targeting":{"targets":["[PSY]","Slasher"]}},{"attributes":["Special Bind"],"chance":50,"duration":15,"effect":"evade","targeting":{"targets":["[PSY]","Slasher"]}}]}],"resilience":[{"attribute":"Special Bind","chance":80,"type":"debuff"},{"attribute":"[INT]","percentage":20,"type":"damage"}],"pattern":[{"type":"Normal","action":"attack"},{"type":"Power","action":"attack"},{"level":1,"area":"Small","action":"heal"},{"type":"Power","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"SPT","def":192,"spd":187},"cost":20}}');


