      INSERT INTO character_details (character_id, detail_json)
      VALUES (4432, '{"characterId":4432,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, reduces VS Gauge and Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [Straw Hat Pirates], [Giant], [Logia-type] and [Paramythia-type] characters by 1.1x, boosts ATK of [QCK] and Powerhouse characters by 6x-6.6x, boosts ATK of all other characters by 4.5x-4.95x, boosts HP of [QCK] and Powerhouse characters by 1.35x, makes [QCK], [RCV] and [TND] orbs beneficial for all characters, and reduces Special Bind duration by 10 turns on this character. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Straw Hat Pirates], [Giant], [Logia-type] and [Paramythia-type] characters by 1.3x instead, boosts ATK of [QCK] and Powerhouse characters by 6x-7.8x instead, and boosts ATK of all other characters by 4.5x-5.85x instead. If your crew has 4+ [Egghead Arc] or [Land of Wano Arc] characters, restores Special Cooldown of all characters by 10 turns when they are rewinded. If your crew has 4+ [Egghead Arc] or [Land of Wano Arc] characters and you gain an ATK Up or Orb Amplification buff, enables ATK Up and Orb Amplification buffs to be enhanced up to 2 times, and increases boost effects of ATK Up and Orb Amplification buffs by 1.2x (up to 8x).","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 2 turns at the start of the fight, reduces VS Gauge and Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [Straw Hat Pirates], [Giant], [Logia-type] and [Paramythia-type] characters by 1.1x, boosts ATK of [QCK] and Powerhouse characters by 6x-6.6x, boosts ATK of all other characters by 4.5x-4.95x, boosts HP of [QCK] and Powerhouse characters by 1.35x, makes [QCK], [RCV] and [TND] orbs beneficial for all characters, and reduces Special Bind duration by 10 turns on this character. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Straw Hat Pirates], [Giant], [Logia-type] and [Paramythia-type] characters by 1.3x instead, boosts ATK of [QCK] and Powerhouse characters by 6x-7.8x instead, and boosts ATK of all other characters by 4.5x-5.85x instead. If your crew has 4+ [Egghead Arc] or [Land of Wano Arc] characters, restores Special Cooldown of all characters by 10 turns when they are rewinded. If your crew has 4+ [Egghead Arc] or [Land of Wano Arc] characters and you gain an ATK Up or Orb Amplification buff, enables ATK Up and Orb Amplification buffs to be enhanced up to 2 times, and increases boost effects of ATK Up and Orb Amplification buffs by 1.2x (up to 8x)."}],"captainNotes":null,"specialName":"Gum-Gum Dawn Cymbal","specialText":"Reduces Special Bind duration by 10 turns, adds 80x character''s ATK as Additional Typeless Damage for 5 turns, applies Territory: [QCK] to the field for 3 turns, and boosts Orb Effects of [QCK] and Powerhouse characters by 3.5x-4.25x for 2 turns depending on the outcome of Action Special. If your crew has 5+ [Straw Hat Pirates], [Giant], [Logia-type] or [Paramythia-type] characters, makes [STR], [DEX], [QCK], [PSY] and [INT] orbs beneficial for all characters for 2 turns, and sets Chain Boundaries to 3.25x and 35.0x, can be enhanced up to 2 times, for 2 turns; sets Chain Boundaries to 2.5x and 30.0x for 1 turn otherwise.","specialNotes":"MISS: 3.5x, GOOD: 3.7x, GREAT: 3.8x, PERFECT: 3.9x, EXCELLENT 4.25x","superSpecialText":"Reduces Switch Effect of Powerhouse characters by 4, changes the orb, including [BLOCK] and [SUPERBLOCK] orb, of this character into a [TND] orb, increases boost effects of Chain Lock buffs by +0.25x, boosts Advantageous Class Effect of Powerhouse characters by 2x for 2 turns, transforms [QCK] characters into Super [QCK] characters, and transforms Powerhouse characters into Super Powerhouse characters.","superSpecialCriteriaText":"This character must be captain. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Roronoa Zoro, Sanji, Nami, Usopp, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Jewelry Bonney, Dr. Vegapunk (Stella), Dr. Vegapunk \"Shaka the Good\", Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Edison the Thinker\", Dr. Vegapunk \"Pythagoras the Wise\", Dr. Vegapunk \"Atlas the Violent\", S-Snake, Sentomaru, Bartholomew Kuma, Portgas D. Ace, Sabo, Monkey D. Garp, Makino, Shanks, Dorry, Broggy, Kashii, Oimo","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Roronoa Zoro, Sanji, Nami, Usopp, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Jewelry Bonney, Dr. Vegapunk (Stella), Dr. Vegapunk \"Shaka the Good\", Dr. Vegapunk \"Lilith the Evil\", Dr. Vegapunk \"Edison the Thinker\", Dr. Vegapunk \"Pythagoras the Wise\", Dr. Vegapunk \"Atlas the Violent\", S-Snake, Sentomaru, Bartholomew Kuma, Portgas D. Ace, Sabo, Monkey D. Garp, Makino, Shanks, Dorry, Broggy, Kashii, Oimo","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Sanji","acceptedKeys":["sanji"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},{"label":"Brook","acceptedKeys":["brook"]},{"label":"Jinbe","acceptedKeys":["jinbe"]},{"label":"Jewelry Bonney","acceptedKeys":["jewelry bonney","bonney"]},{"label":"Dr. Vegapunk (Stella)","acceptedKeys":["dr vegapunk stella","dr vegapunk","stella","vegapunk"]},{"label":"Dr. Vegapunk \"Sha