      INSERT INTO character_details (character_id, detail_json)
      VALUES (4436, '{"characterId":4436,"captainAbility":"Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, boosts ATK of Powerhouse characters by 4.5x, by 5x instead if they have a beneficial orb, boosts HP of Powerhouse characters by 1.5x, makes [INT], [RCV] and [TND] orbs beneficial for Powerhouse characters, and deals 150x character''s ATK in [QCK] damage to all enemies at the end of each turn. If your crew has 3+ [Giant], [Straw Hat Pirates] or [Four Emperors] characters, boosts ATK of Powerhouse characters by 4.95x, by 5.5x instead if they have a beneficial orb. If your crew has 3+ [Giant] characters and you gain a Chain Multiplier Growth Rate buff, up to 2 times per adventure, activates \"Advancing Giant Pirate Crew\" in the following turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, boosts ATK of Powerhouse characters by 4.5x, by 5x instead if they have a beneficial orb, boosts HP of Powerhouse characters by 1.5x, makes [INT], [RCV] and [TND] orbs beneficial for Powerhouse characters, and deals 150x character''s ATK in [QCK] damage to all enemies at the end of each turn. If your crew has 3+ [Giant], [Straw Hat Pirates] or [Four Emperors] characters, boosts ATK of Powerhouse characters by 4.95x, by 5.5x instead if they have a beneficial orb. If your crew has 3+ [Giant] characters and you gain a Chain Multiplier Growth Rate buff, up to 2 times per adventure, activates \"Advancing Giant Pirate Crew\" in the following turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, boosts ATK of Powerhouse characters by 4.75x, boosts HP of Powerhouse characters by 1.5x, makes [PSY], [RCV] and [TND] orbs beneficial for Powerhouse characters, and deals 150x character''s ATK in [QCK] damage to all enemies at the end of each turn. If your crew has 3+ [Giant], [Straw Hat Pirates] or [Four Emperors] characters, boosts ATK of Powerhouse characters by 5.225x instead. If your crew has 3+ [Giant] characters and you gain a Chain Multiplier Growth Rate buff, up to 2 times per adventure, activates \"Advancing Giant Pirate Crew\" in the following turn."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of Powerhouse characters by 2 turns at the start of the fight, boosts ATK of Powerhouse characters by 5.25x, boosts HP of Powerhouse characters by 1.5x, makes [QCK], [PSY], [INT], [RCV] and [TND] orbs beneficial for Powerhouse characters, and deals 300x character''s ATK in [QCK] damage to all enemies at the end of each turn. If your crew has 3+ [Giant], [Straw Hat Pirates] or [Four Emperors] characters, boosts ATK of Powerhouse characters by 5.775x instead. If your crew has 3+ [Giant] characters and you gain a Chain Multiplier Growth Rate buff, up to 2 times per adventure, activates \"Advancing Giant Pirate Crew\" in the following turn."}],"captainNotes":null,"specialName":"Advancing Giant Pirate Crew","specialText":"Reduces crew''s current HP by 80%, reduces Special Cooldown of Powerhouse and Slasher characters by 3 turns, reduces enemies'' Barrier duration by 3 turns, and reduces damage received by 90% for 1 turn. If your crew has 4+ [Giant], [Straw Hat Pirates] or [Four Emperors] characters, boosts Crew Damage Reduction to ATK of Powerhouse characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn; boosts Crew Damage Reduction to ATK of Powerhouse characters by 1x-1.5x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn otherwise. If Special Counter of this character is 1, activates HP Guard of 90% effect for 1 turn, changes the orbs, including [BLOCK] orbs, of this and adjacent characters into Matching orbs, and boosts Chain Multiplier Growth Rate by 1.5x for 1 turn. If your Captain is a Powerhouse or Slasher character, becomes Dorry & Broggy for 1 turn, and ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 1.75x for 1 turn.","specialNotes":null,"superSpecialText":"Sets Special Counter of this character to 1, reduces enemies'' Damage Nullification duration by 2 turns, changes the orbs of bottom row characters into [RCV] orbs, boosts ATK of Powerhouse characters by 2.25x for 3 turns, and transforms Powerhouse character into Super Powerhouse characters.","superSpecialCriteriaText":"This character must be captain. When this character becomes Dorry & Broggy and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Nefeltari Vivi, Karoo, Oimo, Kashii, Shanks","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. When this character becomes Dorry & Broggy and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Monkey D. Luffy, Roronoa Zoro, Nami, Usopp, Sanji, Tony Tony Chopper, Nico Robin, Franky, Brook, Jinbe, Nefeltari Vivi, Karoo, Oimo, Kashii, Shanks","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Roronoa Zoro","acceptedKeys":["roronoa zoro","zoro"]},{"label":"Nami","acceptedKeys":["nami"]},{"label":"Usopp","acceptedKeys":["usopp"]},{"label":"Sanji","acceptedKeys":["sanji"]},{"label":"Tony Tony Chopper","acceptedKeys":["tony tony chopper","chopper"]},{"label":"Nico Robin","acceptedKeys":["nico robin","robin"]},{"label":"Franky","acceptedKeys":["franky"]},{"label":"Brook","acceptedKeys":["brook"]},{"label":"Jinbe","acceptedKeys":["jinbe"]},{"label":"Nefeltari Vivi","a