      INSERT INTO character_details (character_id, detail_json)
      VALUES (4438, '{"characterId":4438,"captainAbility":"Boosts ATK of Powerhouse and Striker characters by 3.5x, and boosts HP of Powerhouse and Striker characters by 1.3x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Powerhouse and Striker characters by 3.5x, and boosts HP of Powerhouse and Striker characters by 1.3x."}],"captainNotes":null,"specialName":"Pulverizing Strike","specialText":"If HP is below 30% when the special is activated, reduces Bind duration by 6 turns, and reduces ATK Down duration by 3 turns; reduces Bind duration by 3 turns otherwise. If your crew has 3+ [Giant] characters, boosts Orb Effects of Powerhouse and Striker characters by 2.25x for 1 turn; boosts Orb Effects of Powerhouse and Striker characters by 1.75x for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["oimo"],"characterTags":["Giant Pirate Crew","Giant","Egghead Arc"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_atk_down","label":"Remove ATK Down","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_bind","label":"Remove Bind","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"support_status_effect_recovery_bind","label":"Status Effect Recovery: Bind","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"},{"key":"support_reduce_current_hp_crew","label":"Reduce Current HP (Crew)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"sou