      INSERT INTO character_details (character_id, detail_json)
      VALUES (4439, '{"characterId":4439,"captainAbility":"Reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of Cerebral, Shooter and Free Spirit characters by 4.25x, boosts HP of Cerebral, Shooter and Free Spirit characters by 1.3x, and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn. If your crew has 4+ [Straw Hat Pirates] characters, reduces Despair duration by 2 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of Cerebral, Shooter and Free Spirit characters by 4.25x, boosts HP of Cerebral, Shooter and Free Spirit characters by 1.3x, and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn. If your crew has 4+ [Straw Hat Pirates] characters, reduces Despair duration by 2 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of Cerebral, Shooter and Free Spirit characters by 4x, boosts HP of Cerebral, Shooter and Free Spirit characters by 1.3x, boosts ATK against delayed enemies by 1.2x, and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn. If your crew has 4+ [Straw Hat Pirates] characters, reduces Despair duration by 2 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of Cerebral, Shooter and Free Spirit characters by 4.25x, boosts HP of Cerebral, Shooter and Free Spirit characters by 1.3x, boosts ATK against delayed enemies by 1.2x, and has a chance to ignore Debuff Protection and delays all enemies by 1 turn based on damage dealt in previous turn. At the beginning of each Stage, increases the Attack Timer of all enemies by 1 turn. If your crew has 4+ [Straw Hat Pirates] characters, reduces Despair duration by 2 turns, and boosts base ATK of [Straw Hat Pirates] characters by 400."}],"captainNotes":"Delay chance is based on damage dealt with normal attacks and does not stack with any other delay specials or effects. Base Chances. 100,000 damage or more: 20% chance to delay. 1,000,000 damage or more: 50% chance to delay. 3,000,000 damage or more: 100% chance to delay. 5,000,000 damage or more: 100% chance to delay ignoring Debuff Protection","specialName":"Unexpected Joyful Reunion","specialText":"Paralyzes (75%) all enemies for 5 turns, delays all enemies by 2 turns, reduces Paralysis and Special Bind duration by 6 turns, boosts the Color Affinity of Cerebral and Shooter characters by 2.5x-3x for 1 turn depending on the number of [Straw Hat Pirates] characters on your crew, and becomes Nami & Usopp for 3 turns. If your crew has Delay Status ATK Boost when the special is activated, increases boost effects of Delay Status ATK Boost buffs by +0.5x.","specialNotes":". Base: 0-1: 2.5x, 2: 2.6x, 3: 2.7x, 4: 2.8x, 5: 2.9x, 6: 3x. LLB: 0-1: 2.5x, 2: 2.7x, 3: 2.9x, 4: 3.1x, 5: 3.3x, 6: 3.5x","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["nami & usopp","nami","usopp"],"characterTags":["Straw Hat Pirates","Egghead Arc"],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":6,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_delay","label":"Delay","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"apply_delay","label":"Delay","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_crew","label":"HP Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_barrier_pierce","label":"Barrier Pierce","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"}],"sailorAbilities":["Makes [TND] orbs beneficial for all characters.. Boosts base ATK and HP of all characters by 50.. Boosts base ATK and HP of all characters by 75."],"sailorNotes":null,"potentialAbilities":[{"Name":"Barrier Penetration","description":["This character''s normal attack will ignore barriers"]},{"Name":"No Healing","description":["Reduces No Healing duration by 7 turns"]},{"Name":"Slot Bind","description":["Reduces Slot Bind duration completely on this character"]}],"supportData":[],"swapData":{"base":"Changes the orb of this character into a Matching orb, removes Special Bind duration completely on this character, reduces Bind and Despair duration by 1 turn, and boosts ATK against delayed enemies by 1.5x for 1 turn.","super":"Changes the orbs, including [BLOCK] orbs, of this and adjacent characters into Matching orbs, removes Special Bind duration completely on this character, reduces Bind and Despair duration by 3 turns, and boosts ATK against delayed enemies by 2.25x for 1 turn.","superTurns":4},"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4439,"ability":[{"effects":[{"attributes":["HP"],"effect":"buff","level":6,"targeting":{"targets":["Cerebral"]}},{"attributes":["Critical Hit"],"effect":"buff","level":7,"targeting":{"targets":["Cerebral"]}},{"attributes":["DEF"],"effect":"buff","level":4,"targeting":{"targets":["[STR]","[PSY]"]}},{"attributes":["DEF"],"effect":"debuff","level":6,"targeting":{"targets":["enemies"]},"condition":{"type":"crew","composition":true,"comparator":"more","count":5,"targets":["Cerebral"]}}]}],"llbability":[{"effects":[{"attributes":["HP"],"effect":"buff","level":7,"targeting":{"targets":["Cerebral"]}},{"attributes":["Critical Hit"],"effect":"buff","level":8,"targeting":{"targets":["Cerebral"]}},{"attributes":["DEF"],"effect":"buff","level":5,"targeting":{"targets":["[STR]","[PSY]"]}},{"attributes":["DEF"],"effect":"debuff","level":7,"targeting":{"targets":["enemies"]},"condition":{"type":"crew","composition":true,"comparator":"more","count":5,"targets":["Cerebral"]}}]}],"special":[{"cooldown":32,"effects":[{"amount":3,"effect":"damage","type":"atk","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Paralysis"],"chance":90,"duration":20,"effect":"hinderance","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Critical Hit"],"level":8,"duration":30,"effect":"buff","targeting":{"targets":["Cerebral"]}}]}],"llbspecial":[{"cooldown":32,"effects":[{"amount":3.5,"effect":"damage","type":"atk","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Paralysis"],"chance":100,"duration":20,"effect":"hinderance","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Special CT"],"amount":20,"effect":"hinderance","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Critical Hit"],"level":9,"duration":30,"effect":"buff","targeting":{"targets":["Cerebral"]}}]}],"resilience":[{"attribute":"Paralysis","chance":100,"type":"debuff"},{"attribute":"Free Spirit","percentage":30,"type":"damage"}],"llbresilience":[{"attribute":"Paralysis","chance":100,"type":"debuff"},{"attribute":"Free Spirit","percentage":40,"type":"damage"}],"gpability":[{"effects":[{"attributes":["ATK"],"level":3,"effect":"buff","targeting":{"targets":["crew"]}},{"attributes":["HP","SPD"],"level":3,"effect":"buff","targeting":{"targets":["crew"]}}]}],"gpspecial":[{"uses":2,"effects":[{"amount":1000,"effect":"damage","type":"fixed","targeting":{"targets":["enemies"]}}]}],"gpcondition":[{"type":"defeat","team":"crew","count":2}],"pattern":[{"type":"Normal","action":"attack"},{"level":2,"area":"Self","action":"heal"},{"type":"Power","action":"attack"},{"type":"Power","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"DBF","def":185,"spd":186},"cost":55}}');


