      INSERT INTO character_details (character_id, detail_json)
      VALUES (4440, '{"characterId":4440,"captainAbility":"Reduces Special Cooldown of [Five Elders] and [Celestial Dragon] characters by 15 turns at the start of the fight, boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.1x, boosts ATK of [DEX], Driven and Powerhouse characters by 6x, by 6.6x instead if they have the applicable tag, boosts HP of [Five Elders], [Celestial Dragon] and [Navy] characters by 2x, and makes [DEX] and [RCV] orbs beneficial for all characters. If your crew has Orb Amplification and uses a special with an Orb Amplification buff, increases boost effects of Orb Amplification buffs by +?x, equal to the value of the special. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.3x instead, and boosts ATK of [DEX], Driven and Powerhouse characters by 7.8x instead if they have the applicable tag. If your crew has 4+ [Five Elders], [Celestial Dragon] or [Navy] characters and your crew has Orb Amplification buff with an effect of 10x or more, makes this character''s normal attacks count as Type Effective against all Types.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [Five Elders] and [Celestial Dragon] characters by 15 turns at the start of the fight, boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.1x, boosts ATK of [DEX], Driven and Powerhouse characters by 6x, by 6.6x instead if they have the applicable tag, boosts HP of [Five Elders], [Celestial Dragon] and [Navy] characters by 2x, and makes [DEX] and [RCV] orbs beneficial for all characters. If your crew has Orb Amplification and uses a special with an Orb Amplification buff, increases boost effects of Orb Amplification buffs by +?x, equal to the value of the special. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.3x instead, and boosts ATK of [DEX], Driven and Powerhouse characters by 7.8x instead if they have the applicable tag. If your crew has 4+ [Five Elders], [Celestial Dragon] or [Navy] characters and your crew has Orb Amplification buff with an effect of 10x or more, makes this character''s normal attacks count as Type Effective against all Types."}],"captainNotes":null,"specialName":"Slamming Charge of the War God","specialText":"Deals 10% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies, and removes enemies'' Threshold Damage Reduction duration completely. If a [DEX] character is supporting this character, applies Territory: Driven to the field for 3 turns; applies Territory: Powerhouse to the field for 3 turns otherwise. Boosts Orb Effects of Driven and Powerhouse characters by 4x-5x for 1 turn depending on the total Cost of crew, including Friend Captain and Supports, at the start of the fight. Increases boost effects of ATK Up buffs by 1.1x-1.5x (up to 15x) depending on the outcome of Action Special. If your crew has 4+ [Five Elders], [Celestial Dragon] or [Navy] characters, allows HP Overfill up to 2x MAX HP for 1 turn.","specialNotes":". Orb Amplification: 499-: 4x, 500-599: 4.25x, 600-699: 4.5x, 700-749: 4.75x, 750+: 5x. ATK Up: MISS: 1.1x, GOOD: 1.2x, GREAT: 1.3x, PERFECT: 1.4x, EXCELLENT 1.5x","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["st. shepherd ju peter","peter"],"characterTags":["World Government","Celestial Dragon","Five Elders","Egghead Arc"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"ignore_normal_attack_only","label":"Ignore Normal Attack Only (NAO)","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage","label":"Percent Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"percent_damage_ignore_defensive_effects","label":"Percent Damage: Ignore Defensive Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"territory","label":"Territory","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_driven","label":"ATK Boost: Driven","minTurns":null,"isCompleteRemoval":false,"slotTokens"