      INSERT INTO character_details (character_id, detail_json)
      VALUES (4450, '{"characterId":4450,"captainAbility":"Reduces Special Cooldown of [Five Elders] and [Celestial Dragon] characters by 15 turns at the start of the fight, boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.1x, boosts ATK of [QCK], Driven and Powerhouse characters by 6x, by 6.6x instead if they have the applicable tag, boosts HP of [Five Elders], [Celestial Dragon] and [Navy] characters by 2x, and makes [QCK] and [RCV] orbs beneficial for all characters. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.3x instead, and boosts ATK of [QCK], Driven and Powerhouse characters by 7.8x instead if they have the applicable tag. If your crew has Color Affinity and uses a special with a Color Affinity buff, increases boost effects of Color Affinity buffs by +?x, equal to the value of the special. If your crew has 5+ [Five Elders], [Celestial Dragon] or [Navy] characters and there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, increases enemies'' Damage Limiter limit up to 1.3x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [Five Elders] and [Celestial Dragon] characters by 15 turns at the start of the fight, boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.1x, boosts ATK of [QCK], Driven and Powerhouse characters by 6x, by 6.6x instead if they have the applicable tag, boosts HP of [Five Elders], [Celestial Dragon] and [Navy] characters by 2x, and makes [QCK] and [RCV] orbs beneficial for all characters. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of [Five Elders], [Celestial Dragon] and [Navy] characters by 1.3x instead, and boosts ATK of [QCK], Driven and Powerhouse characters by 7.8x instead if they have the applicable tag. If your crew has Color Affinity and uses a special with a Color Affinity buff, increases boost effects of Color Affinity buffs by +?x, equal to the value of the special. If your crew has 5+ [Five Elders], [Celestial Dragon] or [Navy] characters and there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, increases enemies'' Damage Limiter limit up to 1.3x."}],"captainNotes":null,"specialName":"Shredding Rampage of the War God","specialText":"Deals 250x character''s ATK in Typeless Fixed True damage to one enemy, and reduces Bind duration by 20 turns. Boosts the Color Affinity of Driven and Powerhouse characters by 4x-5x for 1 turn depending on the total Cost of crew, including Friend Captain and Supports, at the start of the fight. Increases boost effects of Delay Status ATK Boost buffs by 1.1x-1.5x (up to 10x) depending on the outcome of Action Special. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 1.75x for 2 turns.","specialNotes":". Color Affinity: 499-: 4x, 500-599: 4.25x, 600-699: 4.5x, 700-749: 4.75x, 750+: 5x. Delay Status ATK Boost: MISS: 1.1x, GOOD: 1.2x, GREAT: 1.3x, PERFECT: 1.4x, EXCELLENT 1.5x","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["st. topman warcury","warcury"],"characterTags":["World Government","Celestial Dragon","Five Elders","Egghead Arc"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":20,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurn