      INSERT INTO character_details (character_id, detail_json)
      VALUES (4458, '{"characterId":4458,"captainAbility":"Boosts ATK of Driven and Powerhouse characters by 4x, boosts HP of Driven and Powerhouse characters by 1.75x, reduces RCV of all characters by 50%, increases damage received by 1.5x, reduces chances of getting [RCV] orbs, and deals 10% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies at the start of every stage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with the following effect: boosts ATK of Driven and Powerhouse characters by 2.25x for 1 turn.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of Driven and Powerhouse characters by 4x, boosts HP of Driven and Powerhouse characters by 1.75x, reduces RCV of all characters by 50%, increases damage received by 1.5x, reduces chances of getting [RCV] orbs, and deals 10% of enemies'' current HP in True damage, ignoring Normal Attack Only, to all enemies at the start of every stage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with the following effect: boosts ATK of Driven and Powerhouse characters by 2.25x for 1 turn."},{"key":"character2","label":"Captain Ability (Character 2)","text":"oosts ATK of Driven and Powerhouse characters by 4.25x, boosts HP of Driven and Powerhouse characters by 1.75x, reduces RCV of all characters by 50%, increases damage received by 1.5x, reduces chances of getting [RCV] orbs, and reduces Special Cooldown of this character by 2 turns and reduces Switch Effect of this character by 2 after each turn you take damage. If a crew member uses a special with a Percent Damage Reduction, Threshold Damage Reduction or Damage Nullification buff, replaces those buffs with the following effect: boosts ATK of Driven and Powerhouse characters by 2.25x for 1 turn."