      INSERT INTO character_details (character_id, detail_json)
      VALUES (4460, '{"characterId":4460,"captainAbility":"Reduces Special Cooldown of [INT], Powerhouse and Shooter characters by 2 turns at the start of the fight, reduces VS Gauge of [INT], Powerhouse and Shooter characters by 2 at the start of the fight, boosts ATK of [INT], Powerhouse and Shooter characters by 5.25x, boosts HP of [INT], Powerhouse and Shooter characters by 1.3x, makes [INT] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. Up to 2 times per adventure, when Marshall D. Teach (Blackbeard), Jesus Burgess (Mr. Store), Shiryu, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, or Kuzan (Aokiji) uses a special as crewmate, boosts Chain Multiplier Growth Rate by 1.5x for 2 turns. If your crew has 3+ [Blackbeard Pirates] characters, boosts ATK of [Blackbeard Pirates] characters by 1.1x, by 5.775x instead if they are an [INT], Powerhouse or Shooter character, and increases boost effects of Color Affinity buffs applied by specials by +0.3x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [INT], Powerhouse and Shooter characters by 2 turns at the start of the fight, reduces VS Gauge of [INT], Powerhouse and Shooter characters by 2 at the start of the fight, boosts ATK of [INT], Powerhouse and Shooter characters by 5.25x, boosts HP of [INT], Powerhouse and Shooter characters by 1.3x, makes [INT] and [TND] orbs beneficial for all characters, and restores Special Cooldown of all characters by 10 turns when they are rewinded. Up to 2 times per adventure, when Marshall D. Teach (Blackbeard), Jesus Burgess (Mr. Store), Shiryu, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, or Kuzan (Aokiji) uses a special as crewmate, boosts Chain Multiplier Growth Rate by 1.5x for 2 turns. If your crew has 3+ [Blackbeard Pirates] characters, boosts ATK of [Blackbeard Pirates] characters by 1.1x, by 5.775x instead if they are an [INT], Powerhouse or Shooter character, and increases boost effects of Color Affinity buffs applied by specials by +0.3x."}],"captainNotes":null,"specialName":"Sniping Down the Commodore''s Enemies","specialText":"Reduces Special Cooldown of Powerhouse and Shooter characters by 2 turns, reduces Chain Multiplier Limit duration by 7 turns, and sets Chain Boundaries to 3.0x and 40.0x for 3 turns. If HP is below 50% when the special is activated or your crew has 3+ [Blackbeard Pirates] characters, boosts Advantageous Class Effect of Powerhouse and Shooter characters by 1.75x for 3 turns. If your crew has 3+ [Blackbeard Pirates] characters, swaps bottom-left character with your captain for 3 turns. If your crew has 2- [Blackbeard Pirates] characters and this character is a crewmate, swaps this unit with your captain for 1 turn.","specialNotes":null,"superSpecialText":"Optionally removes Captain Swap duration completely, changes the orb, including [BLOCK] orb, of this character into a [TND] orb, reduces enemies'' Powerhouse and Shooter Resistance by -25% for 1 turn, increases boost effects of ATK Up buffs applied by Powerhouse and Shooter characters by +0.3x for 1 turn, reduces enemies'' Barrier duration by 2 turns, ignores Debuff Protection and reduces the defense of all enemies by 100% for 2 turns, and transforms Powerhouse characters into Super Powerhouse characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Marshall D. Teach (Blackbeard), Jesus Burgess (Mr. Store), Shiryu, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, Kuzan (Aokiji)","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Marshall D. Teach (Blackbeard), Jesus Burgess (Mr. Store), Shiryu, Avalo P