      INSERT INTO character_details (character_id, detail_json)
      VALUES (4475, '{"characterId":4475,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of all characters by 4.25x, boosts HP of all characters by 1.25x, makes [PSY] orbs beneficial for all characters, and recovers 0.5x this character''s RCV at the end of the turn for each time you hit a PERFECT.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 1 turn at the start of the fight, boosts ATK of all characters by 4.25x, boosts HP of all characters by 1.25x, makes [PSY] orbs beneficial for all characters, and recovers 0.5x this character''s RCV at the end of the turn for each time you hit a PERFECT."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 1 turn and reduces Switch Effect of all characters by 1 at the start of the fight, boosts ATK of all characters by 4.5x, boosts HP of all characters by 1.25x, and makes [INT] orbs beneficial for all characters."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 1 turn and reduces Switch Effect of all characters by 1 at the start of the fight, boosts ATK of all characters by 5x, boosts HP of all characters by 1.25x, makes [PSY] and [INT] orbs beneficial for all characters, and recovers 1.5x this character''s RCV at the end of the turn for each time you hit a PERFECT. If this character has a [DEX] or [QCK] orb and you attack with this character, inflicts all enemies with Increase Damage Taken by 1.5x for 1 turn."}],"captainNotes":null,"specialName":"The Worst Plan to Overthrow a God","specialText":"Deals 400x character''s ATK in Typeless damage to one enemy, reduces Paralysis duration by 6 turns, makes [STR], [DEX] and [QCK] orbs beneficial for all characters for 1 turn, boosts Orb Effects of all characters by 3x for 1 turn, and becomes Luffy & Law for 3