      INSERT INTO character_details (character_id, detail_json)
      VALUES (4476, '{"characterId":4476,"captainAbility":"Launches the following effect at start of fight: if there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Special Cooldown of Slasher and Striker characters by 5 turns, reduces Switch Effect of Slasher and Striker characters by 3, and increases Chain Tap Timing Bonus of [STR] and [PSY] characters to +0.2x-0.7x for 10 turns depending on Tap Timing. Boosts ATK of Slasher and Striker characters by 5x, boosts HP of Slasher and Striker characters by 1.3x, makes [STR] and [PSY] orbs beneficial for Slasher and Striker characters, and reduces Special Bind duration by 10 turns on this character. If your crew has 3+ [Land of Wano Arc] characters, boosts ATK of Slasher and Striker characters by 5.5x instead. If your crew has 5+ [Kozuki Clan], [Land of Wano Arc] or [Mythical Zoan-type] characters and a character performs a Critical Hit, reduces enemies'' Increased Defense duration by 2 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effect at start of fight: if there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Special Cooldown of Slasher and Striker characters by 5 turns, reduces Switch Effect of Slasher and Striker characters by 3, and increases Chain Tap Timing Bonus of [STR] and [PSY] characters to +0.2x-0.7x for 10 turns depending on Tap Timing. Boosts ATK of Slasher and Striker characters by 5x, boosts HP of Slasher and Striker characters by 1.3x, makes [STR] and [PSY] orbs beneficial for Slasher and Striker characters, and reduces Special Bind duration by 10 turns on this character. If your crew has 3+ [Land of Wano Arc] characters, boosts ATK of Slasher and Striker characters by 5.5x instead. If your crew has 5+ [Kozuki Clan], [Land of Wano Arc] or [Mythical Zoan-type] characters and a character performs a Critical Hit, reduces enemies'' Increased Defense duration by 2 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of Slasher characters by 2 turns, reduces Switch Effect of Slasher characters by 2, and increases Chain Tap Timing Bonus of [STR] and [PSY] characters to +0.2x-0.6x for 5 turns depending on Tap Timing. Boosts ATK of Slasher and Striker characters by 5x, boosts HP of Slasher and Striker characters by 1.3x, makes [STR] and [PSY] orbs beneficial for Slasher and Striker characters, and reduces Special Bind duration by 10 turns on this character. If your crew has 3+ [Land of Wano Arc] characters, boosts ATK of Slasher and Striker characters by 5.5x instead. If your crew has 5+ [Kozuki Clan], [Land of Wano Arc] or [Mythical Zoan-type] characters and a character performs a Critical Hit, reduces enemies'' Increased Defense duration by 2 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of Slasher and Striker characters by 5.5x, boosts HP of Slasher and Striker characters by 1.3x, makes [STR] and [PSY] orbs beneficial for Slasher and Striker characters, and reduces Special Bind duration by 10 turns on this character. If your crew has 3+ [Land of Wano Arc] characters, boosts ATK of Slasher and Striker characters by 6.05x instead. If your crew has 5+ [Kozuki Clan], [Land of Wano Arc] or [Mythical Zoan-type] characters and a character performs a Critical Hit, reduces enemies'' Increased Defense duration by 2 turns, and reduces enemies'' Slasher and Striker Resistance by -4% for 1 turn."}],"captainNotes":". Yamato: GOOD +0.2, GREAT +0.4, PERFECT +0.7. Momonosuke: GOOD +0.2, GREAT +0.4, PERFECT +0.6","specialName":"Honing Skills of Their Blade","specialText":"Reduces Despair and Special Bind duration by 7 turns, boosts Orb Effects of Slasher and Striker characters by 3x for 2 turns, and becomes Yamato & Momonosuke for 3 turns. If your crew has Orb Amplification when the special is activated, boosts the Color Affinity of Slasher and Striker characters by 2.75x for 2 turns. If your crew has 5+ [Kozuki Clan], [Land of Wano Arc] or [Mythical Zoan-type] characters, increases boost effects of ATK Up and Orb Amplification buffs by 1.2x (up to 7x), including effects activated in the same ability, and applies Territory: Slasher to the field for 2 turns.","specialNotes":null,"superSpecialText":"Optionally removes Captain Swap duration completely, reduces enemies'' Percent Damage Reduction effect by 50%, increases boost effects of Chain Multiplication buffs to 1.6x, transforms [STR] characters into Super [STR] characters, and transforms [PSY] characters into Super [PSY] characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Kozuki Oden, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kin''emon, Izo, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Denjiro (Kyoshiro), Shinobu, Otama, Monkey D. Luffy, Trafalgar Law, Eustass Kid","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Kozuki Oden, Kozuki Hiyori (Komurasaki), Kozuki Toki, Kozuki Sukiyaki (Tenguyama Hitetsu), Kin''emon, Izo, Raizo, Okiku, Ashura Doji (Shutenmaru), Dogstorm, Cat Viper, Kawamatsu, Denjiro (Kyoshiro), Shinobu, Otama, Monkey D. Luffy, Trafalgar Law, Eustass Kid","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Kozuki Oden","acceptedKeys":["kozuki oden","oden"]},{"label":"Kozuki Hiyori (Komurasaki)","acceptedKeys":["kozuki hiyori komurasaki","kozuki hiyori","komurasaki","hiyori"]},{"label":"Kozuki Toki","acceptedKe