      INSERT INTO character_details (character_id, detail_json)
      VALUES (4478, '{"characterId":4478,"captainAbility":"Boosts ATK of Slasher and Powerhouse characters by 3.5x, boosts HP of all characters by 1.35x, reduces Bind, Despair, Paralysis and Special Bind duration completely on this character, and restores Special Cooldown of this character completely when it is rewinded. If this character becomes your captain in the middle of an island, boosts ATK of Slasher and Powerhouse characters by 5.25x, and boosts ATK of all other characters 1.5x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Slasher and Powerhouse characters by 3.5x, boosts HP of all characters by 1.35x, reduces Bind, Despair, Paralysis and Special Bind duration completely on this character, and restores Special Cooldown of this character completely when it is rewinded. If this character becomes your captain in the middle of an island, boosts ATK of Slasher and Powerhouse characters by 5.25x, and boosts ATK of all other characters 1.5x."}],"captainNotes":null,"specialName":"Imperial Deep Pride Stake","specialText":"Reduces Special Cooldown of all characters by 2 turns, and reduces enemies'' Resilience duration by 6 turns. If your crew has 5+ [Land of Wano Arc] or [Animal Kingdom Pirates] characters, boosts Orb Effects of Slasher and Powerhouse characters by 2.25x, allowing override, for 1 turn, boosts Base ATK of Slasher and Powerhouse characters by 1,000, allowing override, for 1 turn, and boosts Chain Multiplier Growth Rate by 1.25x for 1 turn; boosts Orb Effects of Slasher and Powerhouse characters by 2.25x for 1 turn and boosts Base ATK of Slasher and Powerhouse characters by 1,000 for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["king"],"characterTags":["Animal Kingdom Pirates","Lead Performer","Ancient Zoan-type","Land of Wano Arc"],"builderAbilities":[{"key":"remove_resilience","label