on by 1 turn."]}],"swapData":null,"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4481,"ability":[{"effects":[{"attributes":["ATK","RCV","SPD"],"effect":"buff","level":5,"targeting":{"targets":["Striker","Slasher"]}},{"attributes":["DEF"],"effect":"debuff","level":3,"targeting":{"targets":["[Four Emperors]"]}},{"attributes":["HP"],"effect":"buff","level":6,"targeting":{"targets":["self"]},"condition":{"type":"mode","mode":"Assault Rumble"}},{"attributes":["Special CT"],"effect":"buff","level":3,"targeting":{"targets":["self"]},"condition":{"type":"mode","mode":"Assault Rumble"}}]}],"special":[{"cooldown":30,"effects":[{"attributes":["ATK"],"effect":"buff","level":5,"duration":20,"targeting":{"targets":["self"]}},{"attributes":["DEF"],"effect":"buff","level":5,"duration":20,"targeting":{"targets":["Striker","Slasher"]}},{"amount":3,"effect":"damage","type":"atk","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"sideways"}},{"attributes":["Action Bind"],"effect":"hinderance","chance":100,"duration":10,"targeting":{"targets":["[Four Emperors]"]}},{"amount":5,"effect":"damage","type":"atk","targeting":{"targets":["[Four Emperors]"]}},{"amount":2.5,"effect":"damage","type":"atk","defbypass":true,"targeting":{"targets":["enemies"],"families":["Charlotte Linlin (Big Mom)"]},"condition":{"type":"mode","mode":"Assault Rumble"}}]}],"resilience":[{"attribute":"Special Bind","chance":80,"type":"debuff"},{"attribute":"[DEX]","percentage":20,"type":"damage"}],"pattern":[{"type":"Normal","action":"attack"},{"type":"Normal","action":"attack"},{"type":"Power","action":"attack"},{"type":"Full","action":"attack"}],"target":{"criteria":"near"},"stats":{"rumbleType":"ATK","def":178,"spd":178},"cost":20}}');


