      INSERT INTO character_details (character_id, detail_json)
      VALUES (4482, '{"characterId":4482,"captainAbility":"Boosts ATK of Cerebral and Driven characters by 5x, boosts Cerebral and Driven characters ATK against enemies inflicted with Burn, paralyzed enemies and poisoned enemies by 1.25x, boosts HP and RCV of all characters by 1.3x, makes [QCK] and [TND] orbs beneficial for all characters, allows effects that inflict Poison to ignore Debuff Protection, and allows HP Overfill up to 2x MAX.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of Cerebral and Driven characters by 5x, boosts Cerebral and Driven characters ATK against enemies inflicted with Burn, paralyzed enemies and poisoned enemies by 1.25x, boosts HP and RCV of all characters by 1.3x, makes [QCK] and [TND] orbs beneficial for all characters, allows effects that inflict Poison to ignore Debuff Protection, and allows HP Overfill up to 2x MAX."}],"captainNotes":null,"specialName":"Science Power of Land of the Dead","specialText":"If your crew has 3+ [Scientist] characters, allows crew to stack 2 different Status ATK Boost buffs for 1 turn. If your crew is inflicted with Poison or Toxic when the special is activated, inflicts Toxic to all enemies, boosts ATK against enemies inflicted with Toxic by 2.75x for 1 turn, and removes Poison duration completely. If your crew is inflicted with Paralysis when the special is activated, ignores Debuff Protection and paralyzes (50%) all enemies for 1 turn, boosts ATK against paralyzed enemies by 2.75x for 1 turn, and reduces Paralysis duration by 10 turns. If your crew is inflicted with Burn when the special is activated, ignores Debuff Protection and inflicts all enemies with Burn that will deal 100x enemies'' ATK in damage for 1 turn, boosts ATK against enemies inflicted with Burn by 2.75x for 1 turn, and reduces Burn duration by 10 turns.","specialNotes":"Toxic starts at 50x character''s attack and increases by 2x at the end of every turn until 3,000,000 damage per turn.","super