      INSERT INTO character_details (character_id, detail_json)
      VALUES (4483, '{"characterId":4483,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of all characters by 4x, boosts ATK against delayed enemies, enemies with reduced defense, enemies inflicted with Increase Damage Taken, paralyzed enemies and enemies inflicted with Burn by 1.05x-1.276x, by a multiplicative 1.05x for each status effect, boosts HP of all characters by 1.3x, and makes [PSY] and [RCV] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Maximum-Chain ATK Down duration by 5 turns, and reduces Special Bind duration by 10 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of all characters by 4x, boosts ATK against delayed enemies, enemies with reduced defense, enemies inflicted with Increase Damage Taken, paralyzed enemies and enemies inflicted with Burn by 1.05x-1.276x, by a multiplicative 1.05x for each status effect, boosts HP of all characters by 1.3x, and makes [PSY] and [RCV] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Maximum-Chain ATK Down duration by 5 turns, and reduces Special Bind duration by 10 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of all characters by 4x, boosts ATK against poisoned enemies by 1.25x, boosts HP of all characters by 1.3x, and makes [INT] and [TND] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Maximum-Chain ATK Down duration by 5 turns, and reduces Special Bind duration by 10 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 3 at the start of the fight, boosts ATK of all characters by 4x, boosts ATK against poisoned enemies by 1.25x, boosts ATK against delayed enemies, enemies with reduced defense, enemies inflicted with Increase Damage Taken, paralyzed enemies and enemies inflicted with Burn by 1.05x-1.276x, by a multiplicative 1.05x for each status effect, boosts HP of all characters by 1.3x, and makes [PSY], [INT], [RCV] and [TND] orbs beneficial for all characters. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew, reduces Maximum-Chain ATK Down duration by 5 turns, and reduces Special Bind duration by 10 turns."}],"captainNotes":null,"specialName":"A Mother''s Hard-Won Kind Hearts","specialText":"Reduces Bind duration by 7 turns, reduces enemies'' Damage Nullification duration by 2 turns, and becomes Sanji & Reiju for 3 turns. If your crew has Orb Amplification when the special is activated, increases boost effects of Orb Amplification buffs by 1.5x (up to 8x); boosts Orb Effects of all characters by 3.25x for 1 turn otherwise. If there is a [STR], [DEX], [QCK], [PSY] and [INT] character in your crew or your crew has 3+ [Germa 66] or [Royalty] characters, changes all orbs, including [BLOCK] orbs, into [RCV] orbs, and boosts Crew Damage Reduction to ATK of all characters by 1x-2.5x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. If your crew has 4+ [Straw Hat Pirates] characters, inflicts all enemies with Weaken by 1.5x, by 1.875x instead if enemies are inflicted with Increase Damage Taken, for 1 turn.","specialNotes":null,"superSpecialText":"allows all characters to perform Super Tandem with [RCV] and [RAINBOW] orbs for 1 turn, enables ATK Up buffs to be enhanced up to 2 times, increases boost effects of ATK Up buffs by +0.5x, removes enemies'' Poison duration completely, inflicts all enemies with Reiju Poison, and transforms Powerhouse characters into Super Powerhouse characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Straw Hat Pirates], [Germa 66], [Royalty] characters","superSpecialNotes":"Reiju Poison deals 20% of enemies'' current HP in damage at the end of each turn and recovers 20% crew''s MAX HP at the end of each turn. Reiju Poison is derivative of Normal Poison, so it fulfills Poison Status ATK Boosts and is affected by Poison Debuff Immunity.","superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Straw Hat Pirates], [Germa 66], [Royalty] characters","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":4,"matchMode":"any_candidate","options":[{"label":"[Straw Hat Pirates]","acceptedKeys":["straw hat pirates","pirates"]},{"label":"[Germa 66]","acceptedKeys":["germa 66","66"]},{"label":"[Royalty] characters","acceptedKeys":["royalty"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["sanji & reiju","sanji","reiju"],"characterTags":["Straw Hat Pirates","Royalty","Whole Cake Island Arc","Germa 66"],"builderAbilities":[{"key":"remove_bind","label":"Remove Bind","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_enemy_damage_nullification","label":"Remove Damage Nullification","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":