      INSERT INTO character_details (character_id, detail_json)
      VALUES (4487, '{"characterId":4487,"captainAbility":"Reduces Special Cooldown of [STR], Cerebral and Free Spirit characters by 2 turns and reduces Switch Effect of [STR], Cerebral and Free Spirit characters by 2 at the start of the fight, boosts ATK of [STR], Cerebral and Free Spirit characters by 5.5x, by 6x instead if they have a [STR], [TND], [BOMB] or [SUPERBOMB] orb, boosts HP of [STR], Cerebral and Free Spirit characters by 1.2x, boosts chances of getting [DEX] orbs, changes [DEX] and [INT] orbs into [BOMB] orbs, makes [BOMB] and [SUPERBOMB] orbs beneficial for all characters, and [BOMB] and [SUPERBOMB] orbs will deal 100% less damage to the crew. If your crew has 3+ [Scientist] characters, boosts ATK of Cerebral characters by 6.05x, by 6.6x instead if they have a [STR], [TND], [BOMB] or [SUPERBOMB] orb; additionally, if this character has a [BOMB] or [SUPERBOMB] orb and you attack with this character, reduces enemies'' Damage Nullification duration by 2 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [STR], Cerebral and Free Spirit characters by 2 turns and reduces Switch Effect of [STR], Cerebral and Free Spirit characters by 2 at the start of the fight, boosts ATK of [STR], Cerebral and Free Spirit characters by 5.5x, by 6x instead if they have a [STR], [TND], [BOMB] or [SUPERBOMB] orb, boosts HP of [STR], Cerebral and Free Spirit characters by 1.2x, boosts chances of getting [DEX] orbs, changes [DEX] and [INT] orbs into [BOMB] orbs, makes [BOMB] and [SUPERBOMB] orbs beneficial for all characters, and [BOMB] and [SUPERBOMB] orbs will deal 100% less damage to the crew. If your crew has 3+ [Scientist] characters, boosts ATK of Cerebral characters by 6.05x, by 6.6x instead if they have a [STR], [TND], [BOMB] or [SUPERBOMB] orb; additionally, if this character has a [BOMB] or [SUPERBOMB] orb and you attack with this character, reduces enemies'' Damage Nullification duration by 2 turns."}],"captainNotes":null,"specialName":"Determined Strike","specialText":"Reduces Special Cooldown of Cerebral characters by 2 turns, reduces enemies'' Threshold Damage Reduction duration by 10 turns, and reduces damage received by 90% for 2 turns. If your crew has 3+ [Scientist] characters, allows you to select up to 2 of the following effects to launch; allows you to select up to 1 of the following effects to launch otherwise (launched effects will bypass special interrupts): Boosts ATK of Cerebral characters by 3.25x for 1 turn. Boosts Orb Effects of Cerebral characters by 3.25x for 1 turn. Boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. Boosts Base ATK of Cerebral characters by 1,750 for 1 turn. Adds 2.0x to chain multiplier for 1 turn.","specialNotes":null,"superSpecialText":"Reduces Special Cooldown of this character by 2 turns, and reduces Special Bind duration by 10 turns on this character. If your crew has ATK Up, decreases boost effects of ATK Up buffs by -0.5x, and converts ATK Up into a Stackable ATK Up. Transforms [STR] characters into Super [STR] characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: [Scientist] characters","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: [Scientist] characters","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"any_candidate","options":[{"label":"[Scientist] characters","acceptedKeys":["scientist"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["dr. vegapunk \"atlas the violent\"","violent\""],"characterTags":["Vegapunk","Scientist","Egghead Arc"],"builderAbilities"