      INSERT INTO character_details (character_id, detail_json)
      VALUES (4498, '{"characterId":4498,"captainAbility":"At the beginning of each stage, increases the Attack Timer of all enemies by 1 turn. Boosts ATK of Driven and Cerebral characters by 4.25x-6.12x, depending of if crew meets tag conditions, boosts HP of Driven and Cerebral characters by 1.3x, makes [STR], [RCV], [TND], [BOMB] and [SUPERBOMB] orbs beneficial for Driven and Cerebral characters, recovers 6,000 HP at the end of each turn, and restores Special Cooldown of this character by 10 turns when it is rewinded. If your crew has 2+ [Scientist] or [Seraphim] characters, boosts ATK of all characters by a further 1.2x. If your crew has 2+ [CP0] or [World Government] characters, boosts ATK of all characters a further 1.2x.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"At the beginning of each stage, increases the Attack Timer of all enemies by 1 turn. Boosts ATK of Driven and Cerebral characters by 4.25x-6.12x, depending of if crew meets tag conditions, boosts HP of Driven and Cerebral characters by 1.3x, makes [STR], [RCV], [TND], [BOMB] and [SUPERBOMB] orbs beneficial for Driven and Cerebral characters, recovers 6,000 HP at the end of each turn, and restores Special Cooldown of this character by 10 turns when it is rewinded. If your crew has 2+ [Scientist] or [Seraphim] characters, boosts ATK of all characters by a further 1.2x. If your crew has 2+ [CP0] or [World Government] characters, boosts ATK of all characters a further 1.2x."}],"captainNotes":null,"specialName":"Last Promise to Live","specialText":"Reduces Special Cooldown of all characters by 2 turns, reduces VS Gauge of all characters by 6, and reduces Bleed duration by 10 turns. If your crew is inflicted with Bleed, Poison or Toxic or your crew has Orb Multiplier Override buff when the special is activated, increases Chain Tap Timing Bonus of Driven and Cerebral characters to +0.3x-0.8x for 2 turns depending on Tap Timing; increases Chain Tap Timing Bonus of Driven and Cerebral characters to +0.2x-0.6x for 2 turns depending on Tap Timing otherwise. If your crew has 2+ [Scientist] or [Seraphim] characters and 2+ [CP0] or [World Government] characters, changes all orbs, including [BLOCK] orbs, into [SUPERBOMB] orbs, and increases Orb Effects of beneficial [RCV], [TND], [BOMB] and [SUPERBOMB] orbs to 3.5x for 3 turns. If your crew has 3+ [Scientist] or [Seraphim] characters, changes all orbs, including [BLOCK] orbs, into [BOMB] orbs, and increases Orb Effects of beneficial [BOMB] and [SUPERBOMB] orbs to 3.5x for 2 turns. If your crew has 3+ [CP0] or [World Government] characters, changes all orbs, including [BLOCK] orbs, into [RCV] orbs, and increases Orb Effects of beneficial [RCV] and [TND] orbs to 3.5x for 2 turns.","specialNotes":". GOOD: +0.3, GREAT: +0.5, PERFECT: +0.8. GOOD: +0.2, GREAT: +0.4, PERFECT: +0.6","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["stussy"],"characterTags":["Zoan-type","Egghead Arc"],"builderAbilities":[{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"change_block_slots","label":"Change [BLOCK] Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_cerebral","label":"ATK Boost: Cerebral","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],