      INSERT INTO character_details (character_id, detail_json)
      VALUES (4502, '{"characterId":4502,"captainAbility":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [STR], Slasher, Shooter and Striker characters by 5x, boosts HP of [STR], Slasher, Shooter and Striker characters by 1.2x, changes [DEX] and [BOMB] orbs of [STR], Slasher, Shooter and Striker characters into [WANO] orbs, and reduces damage received by 25%. If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, increases boost effects of Orb Amplification and Color Affinity buffs applied by specials by +0.3x.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [STR], Slasher, Shooter and Striker characters by 5x, boosts HP of [STR], Slasher, Shooter and Striker characters by 1.2x, changes [DEX] and [BOMB] orbs of [STR], Slasher, Shooter and Striker characters into [WANO] orbs, and reduces damage received by 25%. If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, increases boost effects of Orb Amplification and Color Affinity buffs applied by specials by +0.3x."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [DEX], Slasher, Shooter and Striker characters by 4.75x, by 5.25x instead if they have a beneficial orb, boosts HP of [DEX], Slasher, Shooter and Striker characters by 1.2x, and changes [STR] and [BOMB] orbs of [DEX], Slasher, Shooter and Striker characters into [WANO] orbs. If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, increases boost effects of Orb Amplification and Color Affinity buffs applied by specials by +0.3x."},{"key":"combined","label":"Captain Ability (Combined)","text":"Reduces Special Cooldown of all characters by 2 turns and reduces Switch Effect of all characters by 2 at the start of the fight, boosts ATK of [STR], [DEX], Slasher, Shooter and Striker characters by 5.25x, by 5.5x instead if they have a beneficial orb, boosts HP of [STR], [DEX], Slasher, Shooter and Striker characters by 1.2x, and changes [STR], [DEX] and [BOMB] orbs of [STR], [DEX], Slasher, Shooter and Striker characters into [WANO] orbs. Up to 1 time per adventure, when a Slasher or Shooter character uses a special, increases boost effects of Color Affinity and Status ATK Boost buffs by +0.5x, and boosts ATK against enemies with reduced defense by 2.25x for 3 turns. If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, increases boost effects of Orb Amplification and Color Affinity buffs applied by specials by +0.3x."}],"captainNotes":null,"specialName":"Red Flag and Roar of the Sea Onslaught","specialText":"Reduces Silence duration by 5 turns, reduces ATK Down duration by 7 turns, and becomes Drake & Apoo for 3 turns. If enemies are inflicted with Weaken when the special is activated, removes enemies'' Weaken duration completely, and recovers 5,000 HP at the end of the turn for 7 turns. If your crew has 7+ turns of End of Turn Healing, ignores Debuff Protection and inflicts all enemies with Weaken by 1.5x, by 2.25x instead if enemies are inflicted with Increase Damage Taken, for 1 turn. If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, ignores Debuff Protection and inflicts all enemies with Weaken by 1.5x, by 1.875x instead if enemies are inflicted with Increase Damage Taken, for 1 turn, boosts Base ATK of all characters by 1,000 for 1 turn, and increases boost effects of Base ATK Boost buffs by +750, including effects activated in the same ability; otherwise, inflicts all enemies with Weaken by 1.5x, by 1.875x instead if enemies are inflicted with Increase Damage Taken, for 1 turn. If a [DEX] character is supporting this character, reduces enemies'' damage received by 33% for 3 turns, reduces damage received by 90% for 1 turn, and boosts Crew Damage Reduction to ATK of all characters by 1x-1.6x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn.","specialNotes":null,"superSpecialText":"Inflicts all enemies with Set Target, increasing damage taken from Slasher, Shooter and Striker characters by 2.25x and reducing Special Cooldown of Slasher, Shooter and Striker characters by 2 turns when they defeat an enemy, for 2 turns, transforms Slasher characters into Super Slasher characters, and transforms Striker characters into Super Striker characters.","superSpecialCriteriaText":"This character must be captain. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Kaido, King (Alber), Queen, Jack, Ulti, Page One, Black Maria, Who''s-Who, Sasaki, Yamato, Coby, Helmeppo, Prince Grus, Kujaku, Hibari, [Worst Generation]","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Kaido, King (Alber), Queen, Jack, Ulti, Page One, Black Maria, Who''s-Who, Sasaki, Yamato, Coby, Helmeppo, Prince Grus, Kujaku, Hibari, [Worst Generation]","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Kaido","acceptedKeys":["kaido"]},{"label":"King (Alber)","acceptedKeys":["king alber","king","alber"]},{"label":"Queen","acceptedKeys":["queen"]},{"label":"Jack","acceptedKeys":["jack"]},{"label":"Ulti","acceptedKeys":["ulti"]},{"label":"Page One","acceptedKeys":["page one","one"]},{"label":"Black Maria","acceptedKeys":["black maria","maria"]},{"label":"Who''s-Who","acceptedKeys":["who s who"]},{"label":"Sasaki","acceptedKeys":["sasaki"]},{"label":"Yamato","acceptedKeys":["yamato"]},{"label":"Coby","acceptedKeys":["coby"]},{"label":"Helmeppo","acceptedKeys":["helmeppo"]},{"label":"Prince Grus","acceptedKeys":["prince grus","grus"]},{"label":"Kujaku","acceptedKeys":["kujaku"]},{"label":"Hibari","acceptedKeys":["hibari"]},{"label":"[Worst Generation]","acceptedKeys":["worst generation","generation"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["drake & apoo","drake","apoo"],"characterTags":["SWORD","Navy","Worst Generation","Ancient Zoan-type","Land of Wano Arc","On-Air Pirates","Animal Kingdom Pirates","Paramythia-type"],"builderAbilities":[{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_atk_down","label":"Remove ATK Down","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_silence","label":"Silence","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"heal_hp","label":"Heal HP","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"change_slots","label":"Change Slots","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"remove_blindness","label":"Remove Blindness","minTurns":99,"isCompleteRemoval":true,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_critical_atk","label":"Critical ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_barrier_pierce","label":"Barrier Pierce","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_damage_limit_break_class","label":"Damage Limit Break: Class","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"}],"sailorAbilities":["If your crew has 4+ [Worst Generation] or [Land of Wano Arc] characters, reduces Silence duration by 5 turns on this character.. Removes Blindness duration completely."],"sailorNotes":null,"potentialAbilities":[{"Name":"Critical Hit","description":["If you hit a PERFECT with this character, there is a 100% chance to deal 10% of this character''s attack in extra damage"]},{"Name":"Barrier Penetration","description":["This character''s normal attack will ignore barriers"]},{"Name":"Damage Limit Break: Class","description":["Boosts Damage Limit Break effect based on number of Slasher characters on the crew (except as Support Characters): +0.2 for 1, +.0.3 for 2, +0.4 for 3, +0.5 for 4, +0.6 for 5, +0.75 for 6"]}],"supportData":[],"swapData":{"base":"Reduces enemies'' Slasher and Striker Resistance by -15% for 1 turn, changes the orb of this character into a [BOMB] orb, recovers 5% of crew''s MAX HP, and deals 30x character''s ATK in character''s type damage to all enemies at the end of each turn for 1 turn.","super":"Reduces enemies'' Slasher and Striker Resistance by -30% for 1 turn, changes the orb of this character into a [BOMB] orb, changes orbs of adjacent characters into [WANO] orbs, recovers 5% of crew''s MAX HP, deals 50x character''s ATK in character''s type damage to all enemies at the end of each turn for 5 turns, and becomes Drake & Apoo for 3 turns.","superTurns":6},"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4502,"ability":[{"effects":[{"attributes":["HP"],"effect":"buff","level":8,"targeting":{"targets":["[Land of Wano Arc]","[Navy]","[Worst Generation]","[Paramythia-type]"]}},{"attributes":["ATK","SPD","DEF"],"effect":"debuff","level":2,"targeting":{"targets":["Fighter","Slasher"]},"condition":{"type":"trigger","stat":"hit","count":7}},{"attributes":["Special CT"],"effect":"hinderance","amount":10,"targeting":{"targets":["Fighter","Slasher"]},"condition":{"type":"trigger","stat":"takes damage","count":5}}]}],"special":[{"cooldown":30,"effects":[{"attributes":["Special CT"],"effect":"hinderan