      INSERT INTO character_details (character_id, detail_json)
      VALUES (4506, '{"characterId":4506,"captainAbility":"Boosts ATK of [PSY], Cerebral and Striker characters by 5x, boosts ATK of all other characters by 3.5x, boosts HP of [PSY], Cerebral and Striker characters by 1.3x, makes [STR], [PSY], [RCV] and [TND] orbs beneficial for [PSY], Cerebral and Striker characters, and reduces Bind duration by 10 turns. Boosts [PSY], Cerebral and Striker characters ATK against enemies inflicted with Increase Damage Taken, delayed enemies, poisoned enemies, enemies with reduced defense, paralyzed enemies, enemies inflicted with Burn and enemies inflicted with Negative by 1.03x-1.23x, by a multiplicative 1.03x for each status effect. If your crew has 4+ [Paramythia-type] or [Zoan-type] characters, allows effects that inflict Increase Damage Taken, Delay, Poison, Defense Reduction, Paralysis, Burn and Weaken to ignore Debuff Protection.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Boosts ATK of [PSY], Cerebral and Striker characters by 5x, boosts ATK of all other characters by 3.5x, boosts HP of [PSY], Cerebral and Striker characters by 1.3x, makes [STR], [PSY], [RCV] and [TND] orbs beneficial for [PSY], Cerebral and Striker characters, and reduces Bind duration by 10 turns. Boosts [PSY], Cerebral and Striker characters ATK against enemies inflicted with Increase Damage Taken, delayed enemies, poisoned enemies, enemies with reduced defense, paralyzed enemies, enemies inflicted with Burn and enemies inflicted with Negative by 1.03x-1.23x, by a multiplicative 1.03x for each status effect. If your crew has 4+ [Paramythia-type] or [Zoan-type] characters, allows effects that inflict Increase Damage Taken, Delay, Poison, Defense Reduction, Paralysis, Burn and Weaken to ignore Debuff Protection."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Boosts ATK of [STR], Cerebral and Striker characters by 4.75x, boosts HP of [STR], Cerebral and Striker characters by 1.3x, makes [STR], [PSY], [RCV] and [TND] orbs beneficial for [STR], Cerebral and Striker characters, and reduces Bind duration by 10 turns. Boosts [STR], Cerebral and Striker characters ATK against poisoned enemies by 1.1x. If your crew has 4+ [Paramythia-type] or [Zoan-type] characters, allows effects that inflict Increase Damage Taken, Delay, Poison, Defense Reduction, Paralysis, Burn, Negative and Weaken to ignore Debuff Protection."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of [STR], [PSY], Cerebral and Striker characters by 5x, boosts ATK of all other characters by 4x, boosts HP of [STR], [PSY], Cerebral and Striker characters by 1.3x, makes [STR], [PSY], [RCV] and [TND] orbs beneficial for [STR], [PSY], Cerebral and Striker characters, and reduces Bind duration by 10 turns. Boosts [STR], [PSY], Cerebral and Striker characters ATK against enemies inflicted with Increase Damage Taken, delayed enemies, poisoned enemies, enemies with reduced defense, paralyzed enemies, enemies inflicted with Burn and enemies inflicted with Negative by 1.04x-1.316x, by a multiplicative 1.04x for each status effect. If your crew has 4+ [Paramythia-type] or [Zoan-type] characters, allows effects that inflict Increase Damage Taken, Delay, Poison, Defense Reduction, Paralysis, Burn, Negative and Weaken to ignore Debuff Protection."}],"captainNotes":null,"specialName":"Coordinated Attacks of Gorgon Sisters","specialText":"Ignores Debuff Protection and inflicts all enemies with Burn that will deal 100x enemies'' ATK in damage for 1 turn, and becomes Hancock & Sandersonia & Marigold for 3 turns. If your crew has Color Affinity when the special is activated, boosts Base ATK of [STR], [PSY] and Cerebral characters by 2,000 for 1 turn. Boosts Color Affinity of [STR], [PSY] and Cerebral characters by 2.5x-3x for 1 turn depending on the number of status effects applied on enemy when special is activated. If enemies have 8+ status effects when the special is activated, increases boost effects of Color Affinity buffs by +0.4x, including effects activated in the same ability. If your crew has 3+ [Paramythia-type] or [Zoan-type] characters, increases boost effects of Orb Amplification buffs by +0.5x, and increases boost effects of Base ATK Boost buffs by +500, including effects activated in the same ability.","specialNotes":"2.5x for 0-2 effects, 2.75x for 3-5 effects, 3x for 6+ effects","superSpecialText":"Reduces enemies'' Threshold Damage Reduction duration by 6 turns, boosts ATK against poisoned enemies and enemies inflicted with Burn by 2.25x for 1 turn, optionally removes Captain Swap duration completely, transforms [STR] characters into Super [STR] characters, and transforms [PSY] characters into Super [PSY] characters.","superSpecialCriteriaText":"Can be launched as crewmate. When character becomes Hancock & Sandersonia & Marigold during Captain Shift and your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Paramythia-type], [Zoan-type], [Straw Hat Pirates]","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When character becomes Hancock & Sandersonia & Marigold during Captain Shift and your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Paramythia-type], [Zoan-type], [Straw Hat Pirates]","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":4,"matchMode":"any_candidate","options":[{"label":"[Paramythia-type]","acceptedKeys":["paramythia type"]},{"label":"[Zoan-type]","acceptedKeys":["zoan type"]},{"label":"[Straw Hat Pirates]","acceptedKeys":["straw hat pirates","pirates"]}]}],"hasNonRosterBranches":true,"parserStatus":"mixed"},"partyConflictKeys":["hancock & sandersonia & marigold","hancock","sandersonia","marigold"],"characterTags":["Kuja Pirates","Seven Warlords of the Sea","Paramythia-type","Amazon Lily Arc","Zoan-type"],"builderA