      INSERT INTO character_details (character_id, detail_json)
      VALUES (4507, '{"characterId":4507,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [Alabasta Arc] characters by 1.1x, boosts ATK of Cerebral and Free Spirit characters by 4.75x, by 5.25x instead if they have a beneficial orb, boosts HP of Cerebral and Free Spirit characters by 1.35x, makes [QCK] and [TND] orbs beneficial for Cerebral and Free Spirit characters, and reduces Paralysis duration by 10 turns. If your crew has 3+ [Alabasta Arc] or [Royalty] characters, reduces Special Use Limit duration by 7 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [Alabasta Arc] characters by 1.1x, boosts ATK of Cerebral and Free Spirit characters by 4.75x, by 5.25x instead if they have a beneficial orb, boosts HP of Cerebral and Free Spirit characters by 1.35x, makes [QCK] and [TND] orbs beneficial for Cerebral and Free Spirit characters, and reduces Paralysis duration by 10 turns. If your crew has 3+ [Alabasta Arc] or [Royalty] characters, reduces Special Use Limit duration by 7 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [Alabasta Arc] and [Royalty] characters by 1.1x, boosts ATK of Cerebral and Free Spirit characters by 5x, by 5.5x instead if they have the applicable tag, boosts HP of Cerebral and Free Spirit characters by 1.35x, makes [INT] and [TND] orbs beneficial for Cerebral and Free Spirit characters, and reduces Paralysis duration by 10 turns. If your crew has 3+ [Alabasta Arc] or [Royalty] characters, reduces Special Use Limit duration by 7 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [Alabasta Arc] and [Royalty] characters by 1.1x, boosts ATK of Cerebral and Free Spirit characters by 5x, by 5.5x instead if they have a beneficial orb, boosts HP of Cerebral and Free Spirit characters by 1.35x, makes [QCK], [INT] and [TND] orbs beneficial for Cerebral and Free Spirit characters, and reduces Paralysis duration by 10 turns. If your crew has 3+ [Alabasta Arc] or [Royalty] characters, reduces Special Use Limit duration by 7 turns."}],"captainNotes":null,"specialName":"Showing Off Their Dancers'' Outfits","specialText":"Reduces Switch Effect and VS Gauge of all characters by 2, reduces Slot Bind duration by 7 turns, boosts Orb Effects of all characters by 2.75x, can be enhanced up to 2 times, for 2 turns, increases boost effects of Color Affinity buffs by +0.4x, increases boost effects of Status ATK Boost buffs applied by all characters by +0.25x for 1 turn, and becomes Nami & Vivi for 3 turns. If your crew has 2+ [Alabasta Arc] or [Royalty] characters, reduces Minimum-Chain ATK Down duration by 3 turns, and reduces enemies'' Cerebral and Free Spirit resistance by -15% for 1 turn. If your crew has 3+ [Alabasta Arc] or [Royalty] characters, reduces enemies'' Cerebral and Free Spirit resistance by -10% for 1 turn.","specialNotes":null,"superSpecialText":"Increases boost effects of enemies'' Increase Damage Taken debuffs by +0.25x, inflicts all enemies with Increase Damage Taken by 2x for 1 turn, reduces Special Cooldown of this character by 9 turns, and transforms Cerebral characters into Super Cerebral characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and yo