      INSERT INTO character_details (character_id, detail_json)
      VALUES (4510, '{"characterId":4510,"captainAbility":"Boosts ATK of [QCK], Cerebral and Fighter characters by 3.25x, boosts ATK against poisoned enemies by 1.2x, boosts HP of [QCK], Cerebral and Fighter characters by 1.2x, and allows effects that inflict Poison to ignore Debuff Protection.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [QCK], Cerebral and Fighter characters by 3.25x, boosts ATK against poisoned enemies by 1.2x, boosts HP of [QCK], Cerebral and Fighter characters by 1.2x, and allows effects that inflict Poison to ignore Debuff Protection."}],"captainNotes":null,"specialName":"Little Brother''s Irreplaceable Friends","specialText":"Removes Poison duration completely, and boosts Color Affinity of [QCK], Cerebral and Fighter characters by 2.25x for 1 turn. If enemies are inflicted with any Poison when the special is activated, inflicts all enemies with Set Target, increasing damage taken from [QCK], Cerebral and Fighter characters by 1.5x and reducing Special Cooldown of [QCK], Cerebral and Fighter characters by 2 turns when they defeat an enemy, for 1 turn. If your crew has 3+ [Germa 66] or [Royalty] characters, removes enemies'' Poison duration completely, inflicts all enemies with Reiju Poison, and reduces Chain Coefficient Reduction duration by 4 turns.","specialNotes":"Reiju Poison deals 20% of enemies'' current HP in damage at the end of each turn and recovers 20% crew''s MAX HP at the end of each turn. Reiju Poison is derivative of Normal Poison, so it fulfills Poison Status ATK Boosts and is affected by Poison Debuff Immunity.","superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["vinsmoke reiju","reiju"],"characterTags":["Germa 66","Royalty","Whole Cake Island Arc"],"builderAbilities":[{"key":"remove_poison","label":"Remove Poison","minTurns":4,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMo