      INSERT INTO character_details (character_id, detail_json)
      VALUES (4512, '{"characterId":4512,"captainAbility":"Boosts ATK of [PSY], Slasher and Fighter characters by 4.5x, by 5.625x instead if they have a beneficial orb, boosts HP of [PSY], Slasher and Fighter characters by 1.3x, boosts chances of getting matching orbs, and makes [PSY], [RCV] and [TND] orbs beneficial for [PSY], Slasher and Fighter characters. If your crew has 3+ [Paramythia-type], [Navy] or [SWORD] characters, increases duration of any ATK Up and Orb Amplification buffs applied by specials by 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Boosts ATK of [PSY], Slasher and Fighter characters by 4.5x, by 5.625x instead if they have a beneficial orb, boosts HP of [PSY], Slasher and Fighter characters by 1.3x, boosts chances of getting matching orbs, and makes [PSY], [RCV] and [TND] orbs beneficial for [PSY], Slasher and Fighter characters. If your crew has 3+ [Paramythia-type], [Navy] or [SWORD] characters, increases duration of any ATK Up and Orb Amplification buffs applied by specials by 1 turn."}],"captainNotes":null,"specialName":"Almighty Discipline","specialText":"Changes [BLOCK], [BOMB] and [SUPERBOMB] orbs into [EMPTY] orbs, deals 50x-500x character''s ATK in [PSY] damage to one enemy depending on number of [BLOCK], [BOMB] and [SUPERBOMB] slots emptied, changes all orbs into matching orbs, and increases Orb Effects of beneficial [STR], [DEX], [QCK], [PSY] and [INT] orbs to 3.5x for 1 turn. If your crew has 3+ [Paramythia-type], [Navy] or [SWORD] characters, reduces enemies'' Barrier duration by 2 turns, reduces Paralysis duration by 3 turns, removes Poison duration completely, adds 1.6x to chain multiplier for 1 turn, and ignores Debuff Protection and paralyzes (60%) all enemies for 1 turn; paralyzes (60%) all enemies for 1 turn otherwise.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["kujaku"],"characte