      INSERT INTO character_details (character_id, detail_json)
      VALUES (4515, '{"characterId":4515,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect of all characters by 2. Boosts ATK of [Dressrosa Kingdom] and [Royalty] characters by 1.1x, boosts ATK of all characters by 5x, by 5.5x instead if they have a beneficial orb, boosts HP and RCV of all characters by 1.3x, makes [QCK], [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of this character completely when it is rewinded. If your crew has 3+ [Dressrosa Kingdom] or [Royalty] characters, increases duration of any ATK Up and Orb Amplification buffs applied by specials by 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 2 turns, and reduces Switch Effect of all characters by 2. Boosts ATK of [Dressrosa Kingdom] and [Royalty] characters by 1.1x, boosts ATK of all characters by 5x, by 5.5x instead if they have a beneficial orb, boosts HP and RCV of all characters by 1.3x, makes [QCK], [RCV] and [TND] orbs beneficial for all characters, and restores Special Cooldown of this character completely when it is rewinded. If your crew has 3+ [Dressrosa Kingdom] or [Royalty] characters, increases duration of any ATK Up and Orb Amplification buffs applied by specials by 1 turn."}],"captainNotes":null,"specialName":"Bond of Father and Daughter","specialText":"Reduces enemies'' Barrier duration by 3 turns, and reduces damage received by 95% for 1 turn. If this character is your Captain or Friend Captain, reduces Special Cooldown of bottom right character by 5 turns; reduces Special Cooldown of top right character by 5 turns otherwise. If your crew has 3+ [Dressrosa Kingdom] or [Royalty] characters, reduces enemies'' Intimidation duration by 2 turns, and boosts ATK of all characters by 3.25x for 2 turns; boosts ATK of Free Spirit and Fighter characters by 2.75x for 2 turns otherwise. If your crew has ATK Up when the special is activated, boosts Base ATK of Free Spirit and Fighter characters by 1,750 for 2 turns; if your crew also has 3+ [Dressrosa Kingdom] or [Royalty] characters, boosts Base ATK of all characters by 1,750 for 2 turns instead.","specialNotes":"The reduce Special Cooldown effect is limited to once per adventure.","superSpecialText":"Recovers 10,000 HP, changes all orbs into matching orbs, increases boost effects of ATK Up, Orb Amplification and Chain Addition buffs by +0.4x, and transforms [QCK] characters into Super [QCK] characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Dressrosa Kingdom], [Royalty] characters","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 4 of the following, excluding supports and counting only 1 per unit: [Dressrosa Kingdom], [Royalty] characters","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":4,"matchMode":"any_candidate","options":[{"label":"[Dressrosa Kingdom]","acceptedKeys":["dressrosa kingdom","kingdom"]},{"label":"[Royalty] characters","acceptedKeys":["royalty"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["rebecca"],"characterTags":["Dressrosa Kingdom","Royalty","Dressrosa Arc"],"builderAbilities":[{"key":"remove_enemy_barrier","label":"Remove Enemy Barrier","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_base_atk","label":"Boost Base ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_atk_boost_fighter","label":"ATK Boost: Fighter","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_fighter","label":"RCV Boost: Fighter","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_str_damage_reduction","label":"STR Damage Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"support_damage_reduction_turn","label":"Damage Reduction: Turn","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"supportData","coverageMode":"explicit"}],"sailorAbilities":["Boosts base ATK and RCV of [QCK], Free Spirit and Fighter characters by 100.. Restores Special Cooldown of this character by 10 turns when it is rewinded."],"sailorNotes":null,"potentialAbilities":[{"Name":"Pinch Healing","description":["