      INSERT INTO character_details (character_id, detail_json)
      VALUES (4521, '{"characterId":4521,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 1 turn, and reduces Switch Effect of all characters by 1. Boosts ATK of [QCK], Fighter and Powerhouse characters by 4.75x, boosts ATK of all other characters by 3.5x, and boosts HP of [QCK], Fighter and Powerhouse characters by 1.35x. Up to 7 times per adventure, when a [DEX] or [QCK] crewmate uses a special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the final stage, effect accumulates until the final stage; at the start of the final stage, applies Final Tap ATK boost based on the accumulated value. If your crew has 4+ [Egghead Arc] or [Navy] characters and you gain an ATK Up or Orb Amplification buff, increases boost effects of ATK Up and Orb Amplification buffs by 1.1x (up to 8x).","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 1 turn, and reduces Switch Effect of all characters by 1. Boosts ATK of [QCK], Fighter and Powerhouse characters by 4.75x, boosts ATK of all other characters by 3.5x, and boosts HP of [QCK], Fighter and Powerhouse characters by 1.35x. Up to 7 times per adventure, when a [DEX] or [QCK] crewmate uses a special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the final stage, effect accumulates until the final stage; at the start of the final stage, applies Final Tap ATK boost based on the accumulated value. If your crew has 4+ [Egghead Arc] or [Navy] characters and you gain an ATK Up or Orb Amplification buff, increases boost effects of ATK Up and Orb Amplification buffs by 1.1x (up to 8x)."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 1 turn, and reduces Switch Effect of all characters by 1. Boosts ATK of [DEX], Fighter and Powerhouse characters by 4.75x, boosts ATK of all other characters by 3.5x, and boosts HP of [DEX], Fighter and Powerhouse characters by 1.35x. Up to 7 times per adventure, when a [DEX] or [QCK] crewmate uses a special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the final stage, effect accumulates until the final stage; at the start of the final stage, applies Final Tap ATK boost based on the accumulated value. If your crew has 4+ [Egghead Arc] or [Navy] characters and you gain an ATK Up or Orb Amplification buff, increases boost effects of ATK Up and Orb Amplification buffs by 1.1x (up to 8x)."},{"key":"combined","label":"Captain Ability (Combined)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 1 turn, and reduces Switch Effect of all characters by 1. Boosts ATK of [DEX], [QCK], Fighter and Powerhouse characters by 5.75x, boosts ATK of all other characters by 4x, and boosts HP of [DEX], [QCK], Fighter and Powerhouse characters by 1.35x. Up to 7 times per adventure, when a [DEX] or [QCK] crewmate uses a special, reduces Switch Effect of this character by 1, and boosts Final Tap ATK of all characters by 5%. If the Final Tap ATK boost effect activates before the final stage, effect accumulates until the final stage; at the start of the final stage, applies Final Tap ATK boost based on the accumulated value. If your crew has 4+ [Egghead Arc] or [Navy] characters and you gain an ATK Up or Orb Amplification buff, increases boost effects of ATK Up and Orb Amplification buffs by 1.1x (up to 8x)."}],"captainNotes":null,"specialName":"Inherited Fists of Justice","specialText":"Reduces Special Cooldown of all characters by 1 turn, deals 300x character''s ATK in Typeless Fixed True damage to one enemy, reduces Despair duration by 7 turns, reduces enemies'' Threshold Damage Reduction duration by 7 turns, and becomes Garp & Coby for 3 turns. If your crew has Color Affinity when the special is activated, boosts Final Tap ATK of all characters by 50%; boosts Color Affinity of [DEX] and [QCK] characters by 3.25x for 3 turns otherwise. If your crew has 5+ turns of End of Turn Healing or 5+ turns of Additional Damage when the special is activated, increases boost effects of Color Affinity buffs by 1.2x (up to 5x), including effects activated in the same ability, and applies Territory: Fighter to the field for 2 turns.","specialNotes":null,"superSpecialText":"Reduces enemies'' Orb-Based Damage Reduction duration by 2 turns, enables Color Affinity buffs to be enhanced up to 2 times, reduces Special Cooldown of this character by 10 turns, transforms Fighter characters into Super Fighter characters, and transforms Powerhouse characters into Super Powerhouse characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Helmeppo, Prince Grus, Kujaku, Hibari, X Drake, Sakazuki (Akainu), Kuzan (Aokiji), Borsalino (Kizaru), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Tsuru, Tashigi, Vice Admiral Doll, Monkey D. Luffy, Portgas D. Ace, Sabo","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Helmeppo, Prince Grus, Kujaku, Hibari, X Drake, Sakazuki (Akainu), Kuzan (Aokiji), Borsalino (Kizaru), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Tsuru, Tashigi, Vice Admiral Doll, Monkey D. Luffy, Portgas D. Ace, Sabo","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Helmeppo","acceptedKeys":["helmeppo"]},{"label":"Prince Grus","acceptedKeys":["prince grus","grus"]},{"label":"Kujaku","acceptedKeys":["kujaku"]},{"label":"Hibari","acceptedKeys":["hibari"]},{"label":"X Drake","acceptedKeys":["x drake","drake"]},{"label":"Sakazuki (Akainu)","acceptedKeys":["sakazuki akainu","sakazuki","akainu"]},{"label":"Kuzan (Aokiji)","acceptedKeys":["kuzan aokiji","kuzan","aokiji"]},{"label":"Borsalino (Kizaru)","acceptedKeys":["borsalino kizaru","borsalino","kizaru"]},{"label":"Issho (Fujitora)","acceptedKeys":["issho fujitora","issho","fujitora"]},{"label":"Aramaki (Ryokugyu)","acceptedKeys":["aramaki ryokugyu","aramaki","ryokugyu"]},{"label":"Sengoku","acceptedKeys":["sengoku"]},{"label":"Tsuru","acceptedKeys":["tsuru"]},{"label":"Tashigi","acceptedKeys":["tashigi"]},{"label":"Vice Admiral Doll","acceptedKeys":["vice admiral doll","doll"]},{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Portgas D. Ace","acceptedKeys":["portgas d ace","ace"]},{"label":"Sabo","acceptedKeys":["sabo"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["garp & coby","garp","coby"],"characterTags":["Navy","Navy Vice Admiral","Egghead Arc","SWORD"],"builderAbilities":[{"key":"remove_despair","label":"Remove Despair","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens