      INSERT INTO character_details (character_id, detail_json)
      VALUES (4522, '{"characterId":4522,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of [Blackbeard Pirates] characters by 3 turns, reduces Switch Effect of all characters by 2, and boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 8 turns. Boosts ATK of [DEX], [INT], Driven and Shooter characters by 4.5x, by 5.5x instead if they have a [RCV], [TND], [EMPTY], [BOMB] or [SUPERBOMB] orb, boosts HP of [DEX], [INT], Driven and Shooter characters by 1.5x, and makes [DEX], [INT], [TND] and [BOMB] orbs beneficial for [DEX], [INT], Driven and Shooter characters. If your crew has 3+ [Blackbeard Pirates] or 6 [Egghead Arc] characters and a crew member uses a special with a Percent Damage Reduction buff, replaces that buff with the following effect: increases boost effects of ATK Up buffs by 2x (up to 6x).","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Blackbeard Pirates] characters by 3 turns, reduces Switch Effect of all characters by 2, and boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 8 turns. Boosts ATK of [DEX], [INT], Driven and Shooter characters by 4.5x, by 5.5x instead if they have a [RCV], [TND], [EMPTY], [BOMB] or [SUPERBOMB] orb, boosts HP of [DEX], [INT], Driven and Shooter characters by 1.5x, and makes [DEX], [INT], [TND] and [BOMB] orbs beneficial for [DEX], [INT], Driven and Shooter characters. If your crew has 3+ [Blackbeard Pirates] or 6 [Egghead Arc] characters and a crew member uses a special with a Percent Damage Reduction buff, replaces that buff with the following effect: increases boost effects of ATK Up buffs by 2x (up to 6x)."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of all characters by 1 turn, reduces Switch Effect of all characters by 2, and boosts Crew Damage Reduction to ATK of all characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 8 turns. Boosts ATK of [DEX], [INT], Driven and Shooter characters by 4.5x, by 5.5x instead if they have a [RCV], [TND], [EMPTY], [BOMB] or [SUPERBOMB] orb, boosts HP of [DEX], [INT], Driven and Shooter characters by 1.5x, and makes [DEX], [INT], [TND] and [BOMB] orbs beneficial for [DEX], [INT], Driven and Shooter characters. If your crew has 3+ [Blackbeard Pirates] or 6 [Egghead Arc] characters and a crew member uses a special with a Percent Damage Reduction buff, replaces that buff with the following effect: increases boost effects of ATK Up buffs by 2x (up to 6x)."},{"key":"combined","label":"Captain Ability (Combined)","text":"Boosts ATK of [DEX], [INT], Driven and Shooter characters by 4.75x, by 5.75x instead if they have a [RCV], [TND], [EMPTY], [BOMB] or [SUPERBOMB] orb, boosts HP of [DEX], [INT], Driven and Shooter characters by 1.5x, and makes [DEX], [INT], [TND] and [BOMB] orbs beneficial for [DEX], [INT], Driven and Shooter characters. If your crew has 3+ [Blackbeard Pirates] or 6 [Egghead Arc] characters and a crew member uses a special with a Percent Damage Reduction buff, replaces that buff with the following effect: increases boost effects of ATK Up buffs by 2x (up to 6x). If your crew has 5+ [Blackbeard Pirates] characters, attacks will ignore damage reducing Barriers and Buffs."}],"captainNotes":"Attacks are still affected by DEF value. DEF boost buffs (Blue shield) still reduce your damage and you cannot kill through Resilience, but Damage Negating (Yellow shield), % Damage Reduction (Rainbow shield), Barriers and Threshold Damage Reduction are ignored. Enemy attacks will go through YOUR defensive buffs.","specialName":"Drinking Together","specialText":"Reduces Paralysis duration by 10 turns, boosts ATK of [DEX], [INT], Driven and Shooter characters by 2.75x, can be enhanced up to 2 times, for 1 turn, and becomes Blackbeard & Kuzan for 3 turns. If HP is below 50% or crew has HP Guard when the special is activated, boosts Orb Effects of [DEX], [INT], Driven and Shooter characters by 3.5x for 3 turns. If your crew has 3+ [Blackbeard Pirates] or 6 [Egghead Arc] characters, activates HP Guard of 85% effect for 1 turn, and boosts Enemy Damage Reduction to ATK of all characters by 1.7x-2.7x, proportional to the strength of enemies'' Percent Damage Reduction buff, for 1 turn.","specialNotes":null,"superSpecialText":"Reduces enemies'' Percent Damage Reduction effect by 40%, boosts Final Tap ATK of all characters by 50%, transforms [DEX] characters into Super [DEX] characters, and transforms [INT] characters into Super [INT] characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and HP must be below 50%","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and HP must be below 50%","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"},"partyConflictKeys":["blackbeard & kuzan","blackbeard","kuzan","marshall d teach"],"characterTags":["Blackbeard Pirates","Four Emperors","Worst Generation","Logia-type","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_special_charge_start_of_quest","label":"At start of quest","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_barrier_pierce","label":"Barrier Pierce","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"}],"sailorAbilities":["Reduces Special Cooldown of all characters by 1 turn at the start of the fight.. Boosts base ATK of [DEX] and [INT] characters by 1.1x."],"sailorNotes":null,"potentialAbilities":[{"Name":"Special Use Limit","description":["Reduces Special Use Limit duration by 3 turns"]},{"Name":"Barrier Penetration","description":["This character''s normal attack will ignore barriers"]},{"Name":"Rush","description":["Obtain Rush Lv.5"]}],"supportData":[],"swapData":{"base":"Removes Slot Bind duration completely on this character, changes the orb, including [BLOCK] orb, of this character into a matching orb, reduces Paralysis duration by 1 turn, boosts ATK of this character by 1.5x, allowing override, for 1 turn, and makes this character''s normal attacks ignore damage reducing barriers and buffs for 1 turn.","super":"Removes Slot Bind duration completely on this character, changes the orb, including [BLOCK] orb, of this character into a matching orb, reduces Paralysis duration by 3 turns, boosts ATK of all characters by 2x, allowing override, for 1 turn, makes this character''s normal attacks ignore damage reducing barriers and buffs for 1 turn, and becomes Blackbeard & Kuzan for 3 turns.","superTurns":6},"vsSpecial":null,"superType":null,"superTandemData":null,"finalTapData":null,"rushSugoSpecialData":null,"superClass":null,"rumbleData":{"id":4522,"ability":[{"effects":[{"attributes":["DEF"],"effect":"buff","level":6,"targeting":{"targets":["Driven","[Blackbeard Pirates]"]}},{"attributes":["HP"],"effect":"debuff","level":7,"targeting":{"targets":["enemies"]}},{"attributes":["Special CT"],"effect":"debuff","level":3,"targeting":{"targets":["enemies"]},"condition":{"type":"crew","composition":true,"comparator":"more","count":5,"targets":["Driven"]}},{"attributes":["ATK"],"effect":"buff","level":8,"targeting":{"targets":["self"]},"condition":{"type":"crew","composition":true,"comparator":"more","count":4,"targets":["[Blackbeard Pirates]"]}},{"attributes":["DEF"],"effect":"debuff","level":7,"targeting":{"targets":["enemies"]},"condition":{"type":"crew","composition":true,"comparator":"more","count":4,"targets":["[Blackbeard Pirates]"]}}]}],"special":[{"cooldown":28,"effects":[{"attributes":["RCV Bind"],"effect":"hinderance","chance":100,"duration":20,"targeting":{"count":3,"targets":["enemies"]}},{"attributes":["ATK","SPD","DEF"],"effect":"debuff","level":8,"duration":20,"targeting":{"targets":["enemies"],"status":["RCV Bind"]}},{"attributes":["Action Bind"],"effect":"hinderance","chance":100,"duration":10,"targeting":{"targets":["enemies"],"status":["Special Bind"]}},{"attributes":["Special CT"],"effect":"hinderance","amount":20,"targeting":{"targets":["enemies"],"status":["Shield"]}},{"amount":6000,"type":"fixed","effect":"damage","targeting":{"targets":["enemies"],"status":["Shield"]}},{"amount":5,"type":"atk","effect":"damage","spread":true,"targeting":{"targets":["enemies"],"status":["Confusion"]}},{"amount":3,"type":"atk","effect":"damage","targeting":{"targets":["enemies"]},"range":{"size":"large","direction":"radial"}}]}],"superspecial":[{"condition