      INSERT INTO character_details (character_id, detail_json)
      VALUES (4523, '{"characterId":4523,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of [Navy] and [SWORD] characters by 3 turns, and reduces Switch Effect of all characters by 4. Boosts ATK of [Navy] and [SWORD] characters by 1.2x, boosts ATK of [DEX], Shooter and Fighter characters by 5.25x, by 6.3x instead if they have the applicable tag, boosts RCV of [DEX], Shooter and Fighter characters by 1.35x, and increases boost effects of Status ATK Boost buffs applied by specials by +0.25x. Up to 2 times per adventure, when Coby uses a special as crewmate, inflicts all enemies with Set Target, increasing damage taken from all characters by 1.75x and reducing Special Cooldown of all characters by 1 turn when they defeat an enemy, for 1 turn.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Navy] and [SWORD] characters by 3 turns, and reduces Switch Effect of all characters by 4. Boosts ATK of [Navy] and [SWORD] characters by 1.2x, boosts ATK of [DEX], Shooter and Fighter characters by 5.25x, by 6.3x instead if they have the applicable tag, boosts RCV of [DEX], Shooter and Fighter characters by 1.35x, and increases boost effects of Status ATK Boost buffs applied by specials by +0.25x. Up to 2 times per adventure, when Coby uses a special as crewmate, inflicts all enemies with Set Target, increasing damage taken from all characters by 1.75x and reducing Special Cooldown of all characters by 1 turn when they defeat an enemy, for 1 turn."}],"captainNotes":null,"specialName":"Senior-Rescuing Flower Rounds","specialText":"Reduces enemies'' Percent Damage Reduction duration by 7 turns, and reduces ATK Down duration by 7 turns. If your crew has 4+ [Navy] characters, boosts ATK against enemies inflicted with Increase Damage Taken by 2.25x for 1 turn, and ignores Debuff Protection and inflicts all enemies with Increase Damage Taken by 2.5x for 1 turn; inflicts all enemies with Increase Damage Taken by 2.5x for 1 turn otherwise. If your crew has 5-10 turns of End of Turn Healing when the special is activated, increases boost effects of Orb Amplification and Color Affinity buffs by +0.3x. If your crew has 10+ turns of End of Turn Healing when the special is activated, increases boost effects of ATK Up buffs by 1.5x (up to 8x), recovers 30,000 HP, and reduces End of Turn Healing duration by 3 turns.","specialNotes":null,"superSpecialText":"Optionally removes Captain Swap duration completely, increases boost effects of Chain Multiplication buffs by +0.2x, adds 1.2x to chain multiplier for 1 turn, changes the orb of this character into a [TND] orb, increases duration of any End of Turn Healing buffs by 3 turns, recovers 5,000 HP at the end of the turn for 5 turns, and transforms [DEX] characters into Super [DEX] characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Monkey D. Garp, Coby, Helmeppo, Prince Grus, Kujaku, X Drake, Sakazuki (Akainu), Borsalino (Kizaru), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Tsuru, Tashigi","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Monkey D. Garp, Coby, Helmeppo, Prince Grus, Kujaku, X Drake, Sakazuki (Akainu), Borsalino (Kizaru), Issho (Fujitora), Aramaki (Ryokugyu), Sengoku, Tsuru, Tashigi","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Coby","acceptedKeys":["coby"]},{"label":"Helmeppo","acceptedKeys":["helmeppo"]},{"label":"Prince Grus","acceptedKeys":["prince grus","grus"]},{"label":"Kujaku","acceptedKeys":["kujaku"]