      INSERT INTO character_details (character_id, detail_json)
      VALUES (4528, '{"characterId":4528,"captainAbility":"Launches the following effect at start of fight: reduces damage received by 100% for 1 attack. Boosts ATK of [DEX], Powerhouse and Fighter characters by 5x, by 5.25x instead if they have a beneficial orb, boosts HP of [DEX], Powerhouse and Fighter characters by 1.4x, makes [DEX] and [RCV] orbs beneficial for all characters, and reduces damage received by 20%. If your crew has 3+ [SWORD] characters, boosts ATK of [DEX] characters by 5.5x, by 5.775x instead if they have a beneficial orb.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effect at start of fight: reduces damage received by 100% for 1 attack. Boosts ATK of [DEX], Powerhouse and Fighter characters by 5x, by 5.25x instead if they have a beneficial orb, boosts HP of [DEX], Powerhouse and Fighter characters by 1.4x, makes [DEX] and [RCV] orbs beneficial for all characters, and reduces damage received by 20%. If your crew has 3+ [SWORD] characters, boosts ATK of [DEX] characters by 5.5x, by 5.775x instead if they have a beneficial orb."}],"captainNotes":null,"specialName":"Battleship-Protecting Glorp Web","specialText":"Reduces damage received by 80% for 3 turns, reduces enemies'' End of Turn Damage and Enrage duration by 20 turns, changes all orbs, including [BLOCK] orbs, into [DEX] orbs, and boosts ATK of all characters by 3.25x for 3 turns. If during that turn you score 3 PERFECT hits, boosts ATK against enemies with reduced defense by 2.25x for 1 turn in the following turn. If your crew has 3+ [SWORD] characters, allows crew to stack 2 different Status ATK Boost buffs for 3 turns, and recovers 8,000 HP at the end of the turn for 10 turns.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["prince grus","grus"],"characterTags":["SWORD","Navy","Paramythia-type","Egghead Arc"],"builderAbilities":[{"ke