      INSERT INTO character_details (character_id, detail_json)
      VALUES (4529, '{"characterId":4529,"captainAbility":"Reduces Switch Effect and VS Gauge of all characters by 3 at the start of the fight, boosts ATK of [DEX], Free Spirit, and Slasher characters by 5.5x, by 6x instead if they have a [DEX], [RCV], [TND], [RAINBOW] or [WANO] orb, boosts HP of all characters by 1.3x, makes [DEX], [RCV] and [TND] orbs beneficial for all characters, and all characters who attack with a type advantage will gain a [TND] orb after attacking. If your crew has 3+ [Straw Hat Pirates], [Worst Generation] and [Giant] characters, boosts ATK of all characters by 5.5x, by 6x instead if they have a [DEX], [RCV], [TND], [RAINBOW] or [WANO] orb, and restores Special Cooldown of all characters by 10 turns when they are rewinded.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Reduces Switch Effect and VS Gauge of all characters by 3 at the start of the fight, boosts ATK of [DEX], Free Spirit, and Slasher characters by 5.5x, by 6x instead if they have a [DEX], [RCV], [TND], [RAINBOW] or [WANO] orb, boosts HP of all characters by 1.3x, makes [DEX], [RCV] and [TND] orbs beneficial for all characters, and all characters who attack with a type advantage will gain a [TND] orb after attacking. If your crew has 3+ [Straw Hat Pirates], [Worst Generation] and [Giant] characters, boosts ATK of all characters by 5.5x, by 6x instead if they have a [DEX], [RCV], [TND], [RAINBOW] or [WANO] orb, and restores Special Cooldown of all characters by 10 turns when they are rewinded."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Reduces Special Cooldown of [Five Elders] and [Celestial Dragon] characters by 6 turns and reduces Switch Effect and VS Gauge of all characters by 3 at the start of the fight, boosts ATK of [STR], Cerebral and Slasher characters by 5.5x, by 6x instead if they have a [STR], [RCV], [TND], [RAINBOW] or [WANO] orb, boosts HP of all characters by 1.3x, makes [STR], [RCV] and [TND] orbs beneficial for all characters, and all characters who attack with a type advantage will gain a [RCV] orb after attacking. If your crew has 4+ [Egghead Arc], [World Government] and [Five Elders] characters, boosts ATK of all characters by 5.5x, by 6x instead if they have a [STR], [RCV], [TND], [RAINBOW] or [WANO] orb, and reduces Special Bind duration by 10 turns; additionally, if a [World Government] or [Five Elders] character uses a special with a Color Affinity buff and your crew has Color Affinity when the special is activated: decreases boost effects of Color Affinity buffs by 0.25x, and converts Color Affinity into a Stackable Color Affinity."}],"captainNotes":null,"specialName":"Fearsome Clash of Blades","specialText":"Reduces enemies'' Threshold Damage Reduction duration by 7 turns, reduces Bind and Paralysis duration by 7 turns, boosts ATK of [DEX], Free Spirit and Slasher characters by 3.25x, can be enhanced up to 2 times, for 1 turn, and reduces enemies'' [DEX] resistance by -30% for 1 turn. If your crew has ATK Up when the special is activated, inflicts all enemies with Set Target, increasing damage taken from all characters by 2x and reducing Special Cooldown of all characters by 2 turns when they defeat an enemy, for 1 turn. If your crew has 3+ [Straw Hat Pirates] and [Worst Generation] characters and your crew has 3+ turns of End of Turn Healing when the special is activated, reduces End of Turn Healing duration by 3 turns, and increases boost effects of ATK Up buffs by 1.3x (up to 10x), including effects activated in the same ability.. Reduces Despair duration by 7 turns, boosts Advantageous Class Effect of Cerebral and Slasher characters by 2x, can be enhanced up to 2 times, for 1 turn, and boosts Color Affinity of [STR], Cerebral and Slasher characters by 3.25x, can be enhanced up to 2 times, for 1 turn. If your crew has Advantageous Class Effect when the special is activated, ignores Debuff Protection and inflicts all enemies with Weaken by 1.3x, by 1.69x instead if enemies are inflicted with Increase Damage Taken, for 1 turn. If your crew has 4+ [Egghead Arc], [World Government] and [Five Elders] characters and enemies are not inflicted with Increase Damage Taken, increases boost effects of Color Affinity buffs by 1.2x (up to 10x), including effects activated in the same ability. If your crew has 4+ [Egghead Arc], [World Government] and [Five Elders] characters and enemies are inflicted with Increase Damage Taken, reduces enemies'' Increase Damage Taken duration by 5 turns, increases boost effects of Color Affinity buffs by 1.2x (up to 10x) and increases boost effects of Advantageous Class Effect buffs by 1.5x (up to 10x), including effects activated in the same ability.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["zoro vs st. nusjuro","nusjuro"],"characterTags":["Straw Hat Pirates","Worst Generation","Egghead Arc","World Government","Celestial Dragon","Five Elders"],"builderAbilities":[{"key":"remove_threshold_damage_reduction","label":"Remove Threshold Damage Reduction","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_bind","label":"Remove Bind","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_enemy_end_of_turn_heal","label":"Remove End of Turn Heal","minTurns":3,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_despair","label":"Remove Despair","minTurns":7,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_increase_damage_taken","label":"Remove Increase Damage Taken","minTurns":5,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"effect_boost","label":"Effect Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"reduce_damage","label":"Reduce Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_increase_damage_taken","label":"Increase Damage Taken","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_resistance_reduction","label":"Resistance Reduction","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"apply_set_target","label":"Set Target","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"defeat_enemy","label":"Defeat Enemy","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"extend_turn_duration","label":"Extend Turn Duration","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"boost_type_effects","label":"Boost Type Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"reduce_special_charge","label":"Reduce Special Change","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"captainAbility","coverageMode":"explicit"},{"key":"crewmate_make_slots_favorable","label":"Make Slots Favorable","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_special_charge_start_of_quest","label":"At start of quest","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_atk_boost_crew","label":"ATK Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_rcv_boost_crew","label":"RCV Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"crewmate_hp_boost_crew","label":"HP Boost: Crew","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"sailorAbilities","coverageMode":"explicit"},{"key":"potential_pinch_healing","label":"Pinch Healing","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_critical_atk","label":"Critical ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"},{"key":"potential_super_tandem_boost","label":"Super Tandem Boost","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"potentialAbilities","coverageMode":"explicit"}],"sailorAbilities":["Makes [TND] orbs beneficial for all characters. If field has Territory: [DEX], boosts base ATK, HP and RCV of all characters by 200; boosts base HP of all characters by 200 otherwise.. Reduces Special Cooldown of all characters by 1 turn at the start of the fight.. Makes [RCV] orbs beneficial for all characters. If field has Territory: Cerebral, boosts base 