      INSERT INTO character_details (character_id, detail_json)
      VALUES (4536, '{"characterId":4536,"captainAbility":"Reduces Special Cooldown of [STR] and [DEX] characters by 2 turns, by 3 turns instead if they are a Free Spirit character, at the start of the fight, boosts ATK of [STR], [DEX] and Free Spirit characters by 5x, by 5.5x instead in the turn \"Coordinated Giant Arm and Sniping\" is used, boosts HP of [STR], [DEX] and Free Spirit characters by 1.3x, and makes [DEX] and [RCV] orbs beneficial for all characters. Up to 3 times per adventure, when a [Straw Hat Pirates], [Giant] or [Four Emperors] crewmate uses a special, reduces Special Cooldown of this character by 5 turns. If your crew has 3+ [Straw Hat Pirates], [Giant] or [Four Emperors] characters, boosts ATK of Free Spirit characters by 5.5x, by 6.05x instead in the turn \"Coordinated Giant Arm and Sniping\" is used; additionally, when a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Percent Damage Reduction duration by 3 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of [STR] and [DEX] characters by 2 turns, by 3 turns instead if they are a Free Spirit character, at the start of the fight, boosts ATK of [STR], [DEX] and Free Spirit characters by 5x, by 5.5x instead in the turn \"Coordinated Giant Arm and Sniping\" is used, boosts HP of [STR], [DEX] and Free Spirit characters by 1.3x, and makes [DEX] and [RCV] orbs beneficial for all characters. Up to 3 times per adventure, when a [Straw Hat Pirates], [Giant] or [Four Emperors] crewmate uses a special, reduces Special Cooldown of this character by 5 turns. If your crew has 3+ [Straw Hat Pirates], [Giant] or [Four Emperors] characters, boosts ATK of Free Spirit characters by 5.5x, by 6.05x instead in the turn \"Coordinated Giant Arm and Sniping\" is used; additionally, when a Barrier Penetration Enabled character hits a PERFECT, reduces enemies'' Percent Damage Reduction duration by 3 turns."}],"captainNotes":null,"specialNa