      INSERT INTO character_details (character_id, detail_json)
      VALUES (4549, '{"characterId":4549,"captainAbility":"Reduces Special Cooldown of all characters by 1 turn and reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [STR], Striker and Driven characters by 5x, boosts HP of [STR], Striker and Driven characters by 1.3x, and makes [STR] and [INT] orbs beneficial for all characters. If HP is below 50% at the start of the turn, boosts ATK of [STR], Striker and Driven characters by 6x instead, and reduces damage received by 25%. If your crew has 4+ [Kid Pirates], [Worst Generation] or [Land of Wano Arc] characters or your crew has 6 [Kid Pirates], [Worst Generation] or [Egghead Arc] characters, reduces Despair duration by 10 turns, and boosts base ATK of [Paramythia-type] characters by 500.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Reduces Special Cooldown of all characters by 1 turn and reduces Special Cooldown of this character by 4 turns at the start of the fight, boosts ATK of [STR], Striker and Driven characters by 5x, boosts HP of [STR], Striker and Driven characters by 1.3x, and makes [STR] and [INT] orbs beneficial for all characters. If HP is below 50% at the start of the turn, boosts ATK of [STR], Striker and Driven characters by 6x instead, and reduces damage received by 25%. If your crew has 4+ [Kid Pirates], [Worst Generation] or [Land of Wano Arc] characters or your crew has 6 [Kid Pirates], [Worst Generation] or [Egghead Arc] characters, reduces Despair duration by 10 turns, and boosts base ATK of [Paramythia-type] characters by 500."}],"captainNotes":null,"specialName":"Eradicating Damned Punk","specialText":"If HP is above 51% when the special is activated, reduces crew''s current HP by 50% crew''s MAX HP, and advances Special Cooldown of this character to MAX. Deals 100x character''s ATK in Typeless Fixed True damage to all enemies, and boosts ATK of [STR], Striker and Driven characters by 2.75x-3.25x for 1 turn. If your crew has ATK Up when the special is activated, boosts Orb Effects of [STR], Striker and Driven characters by 2.75x-3.25x for 1 turn. If your crew has ATK UP and Orb Amplification when the special is activated, boosts the Color Affinity of [STR], Striker and Driven characters by 2.5x-3x for 1 turn.","specialNotes":". Base: If your crew has 3+ [Kid Pirates] or [Worst Generation] characters, boosts the effect value of the ATK Up, Orb Amplification and Color Affinity buffs by +0.5x. LLB: If your crew has 3+ [Kid Pirates], [Worst Generation] or [Paramythia-type] characters, boosts the effect value of the ATK Up, Orb Amplification and Color Affinity buffs by +0.5x.","superSpecialText":"Changes all orbs into matching orbs, recovers 25% of crew''s MAX HP, reduces Burn duration by 6 turns, and transforms [STR] characters into Super [STR] characters.","superSpecialCriteriaText":"Can be launched as crewmate. If your crew has an ATK UP or Orb Amplification buff","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. If your crew has an ATK UP or Orb Amplification buff","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[],"hasNonRosterBranches":true,"parserStatus":"non_roster_only"},"partyConflictKeys":["eustass \"captain\" kid","kid"],"characterTags":["Kid Pirates","Worst Generation","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"deal_fixed_damage","label":"Deal Fixed Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"special_damage","label":"Damage","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_atk","label":"Boost ATK","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"boost_slot_effects","label":"Boost Slot Effects","minTurns":null,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode"