      INSERT INTO character_details (character_id, detail_json)
      VALUES (4550, '{"characterId":4550,"captainAbility":"Launches the following effects at start of fight: reduces Special Cooldown of [Cross Guild] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [STR] and [INT] characters by 4.5x, boosts [STR] and [INT] characters ATK against delayed enemies, poisoned enemies, paralyzed enemies and enemies with reduced defense by 1.15x, boosts HP of [STR] and [INT] characters by 1.3x, makes [INT] and [TND] orbs beneficial for [STR] and [INT] characters, and reduces ATK Down duration by 10 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effects at start of fight: reduces Special Cooldown of [Cross Guild] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [STR] and [INT] characters by 4.5x, boosts [STR] and [INT] characters ATK against delayed enemies, poisoned enemies, paralyzed enemies and enemies with reduced defense by 1.15x, boosts HP of [STR] and [INT] characters by 1.3x, makes [INT] and [TND] orbs beneficial for [STR] and [INT] characters, and reduces ATK Down duration by 10 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Cross Guild] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [STR] and [INT] characters by 4.5x, by 5.25x instead after the 3rd PERFECTs in a row, boosts HP of [STR] and [INT] characters by 1.3x, makes [STR] and [TND] orbs beneficial for [STR] and [INT] characters, and reduces ATK Down duration by 10 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Cross Guild] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [STR] and [INT] characters by 4.5x, by 5.25x instead after the 3rd PERFECTs in a row, boosts [STR] and [INT] characters ATK against delayed enemies, poisoned enemies, paralyzed enemies and enemies with reduced defense by 1.15x, boosts HP of [STR] and [INT] characters by 1.3x, makes [STR], [INT] and [TND] orbs beneficial for [STR] and [INT] characters, and reduces ATK Down duration by 10 turns. If your crew has 2+ [Cross Guild] or [Four Emperors] characters, boosts ATK of Slasher and Cerebral characters by 1.1x."}],"captainNotes":null,"specialName":"Terrorizing Sand and Sword","specialText":"Poisons all enemies, removes Poison duration completely, reduces enemies'' Threshold Damage Reduction duration by 7 turns, boosts Orb Effects of [STR] and [INT] characters by 3.25x, can be enhanced up to 2 times, for 3 turns, and becomes Crocodile & Mihawk for 3 turns. If enemies have All Debuff Protection, Delay Debuff Protection or Poison Debuff Protection when the special is activated, ignores Debuff Protection and paralyzes (60%) all enemies for 1 turn. If your crew has Orb Amplification when the special is activated, boosts Crew Damage Reduction to ATK of Slasher and Cerebral characters by 1x-2x, proportional to the strength of crew''s Percent Damage Reduction buff, for 1 turn. If your crew has 2+ [Cross Guild] or [Four Emperors] characters and field has Territory: [STR], Territory: [INT] or Territory: Slasher when the special is activated, allows crew to stack 2 different Status ATK Boost buffs for 1 turn.","specialNotes":null,"superSpecialText":"Increases boost effects of Orb Amplification and Status ATK Boost buffs by 1.1x (up to 15x), and transforms Slasher characters into Super Slasher characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 1 of the following, excluding supports and counting only 1 