      INSERT INTO character_details (character_id, detail_json)
      VALUES (4551, '{"characterId":4551,"captainAbility":"Launches the following effects at start of fight: reduces Special Cooldown of [Blackbeard Pirates] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [QCK] and [INT] characters by 4.5x, by 5.25x instead after the 3rd PERFECTs in a row, boosts HP of [QCK] and [INT] characters by 1.3x, makes [INT], [RCV] and [BOMB] orbs beneficial for [QCK] and [INT] characters, and reduces Despair duration by 10 turns.","captainAbilityVariants":[{"key":"character1","label":"Captain Ability (Character 1)","text":"Launches the following effects at start of fight: reduces Special Cooldown of [Blackbeard Pirates] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [QCK] and [INT] characters by 4.5x, by 5.25x instead after the 3rd PERFECTs in a row, boosts HP of [QCK] and [INT] characters by 1.3x, makes [INT], [RCV] and [BOMB] orbs beneficial for [QCK] and [INT] characters, and reduces Despair duration by 10 turns."},{"key":"character2","label":"Captain Ability (Character 2)","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Blackbeard Pirates] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [QCK] and [INT] characters by 5x, boosts HP of [QCK] and [INT] characters by 1.3x, makes [QCK], [TND] and [BOMB] orbs beneficial for [QCK] and [INT] characters, and reduces Despair duration by 10 turns."},{"key":"combined","label":"Captain Ability (Combined)","text":"Launches the following effect at start of fight: reduces Special Cooldown of [Blackbeard Pirates] and [Four Emperors] characters by 3 turns, and reduces Switch Effect and VS Gauge of all characters by 2. Boosts ATK of [QCK] and [INT] characters by 5.5x, by 5.75x instead if they have a beneficial orb, boosts HP of [QCK] and [INT] characters by 1.3x, makes [QCK], [INT], [RCV], [TND] and [BOMB] orbs beneficial for [QCK] and [INT] characters, and reduces Despair duration by 10 turns. If your crew has 2+ [Blackbeard Pirates] or [Four Emperors] characters, boosts ATK of Free Spirit, Driven and Slasher characters by 1.1x."}],"captainNotes":null,"specialName":"Coordinated Might and Invisibility","specialText":"Reduces Paralysis and Special Bind duration by 7 turns, boosts ATK of [QCK] and [INT] characters by 3.25x, can be enhanced up to 2 times, for 3 turn, and becomes Burgess & Shiryu for 3 turns. If your crew has ATK Up when the special is activated, boosts Advantageous Class Effect of Free Spirit, Driven and Slasher characters by 1.75x for 1 turn. If your crew has 2+ [Blackbeard Pirates] or [Four Emperors] characters and field has Territory: [QCK], Territory: [INT] or Territory: Free Spirit when the special is activated, increases Chain Tap Timing Bonus of [QCK] and [INT] characters to +0.3x-0.7x for 3 turns depending on Tap Timing. If enemies have Percent Damage Reduction when the special is activated and an [QCK] character is supporting this character, applies Territory: [QCK] to the field for 2 turns. If enemies have Percent Damage Reduction when the special is activated and an [INT] character is supporting this character, applies Territory: Free Spirit to the field for 2 turns.","specialNotes":"GOOD: +0.3, GREAT: +0.5, PERFECT: +0.7","superSpecialText":"Reduces enemies'' damage received by 30% for 3 turns, increases boost effects of Orb Amplification and Color Affinity buffs by 1.2x (up to 15x), and transforms Free Spirit characters into Super Free Spirit characters.","superSpecialCriteriaText":"Can be launched as crewmate. When this character is in Combined Form from Super Swap Effect and your crew must consist of any 1 of the following, excluding supports and counting only 1 per unit: Marshall D. Teach (Blackbeard), Van Ogre, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, K