      INSERT INTO character_details (character_id, detail_json)
      VALUES (4554, '{"characterId":4554,"captainAbility":"Launches the following effects at start of fight: changes all orbs into [BOMB] orbs, and locks all orbs for 1 turn. Boosts ATK of all characters by 3.5x, boosts HP of all characters by 1.25x, and makes [BOMB] and [SUPERBOMB] orbs beneficial for all characters.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effects at start of fight: changes all orbs into [BOMB] orbs, and locks all orbs for 1 turn. Boosts ATK of all characters by 3.5x, boosts HP of all characters by 1.25x, and makes [BOMB] and [SUPERBOMB] orbs beneficial for all characters."}],"captainNotes":null,"specialName":"Revealing Their Fate","specialText":"Reduces Despair duration by 2 turns. Launches the following effects depending on the Special Launch Status of this character when the special is activated: (0): Sets Chain Boundaries to 2.25x and 17.5x for 1 turn, and sets Special Launch Status of this character to (1). (1): Reduces ATK Down duration by 1 turn, and adds 1.2x to chain multiplier for 1 turn. If this character''s orb is a [BLOCK], [BOMB], [G] or [RAINBOW] orb when the special is activated, sets Special Launch Status of this character to (2). (2): Reduces ATK Down duration by 2 turns, barriers this character''s orb for 1 PERFECT hit, and applies Territory: [INT] to the field for 1 turn.","specialNotes":null,"superSpecialText":null,"superSpecialCriteriaText":null,"superSpecialNotes":null,"superSpecialCriteria":null,"partyConflictKeys":["dr. vegapunk","vegapunk"],"characterTags":["Vegapunk","Scientist","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_despair","label":"Remove Despair","minTurns":2,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_atk_down","label":"Remove ATK Down","minTurns":1,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_atk_down","l