      INSERT INTO character_details (character_id, detail_json)
      VALUES (4556, '{"characterId":4556,"captainAbility":"Launches the following effects at start of fight: sets Special Launch Status to (1), and reduces Switch Effect of all characters by 6. Boosts ATK of Fighter characters by 5x, by 5.75x instead if HP is above 99% or below 25% at the start of the turn, boosts HP of Fighter characters by 1.5x, makes [DEX] and [RCV] orbs beneficial for Fighter characters, and increases duration of any ATK Up buffs applied by specials by 2 turns.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effects at start of fight: sets Special Launch Status to (1), and reduces Switch Effect of all characters by 6. Boosts ATK of Fighter characters by 5x, by 5.75x instead if HP is above 99% or below 25% at the start of the turn, boosts HP of Fighter characters by 1.5x, makes [DEX] and [RCV] orbs beneficial for Fighter characters, and increases duration of any ATK Up buffs applied by specials by 2 turns."}],"captainNotes":null,"specialName":"Enemy-Clearing Flame","specialText":"Ignores Debuff Protection and inflicts all enemies with Burn that will deal 100x enemies'' ATK in damage for 1 turn, reduces Bind duration by 6 turns, and boosts ATK of Fighter characters by 3x, can be enhanced up to 2 times, for 3 turns. If HP is above 10% and Special Launch Status is (1) when the special is activated, reduces enemies'' Increased Defense duration by 6 turns, reduces Special Cooldown of this character by 13 turns, and sets Special Launch Status to (2). If HP is below 10% or Special Launch Status is (2) when the special is activated, changes all non-[DEX] orbs, including [BLOCK] orbs, into [DEX] orbs, boosts ATK against enemies inflicted with Burn by 2.25x for 1 turn, and reduces Special Cooldown of bottom row characters by 3 turns.","specialNotes":null,"superSpecialText":"Applies Territory: [DEX] to the field for 2 turns, adds 50x character''s ATK as Additional Typeless Damage for 5 turns, boosts Chain Multiplier Growth Rate by 1.5x for 3 turns, sets Special Launch Status to (1), and transforms [DEX] characters into Super [DEX] characters.","superSpecialCriteriaText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: Monkey D. Luffy, Sabo, Monkey D. Garp, Curly Dadan, Makino, Leonero, Skull, Mihal, Ganryu, Kotatsu, Cornelia, Yamato, Kaido, Charlotte Linlin (Big Mom), Shanks, Edward Newgate (Whitebeard)","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"Can be launched as crewmate. Your crew must consist of any 3 of the following, excluding supports and counting only 1 per unit: Monkey D. Luffy, Sabo, Monkey D. Garp, Curly Dadan, Makino, Leonero, Skull, Mihal, Ganryu, Kotatsu, Cornelia, Yamato, Kaido, Charlotte Linlin (Big Mom), Shanks, Edward Newgate (Whitebeard)","requiresCaptain":false,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":3,"matchMode":"unique_options","options":[{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Sabo","acceptedKeys":["sabo"]},{"label":"Monkey D. Garp","acceptedKeys":["monkey d garp","garp"]},{"label":"Curly Dadan","acceptedKeys":["curly dadan","dadan"]},{"label":"Makino","acceptedKeys":["makino"]},{"label":"Leonero","acceptedKeys":["leonero"]},{"label":"Skull","acceptedKeys":["skull"]},{"label":"Mihal","acceptedKeys":["mihal"]},{"label":"Ganryu","acceptedKeys":["ganryu"]},{"label":"Kotatsu","acceptedKeys":["kotatsu"]},{"label":"Cornelia","acceptedKeys":["cornelia"]},{"label":"Yamato","acceptedKeys":["yamato"]},{"label":"Kaido","acceptedKeys":["kaido"]},{"label":"Charlotte Linlin (Big Mom)","acceptedKeys":["charlotte linlin big mom","charlotte linlin","big mom","linlin"]},{"label":"Shanks","acceptedKeys":["shanks"]},{"label":"Edward Newgate (Whitebeard)","acceptedKeys":["edward newgate whitebeard","edward newgate","whitebeard","newgate"]}]}],"hasNonRosterBranches":false,"parse