e, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, Kuzan (Aokiji), Monkey D. Luffy, Shanks, Buggy, Gol D. Roger","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. Your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: Jesus Burgess (Mr. Store), Shiryu, Van Ogre, Avalo Pizarro, Lafitte, Catarina Devon, San Juan Wolf, Vasco Shot, Doc Q, Kuzan (Aokiji), Monkey D. Luffy, Shanks, Buggy, Gol D. Roger","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"Jesus Burgess (Mr. Store)","acceptedKeys":["jesus burgess mr store","jesus burgess","mr store","burgess"]},{"label":"Shiryu","acceptedKeys":["shiryu"]},{"label":"Van Ogre","acceptedKeys":["van ogre","ogre"]},{"label":"Avalo Pizarro","acceptedKeys":["avalo pizarro","pizarro"]},{"label":"Lafitte","acceptedKeys":["lafitte"]},{"label":"Catarina Devon","acceptedKeys":["catarina devon","devon"]},{"label":"San Juan Wolf","acceptedKeys":["san juan wolf","wolf"]},{"label":"Vasco Shot","acceptedKeys":["vasco shot","shot"]},{"label":"Doc Q","acceptedKeys":["doc q"]},{"label":"Kuzan (Aokiji)","acceptedKeys":["kuzan aokiji","kuzan","aokiji"]},{"label":"Monkey D. Luffy","acceptedKeys":["monkey d luffy","luffy"]},{"label":"Shanks","acceptedKeys":["shanks"]},{"label":"Buggy","acceptedKeys":["buggy"]},{"label":"Gol D. Roger","acceptedKeys":["gol d roger","roger"]}]}],"hasNonRosterBranches":false,"parserStatus":"roster_only"},"partyConflictKeys":["blackbeard","marshall d teach"],"characterTags":["Blackbeard Pirates","Four Emperors","Worst Generation","Logia-type","Paramythia-type","Egghead Arc"],"builderAbilities":[{"key":"remove_enemy_increased_defense","label":"Remove Increased Defense","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_enemy_barrie