      INSERT INTO character_details (character_id, detail_json)
      VALUES (4571, '{"characterId":4571,"captainAbility":"Launches the following effect at start of fight: reduces Special Cooldown of Cost 70 or more characters by 34% of Max Cooldown (rounded down), reduces VS Gauge and Switch Effect of all characters by 3, and allows all characters to perform Super Tandem with [STR] orbs for 10 turns. Boosts ATK of Cost 70 or more characters by 6x, boosts ATK of all other characters by 4x, boosts HP of all characters by 1.5x, and reduces Bind, Despair, Paralysis and Special Bind duration completely on this character. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of Cost 70 or more characters by 6.5x instead. If field has Territory: Crew, makes all specials that apply Class or Type restricted buffs apply to all characters instead. Special Captain Ability: If this character begins a quest as Captain, allows crew to immediately clear certain quests 6 times per day.","captainAbilityVariants":[{"key":"captain","label":"Captain Ability","text":"Launches the following effect at start of fight: reduces Special Cooldown of Cost 70 or more characters by 34% of Max Cooldown (rounded down), reduces VS Gauge and Switch Effect of all characters by 3, and allows all characters to perform Super Tandem with [STR] orbs for 10 turns. Boosts ATK of Cost 70 or more characters by 6x, boosts ATK of all other characters by 4x, boosts HP of all characters by 1.5x, and reduces Bind, Despair, Paralysis and Special Bind duration completely on this character. If this character is your Captain and performs EXCELLENT with their Action Special, for 3 turns boosts ATK of Cost 70 or more characters by 6.5x instead. If field has Territory: Crew, makes all specials that apply Class or Type restricted buffs apply to all characters instead. Special Captain Ability: If this character begins a quest as Captain, allows crew to immediately clear certain quests 6 times per day."}],"captainNotes":"Special Captain Ability effect is limited to Main Story and Event quests with difficulty 6 stars or less.","specialName":"Punishing the Intruder","specialText":"If this character is your Captain or Friend Captain, reduces enemies'' positive buffs duration by 1 turn. Applies Territory: Crew to the field for 3 turns, and launches the following effects depending on the Special Launch Status of this character when the special is activated: (0) Reduces Special Cooldown of all characters by 2 turns, reduces Special Bind duration by 10 turns, and sets Chain Boundaries to 3.5x-5.0x and 50.0x for 3 turns depending on the outcome of Action Special. (1) Reduces Paralysis and Burn duration by 10 turns, decreases boost effects of ATK Up buffs by -1.0x and converts ATK Up into a Stackable ATK Up, boosts ATK of Cost 70 or more characters by 3.5x-5x for 3 turns depending on the outcome of Action Special, and sets Special Launch Status to (0).","specialNotes":". Chain Boundary: MISS: 3.5x, GOOD: 4.0x, GREAT: 4.5x, PERFECT: 4.75x, EXCELLENT 5.0x. ATK: MISS: 3.5x, GOOD: 4.0x, GREAT: 4.5x, PERFECT: 4.75x, EXCELLENT 5.0x","superSpecialText":"Reduces enemies'' Percent Damage Reduction and Threshold Damage Reduction duration by 5 turns, changes all orbs, including [BLOCK] orbs, into matching orbs, reduces damage received by 80% for 1 turn, increases boost effects of Color Affinity buffs by 1.5x (up to 20x), sets Special Launch Status to (1), and transforms [STR], [DEX], [QCK], [PSY] and [INT] characters into Super [STR], Super [DEX], Super [QCK], Super [PSY] and Super [INT] characters.","superSpecialCriteriaText":"This character must be captain. If your crew has an ATK Up or Orb Amplification buff with an effect of 8x or more or your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: St. Topman Warcury, St. Ethanbaron V. Nusjuro, St. Jaygarcia Saturn, St. Shepherd Ju Peter, St. Marcus Mars, St. Figarland Garling, Saint Roswald, Saint Charlos, Saint Shalria, Saint Donquixote Myosgard","superSpecialNotes":null,"superSpecialCriteria":{"rawText":"This character must be captain. If your crew has an ATK Up or Orb Amplification buff with an effect of 8x or more or your crew must consist of any 2 of the following, excluding supports and counting only 1 per unit: St. Topman Warcury, St. Ethanbaron V. Nusjuro, St. Jaygarcia Saturn, St. Shepherd Ju Peter, St. Marcus Mars, St. Figarland Garling, Saint Roswald, Saint Charlos, Saint Shalria, Saint Donquixote Myosgard","requiresCaptain":true,"excludesSelf":false,"rosterBranches":[{"branchType":"character_count_any","requiredCount":2,"matchMode":"unique_options","options":[{"label":"St. Topman Warcury","acceptedKeys":["st topman warcury","warcury"]},{"label":"St. Ethanbaron V. Nusjuro","acceptedKeys":["st ethanbaron v nusjuro","nusjuro"]},{"label":"St. Jaygarcia Saturn","acceptedKeys":["st jaygarcia saturn","saturn"]},{"label":"St. Shepherd Ju Peter","acceptedKeys":["st shepherd ju peter","peter"]},{"label":"St. Marcus Mars","acceptedKeys":["st marcus mars","mars"]},{"label":"St. Figarland Garling","acceptedKeys":["st figarland garling","garling"]},{"label":"Saint Roswald","acceptedKeys":["saint roswald","roswald"]},{"label":"Saint Charlos","acceptedKeys":["saint charlos","charlos"]},{"label":"Saint Shalria","acceptedKeys":["saint shalria","shalria"]},{"label":"Saint Donquixote Myosgard","acceptedKeys":["saint donquixote myosgard","myosgard"]}]}],"hasNonRosterBranches":true,"parserStatus":"mixed"},"partyConflictKeys":["imu"],"characterTags":["World Government","Celestial Dragon","Egghead Arc"],"builderAbilities":[{"key":"remove_special_bind","label":"Remove Special Bind","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_paralysis","label":"Remove Paralysis","minTurns":10,"isCompleteRemoval":false,"slotTokens":[],"source":"specialText","coverageMode":"explicit"},{"key":"remove_burn","label":"Remove Burn","minTurns":10